    def _find_next_short_end(self, ref_dt, limit_minutes):
        end_boundary = ref_dt + timedelta(minutes=limit_minutes)
        query = f"""
            SELECT timestamp
            FROM crypto_data.shifted_points
            WHERE timeframe = '{self.timeframe}'
              AND timestamp >= '{ref_dt.strftime('%Y-%m-%d %H:%M:%S')}'
              AND timestamp <= '{end_boundary.strftime('%Y-%m-%d %H:%M:%S')}'
              AND shift_type = 'short_end'
            ORDER BY timestamp
            LIMIT 1
        """
        rows = self._client.execute(query)
        if not rows:
            return None, None
        ts = rows[0][0]
