class LimbDSMAnalyzer:
    """Анализатор конечностей (ХВОСТ/УСЫ/ОРГАН) по методу DCM"""
    
    def __init__(self, results_table, timeframe_manager):
        self.results_table = results_table
        self.timeframe_manager = timeframe_manager
        self.limb_analysis_file = "LIMB_ANALYSIS_DATA.json"
        self.limb_data = self.load_limb_data()
        
        # Загружаем GROUP_TIMES_DATA.json для доступа к реальным датам групп
        self.group_times_data = self.load_group_times_data()
        
        # Константы DCM (как в оригинале, всё в секундах)
        self.TF_15 = 15 * 60   # 900 секунд
        self.TF_30 = 30 * 60   # 1800 секунд
        self.TF_1 = 60 * 2.3333     # -60 секунд
        
        # Таймфреймы для усреднения
        self.avg_timeframes = ['30m', '1h', '4h']
    
    def load_group_times_data(self):
        """Загружает GROUP_TIMES_DATA.json для доступа к датам групп"""
        if os.path.exists("GROUP_TIMES_DATA.json"):
            try:
                with open("GROUP_TIMES_DATA.json", 'r', encoding='utf-8') as f:
                    return json.load(f)
            except:
                return {}
        return {}
    
    def load_limb_data(self):
        """Загружает сохранённые анализы конечностей"""
        if os.path.exists(self.limb_analysis_file):
            try:
                with open(self.limb_analysis_file, 'r', encoding='utf-8') as f:
                    return json.load(f)
            except:
                return {"last_update": "", "limb_analysis": {}}
        return {"last_update": "", "limb_analysis": {}}
    
    def save_limb_data(self):
        """Сохраняет анализы конечностей"""
        try:
            self.limb_data["last_update"] = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            with open(self.limb_analysis_file, 'w', encoding='utf-8') as f:
                json.dump(self.limb_data, f, indent=2, ensure_ascii=False)
            return True
        except Exception as e:
            print(f"[LIMB_DCM] Ошибка сохранения: {e}")
            return False
    
    def get_averaged_time_for_group(self, position_id, group_key):
        """
        Получает усреднённое время для группы по всем таймфреймам.
        group_key: 'group5_times', 'group6_times' и т.д.
        Возвращает timestamp в секундах или None.
        """
        times = []
        group_data = self.group_times_data.get(group_key, {})
        
        for tf in self.avg_timeframes:
            tf_data = group_data.get(tf, {})
            time_str = tf_data.get(str(position_id))
            if time_str:
                try:
                    dt = datetime.strptime(time_str, '%Y-%m-%d %H:%M:%S')
                    times.append(dt.timestamp())
                except:
                    pass
        
        if not times:
            return None
        
        return sum(times) / len(times)
    
    def get_limb_times(self, position_id, limb_type):
        """
        Возвращает (start_sec, end_sec) для указанной конечности.
        limb_type: 'hvost', 'usy', 'organ'
        """
        if limb_type == 'hvost':
            group1_key = 'group1_times'
            group2_key = 'group2_times'
        elif limb_type == 'usy':
            group1_key = 'group3_times'
            group2_key = 'group4_times'
        elif limb_type == 'organ':
            group1_key = 'group5_times'
            group2_key = 'group6_times'
        else:
            return None, None
        
        start_sec = self.get_averaged_time_for_group(position_id, group1_key)
        end_sec = self.get_averaged_time_for_group(position_id, group2_key)
        
        return start_sec, end_sec
    
    def calculate_dcm_from_seconds(self, start_sec, end_sec):
        """
        Оригинальная формула DCM, работающая с секундами.
        Возвращает (dog_sec, cat_sec, manul_sec).
        """
        if start_sec is None or end_sec is None:
            return None, None, None
        
        idx1 = start_sec
        idx2 = end_sec
        
        # ========== ОРИГИНАЛЬНЫЙ DCM (калька с DCMResultsManager) ==========
        FirstTimeGAS3 = idx2 + (idx2 - idx1)
        
        FirstGasCorrect15 = idx1 + self.TF_15
        FirstFakeGAS15diff = abs(FirstTimeGAS3 - FirstGasCorrect15) / 2
        FirstFakeGAS15 = FirstTimeGAS3 + self.TF_1 + FirstFakeGAS15diff
        
        FirstGasCorrect30 = idx1 + self.TF_30
        FirstGas30diff = abs(FirstTimeGAS3 - FirstGasCorrect30) / 2
        FirstGas30 = FirstTimeGAS3 + self.TF_1 + FirstGas30diff
        
        FirstGas23diff = (FirstGas30 - FirstFakeGAS15) / 2
        FirstGas23 = round(FirstFakeGAS15 + FirstGas23diff)
        
        # Эхо-расчёт
        FirstTimeGAS4 = FirstTimeGAS3 + (FirstTimeGAS3 - idx1)
        FirstMiddleGAS = FirstTimeGAS3 + (FirstTimeGAS3 - idx2)
        
        FirstEchoGASdiff15 = abs(FirstMiddleGAS - FirstGasCorrect15) / 2
        FirstEchoGAS15 = FirstTimeGAS4 + FirstEchoGASdiff15
        
        FirstEchoGASdiff30 = abs(FirstMiddleGAS - FirstGasCorrect30) / 2
        FirstEchoGAS30 = FirstTimeGAS4 + FirstEchoGASdiff30
        
        FirstEchoGASdiff23 = (FirstEchoGAS30 - FirstEchoGAS15) / 2
        FirstEchoGAS23 = round(FirstEchoGAS15 + FirstEchoGASdiff23)
        
        FirstFinalGASdiff23 = (FirstEchoGAS23 - FirstGas23) / 2
        FirstFinalGAS23 = round(FirstGas23 + FirstFinalGASdiff23)
        
        FirstEndGASdiff = abs(FirstEchoGAS23 - FirstFinalGAS23) / 2
        FirstEndGAS = round(FirstFinalGAS23 + FirstEndGASdiff)
        
        FirstEndGASdiff19 = abs(FirstFinalGAS23 - FirstGas23) / 2
        FirstEndGAS19 = round(FirstGas23 + FirstEndGASdiff19)
        
        # ========== РЕЗУЛЬТАТЫ ==========
        dog_sec = FirstEndGAS19
        cat_sec = FirstEndGAS
        manul_sec = FirstFinalGAS23
        
        return dog_sec, cat_sec, manul_sec
    
    def analyze_id_limb(self, position_id, limb_type, force_recalc=False):
        """
        Анализирует одну конечность одного ID.
        Использует реальные даты из GROUP_TIMES_DATA.json и оригинальный DCM.
        """
        # Проверяем кэш
        id_str = str(position_id)
        if not force_recalc and id_str in self.limb_data.get("limb_analysis", {}):
            if limb_type in self.limb_data["limb_analysis"][id_str]:
                cached = self.limb_data["limb_analysis"][id_str][limb_type]
                if cached.get("status") == "calculated":
                    return cached
        
        # Получаем реальные времена для конечности
        start_sec, end_sec = self.get_limb_times(position_id, limb_type)
        
        if start_sec is None or end_sec is None:
            print(f"[LIMB_DCM] ID {position_id}, {limb_type}: нет данных в GROUP_TIMES_DATA.json")
            return None
        
        # Оригинальный DCM
        dog_sec, cat_sec, manul_sec = self.calculate_dcm_from_seconds(start_sec, end_sec)
        
        if dog_sec is None:
            return None
        
        # Конвертируем секунды в минуты для хранения (как в твоём файле)
        start_min = start_sec / 60.0
        end_min = end_sec / 60.0
        original_dog_min = (end_sec - start_sec) / 60.0
        
        # Определяем знак для ОРГАНА (если start > end, то отрицательный)
        limb_sign = '+'
        if limb_type == 'organ' and start_sec > end_sec:
            limb_sign = '-'
            # Для отрицательного сигнала меняем знак у прогнозов
            # (в DCM они всегда положительные, но если конечность перевёрнута, то и прогноз переворачиваем)
            dog_sec = -dog_sec
            cat_sec = -cat_sec
            manul_sec = -manul_sec
        
        # Сохраняем результат
        analysis_data = {
            "start_sec": start_sec,
            "end_sec": end_sec,
            "start_min": start_min,
            "end_min": end_min,
            "sign": limb_sign,
            "dcm_prediction": {
                "dog": dog_sec / 60.0,      # минуты (как в твоём файле)
                "cat": cat_sec / 60.0,
                "manul": manul_sec / 60.0
            },
            "original_dog": original_dog_min,
            "status": "calculated",
            "last_calculation": datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        }
        
        # Обновляем кэш
        if id_str not in self.limb_data["limb_analysis"]:
            self.limb_data["limb_analysis"][id_str] = {}
        self.limb_data["limb_analysis"][id_str][limb_type] = analysis_data
        self.save_limb_data()
        
        return analysis_data
    
    def analyze_all_limbs_for_id(self, position_id, force_recalc=False):
        """Анализирует все три конечности для одного ID"""
        result = {}
        for limb_type in ['hvost', 'usy', 'organ']:
            result[limb_type] = self.analyze_id_limb(position_id, limb_type, force_recalc)
        return result
    
    def analyze_all_ids(self, progress_callback=None):
        """Анализирует все конечности всех ID"""
        row_count = self.results_table.rowCount()
        analyzed = 0
        
        for row in range(row_count):
            id_item = self.results_table.item(row, 0)
            if not id_item or not id_item.text().strip():
                continue
            
            try:
                position_id = int(id_item.text())
                self.analyze_all_limbs_for_id(position_id, force_recalc=True)
                analyzed += 1
                
                if progress_callback:
                    progress_callback(row + 1, row_count)
                    
            except Exception as e:
                print(f"[LIMB_DCM] Ошибка для ID {id_item.text()}: {e}")
                continue
        
        return analyzed
    
    def get_row_by_id(self, position_id):
        """Возвращает индекс строки по ID"""
        for row in range(self.results_table.rowCount()):
            item = self.results_table.item(row, 0)
            if item and item.text() == str(position_id):
                return row
        return None

class ImpulseStatisticsWorker(QtCore.QThread):
    progress_signal = QtCore.pyqtSignal(int, int)
    finished_signal = QtCore.pyqtSignal(dict)
    error_signal = QtCore.pyqtSignal(str)
    log_signal = QtCore.pyqtSignal(str)

    def __init__(self, ch_manager, timeframe, start_dt, end_dt, limit, timestamps, highs, lows, closes):
        super().__init__()
        self.ch_manager = ch_manager
        self.timeframe = timeframe
        self.start_dt = start_dt
        self.end_dt = end_dt
        self.limit = limit
        self.timestamps = timestamps
        self.highs = highs
        self.lows = lows
        self.closes = closes
        self._is_running = True
        self._logged_ids = set()
        # Параметры для параллельной обработки
        self.batch_size = 10000   # кол-во ID в одном чанке
        self.workers = 8          # число потоков

    def stop(self):
        self._is_running = False

    def run(self):
        try:
            if len(self.timestamps) == 0:
                self.error_signal.emit("Нет данных графика для указанного таймфрейма")
                return

            min_ts = self.timestamps[0]
            max_ts = self.timestamps[-1]
            min_dt = datetime.fromtimestamp(min_ts / 1000.0)
            max_dt = datetime.fromtimestamp(max_ts / 1000.0)
            self.log_signal.emit(f"Доступный диапазон данных: {min_dt} – {max_dt}")

            # Загружаем ID
            query = f"""
                SELECT id, start_time, end_time, direction
                FROM crypto_data.auto_ids
                WHERE timeframe = '{self.timeframe}'
                  AND start_time >= '{min_dt.strftime('%Y-%m-%d %H:%M:%S')}'
                  AND end_time <= '{max_dt.strftime('%Y-%m-%d %H:%M:%S')}'
                  AND start_time >= '{self.start_dt.strftime('%Y-%m-%d %H:%M:%S')}'
                  AND end_time <= '{self.end_dt.strftime('%Y-%m-%d %H:%M:%S')}'
                LIMIT {self.limit}
            """
            rows = self.ch_manager.client.execute(query)
            total = len(rows)
            self.log_signal.emit(f"Загружено {total} ID для обработки (в диапазоне данных)")

            if total == 0:
                self.finished_signal.emit({'total': 0})
                return

            # Подготовка данных для быстрого поиска
            ts_list = self.timestamps / 1000.0   # numpy массив
            ts_to_idx = {ts: i for i, ts in enumerate(ts_list.tolist())}

            # Разбиваем на чанки
            id_chunks = [rows[i:i+self.batch_size] for i in range(0, total, self.batch_size)]
            self.log_signal.emit(f"Разбито на {len(id_chunks)} чанков, потоков: {self.workers}")

            # Общая статистика (с блокировкой)
            from threading import Lock
            stats_lock = Lock()
            stats = {'total': total, 'type0': 0, 'type1': 0, 'type2': 0, 'type3': 0,
                     'type4': 0, 'type5': 0, 'type6': 0, 'type7': 0, 'type8': 0,
                     'subtypes': {'normal': 0, 'short-anomaly': 0, 'long-anomaly': 0},
                     'directions': {'long': 0, 'short': 0},
                     'skipped_empty': 0,
                     'sample_ids': {'type': {}, 'subtype': {}, 'direction': {}}}
            processed = 0

            from concurrent.futures import ThreadPoolExecutor, as_completed
            import time
            start_time = time.time()

            with ThreadPoolExecutor(max_workers=self.workers) as executor:
                futures = []
                for chunk in id_chunks:
                    if not self._is_running:
                        break
                    futures.append(executor.submit(
                        self._process_chunk,
                        chunk, ts_list, ts_to_idx, stats, stats_lock
                    ))

                for future in as_completed(futures):
                    if not self._is_running:
                        break
                    try:
                        chunk_stats = future.result(timeout=300)
                        # Обновляем общую статистику (уже сделано внутри с блокировкой)
                        processed += len(chunk_stats.get('ids_processed', 0))
                        self.progress_signal.emit(processed, total)
                        self.log_signal.emit(f"Обработано {processed}/{total} ID")
                    except Exception as e:
                        self.log_signal.emit(f"Ошибка в потоке: {str(e)}")

            elapsed = time.time() - start_time
            self.log_signal.emit(f"Обработка завершена за {elapsed:.2f} сек. Всего: {total}, пропущено из-за пустых списков: {stats['skipped_empty']}")
            self.finished_signal.emit(stats)

        except Exception as e:
            self.error_signal.emit(str(e))
            import traceback
            self.log_signal.emit(traceback.format_exc())

    def _process_chunk(self, chunk, ts_list, ts_to_idx, stats, stats_lock):
        """
        Обрабатывает один чанк ID, обновляет общую статистику.
        Возвращает словарь с числом обработанных ID (для прогресса).
        """
        import numpy as np
        import bisect
        from datetime import datetime

        processed_ids = []
        chunk_stats = {'ids_processed': []}

        # Локальные ссылки для ускорения
        highs = self.highs
        lows = self.lows
        closes = self.closes

        for row in chunk:
            if not self._is_running:
                break
            id_val, start_dt, end_dt, direction = row
            try:
                start_ts = start_dt.timestamp()
                end_ts = end_dt.timestamp()

                # ---- БЫСТРЫЙ ПОИСК ИНДЕКСОВ С NUMPY ----
                left = ts_to_idx.get(start_ts)
                if left is None:
                    left = np.searchsorted(ts_list, start_ts, side='left')
                    if left >= len(ts_list):
                        left = len(ts_list) - 1
                    elif abs(ts_list[left] - start_ts) > 1:
                        left = np.searchsorted(ts_list, start_ts, side='right') - 1

                right = ts_to_idx.get(end_ts)
                if right is None:
                    right = np.searchsorted(ts_list, end_ts, side='right') - 1
                    if right < 0:
                        right = 0
                    elif abs(ts_list[right] - end_ts) > 1:
                        right = np.searchsorted(ts_list, end_ts, side='left')

                if left < 0:
                    left = 0
                if right >= len(ts_list):
                    right = len(ts_list) - 1

                if right - left < 4:
                    with stats_lock:
                        stats['type0'] += 1
                        if 0 not in stats['sample_ids']['type']:
                            stats['sample_ids']['type'][0] = id_val
                    processed_ids.append(id_val)
                    continue

                # ---- ФОРМИРУЕМ ИНДЕКСЫ (как в оригинале) ----
                if direction == 'long':
                    first3_indices = list(range(left+1, min(left+4, len(ts_list))))
                    rest_after_first = list(range(left+4, right+1))
                    last3_indices = list(range(max(left+1, right-2), right+1))
                    rest_before_last = list(range(left+1, max(left+1, right-2)))
                else:
                    last3_indices = list(range(max(left+1, right-3), right))
                    rest_before_last = list(range(left+1, right-3))
                    first3_indices = list(range(left+1, min(left+4, len(ts_list))))
                    rest_after_first = list(range(left+4, right+1))

                if (len(first3_indices) == 0 or len(rest_after_first) == 0 or
                    len(last3_indices) == 0 or len(rest_before_last) == 0):
                    with stats_lock:
                        stats['type0'] += 1
                        stats['skipped_empty'] += 1
                        if 0 not in stats['sample_ids']['type']:
                            stats['sample_ids']['type'][0] = id_val
                    processed_ids.append(id_val)
                    continue

                # ---- ВЫЧИСЛЕНИЕ ЭКСТРЕМУМОВ (векторизовано) ----
                max_high_first3 = np.max(highs[first3_indices])
                max_close_first3 = np.max(closes[first3_indices])
                min_low_first3 = np.min(lows[first3_indices])
                min_close_first3 = np.min(closes[first3_indices])

                max_high_rest_after = np.max(highs[rest_after_first])
                max_close_rest_after = np.max(closes[rest_after_first])
                min_low_rest_after = np.min(lows[rest_after_first])
                min_close_rest_after = np.min(closes[rest_after_first])

                max_high_last3 = np.max(highs[last3_indices])
                max_close_last3 = np.max(closes[last3_indices])
                min_low_last3 = np.min(lows[last3_indices])
                min_close_last3 = np.min(closes[last3_indices])

                max_high_rest_before = np.max(highs[rest_before_last])
                max_close_rest_before = np.max(closes[rest_before_last])
                min_low_rest_before = np.min(lows[rest_before_last])
                min_close_rest_before = np.min(closes[rest_before_last])

                # ---- КОРРЕКТИРОВКА ДЛЯ LONG И SHORT (как в оригинале) ----
                if direction == 'long':
                    min_low_first3 = min_low_rest_before
                    min_close_first3 = min_close_rest_before
                    min_low_rest_after = min_low_last3
                    min_close_rest_after = min_close_last3
                    start_idx = np.searchsorted(ts_list, start_ts, side='left')
                    if start_idx < len(ts_list) and abs(ts_list[start_idx] - start_ts) > 1:
                        start_idx = left
                    first_close_indices = [start_idx + i for i in range(3) if start_idx + i < len(closes)]
                    if first_close_indices:
                        max_close_first3 = np.max(closes[first_close_indices])
                    first_high_indices = [start_idx + i for i in range(3) if start_idx + i < len(highs)]
                    if first_high_indices:
                        max_high_first3 = np.max(highs[first_high_indices])
                else:  # short
                    max_high_first3 = max_high_rest_before
                    max_close_first3 = max_close_rest_before
                    max_high_rest_after = max_high_last3
                    max_close_rest_after = max_close_last3
                    start_idx = np.searchsorted(ts_list, start_ts, side='left')
                    if start_idx < len(ts_list) and abs(ts_list[start_idx] - start_ts) > 1:
                        start_idx = left
                    first_low_indices = [start_idx + i for i in range(3) if start_idx + i < len(lows)]
                    if first_low_indices:
                        min_low_first3 = np.min(lows[first_low_indices])
                    first_close_indices_short = [start_idx + i for i in range(3) if start_idx + i < len(closes)]
                    if first_close_indices_short:
                        min_close_first3 = np.min(closes[first_close_indices_short])

                # ---- КЛАССИФИКАЦИЯ ТИПА ----
                impulse_type = 0
                if direction == 'long':
                    if (min_close_rest_after < min_close_first3) and (max_close_rest_after > max_close_first3):
                        impulse_type = 1
                    elif (min_close_first3 < min_close_rest_after) and (max_close_first3 > max_close_rest_after):
                        impulse_type = 2
                    elif (min_close_first3 < min_close_rest_after) and (max_close_rest_after > max_close_first3):
                        impulse_type = 3
                    elif (min_close_rest_after < min_close_first3) and (max_close_first3 > max_close_rest_after):
                        impulse_type = 7
                    else:
                        impulse_type = 0
                else:
                    if (min_close_first3 < min_close_rest_after) and (max_close_first3 > max_close_rest_after):
                        impulse_type = 4
                    elif (min_close_rest_after < min_close_first3) and (max_close_rest_after > max_close_first3):
                        impulse_type = 5
                    elif (min_close_rest_after < min_close_first3) and (max_close_first3 > max_close_rest_after):
                        impulse_type = 6
                    elif (min_close_first3 < min_close_rest_after) and (max_close_rest_after > max_close_first3):
                        impulse_type = 8
                    else:
                        impulse_type = 0

                # ---- ПОДТИП (ПРАВИЛЬНАЯ ЛОГИКА) ----
                start_price = closes[left] if left < len(closes) else 0
                end_price = closes[right] if right < len(closes) else 0
                subtype = ''
                if direction == 'short' and end_price < start_price:
                    subtype = 'short-anomaly'
                elif direction == 'long' and end_price > start_price:
                    subtype = 'long-anomaly'
                else:
                    subtype = 'normal'

                # ---- ОБНОВЛЕНИЕ СТАТИСТИКИ (с блокировкой) ----
                with stats_lock:
                    stats[f'type{impulse_type}'] = stats.get(f'type{impulse_type}', 0) + 1
                    stats['subtypes'][subtype] = stats['subtypes'].get(subtype, 0) + 1
                    stats['directions'][direction] = stats['directions'].get(direction, 0) + 1
                    if impulse_type not in stats['sample_ids']['type']:
                        stats['sample_ids']['type'][impulse_type] = id_val
                    if subtype not in stats['sample_ids']['subtype']:
                        stats['sample_ids']['subtype'][subtype] = id_val
                    if direction not in stats['sample_ids']['direction']:
                        stats['sample_ids']['direction'][direction] = id_val

                processed_ids.append(id_val)

            except Exception as e:
                with stats_lock:
                    stats['errors'] = stats.get('errors', 0) + 1
                self.log_signal.emit(f"Ошибка ID {id_val}: {str(e)}")
                processed_ids.append(id_val)

        # Возвращаем количество обработанных ID (для прогресса)
        return {'ids_processed': processed_ids}

class ClickHouseManager:
    def __init__(self, table_name='crypto_data.btc_usdt_1m'):
        # Сохраняем параметры подключения как атрибуты
        self.host = 'localhost'
        self.port = 9000
        self.user = 'default'
        self.password = ''
        self.settings = {
            'send_timeout': 600,
            'receive_timeout': 600,
            'insert_block_size': 1000,
            'connect_timeout': 30
        }

        self.client = None
        self.table_name = table_name
        self.connect()
        self.init_db()
        self.check_table()
        self.find_duplicates()
        self.auto_clean_duplicates()

    def ensure_qualifier_table(self):
        """Создаёт таблицу qualifier_lines, если её нет"""
        try:
            self.client.execute("""
                CREATE TABLE IF NOT EXISTS crypto_data.qualifier_lines (
                    timestamp DateTime,
                    timeframe String,
                    line_type String,   -- 'long_start', 'long_end', 'short_start', 'short_end'
                    price Float64
                ) ENGINE = MergeTree()
                ORDER BY (timeframe, timestamp)
            """)
            print("[QUALIFIER] Таблица crypto_data.qualifier_lines создана/проверена")
        except Exception as e:
            print(f"[QUALIFIER] Ошибка создания таблицы: {str(e)}")        
        
    def find_data_gaps(self):
        """Находит разрывы в минутных данных"""
        try:
            # Сначала получим все временные метки
            all_timestamps = self.client.execute(
                "SELECT timestamp FROM crypto_data.btc_usdt_1m ORDER BY timestamp"
            )
            if not all_timestamps:
                return []
            # Преобразуем в список datetime объектов
            timestamps = [row[0] for row in all_timestamps]
            # Находим разрывы
            gaps = []
            for i in range(1, len(timestamps)):
                prev = timestamps[i-1]
                curr = timestamps[i]
                diff_minutes = (curr - prev).total_seconds() / 60
                if diff_minutes > 1:
                    gaps.append((
                        prev.strftime('%Y-%m-%d %H:%M:%S'),  # gap_start
                        curr.strftime('%Y-%m-%d %H:%M:%S'),  # gap_end
                        diff_minutes                        # gap_minutes
                    ))
            # Сортируем по убыванию длительности разрыва
            return sorted(gaps, key=lambda x: x[2], reverse=True)
        except Exception as e:
            print(f"Ошибка поиска разрывов: {str(e)}")
            return []
    def auto_clean_duplicates(self):
        """Автоматическая очистка дубликатов при старте через временную таблицу"""
        try:
            # First, drop the temp table if it exists
            self.client.execute(f"DROP TABLE IF EXISTS {self.table_name}_temp")
        
            # Execute each statement separately
            self.client.execute(f"""
                CREATE TABLE {self.table_name}_temp AS {self.table_name}
                ENGINE = MergeTree()
                ORDER BY timestamp
            """)
        
            self.client.execute(f"""
                INSERT INTO {self.table_name}_temp
                SELECT DISTINCT * FROM {self.table_name}
            """)
        
            self.client.execute(f"DROP TABLE {self.table_name}")
        
            self.client.execute(f"""
                RENAME TABLE {self.table_name}_temp TO {self.table_name}
            """)
        
            print("Дубликаты успешно удалены через временную таблицу")
        except Exception as e:
            print(f"Ошибка автоматической очистки: {str(e)}")
            self.clean_duplicates_backup()

    def connect(self):
        try:
            self.client = ClickHouseClient(
                host=self.host,
                port=self.port,
                user=self.user,
                password=self.password,
                settings=self.settings
            )
            print("ClickHouse connection established")
            return True
        except Exception as e:
            print(f"ClickHouse connection error: {str(e)}")
            return False
        
    def find_duplicates(self):
        """Находит и подсчитывает дубликаты в таблице"""
        try:
            query = """
            SELECT 
                timestamp, 
                count() as total_count,
                count(DISTINCT (open, high, low, close, volume)) as unique_count
            FROM crypto_data.btc_usdt_1m
            GROUP BY timestamp
            HAVING total_count > unique_count
            ORDER BY total_count DESC
            """
            result = self.client.execute(query)
            if not result:
                print("Дубликаты не найдены")
                return []
            print(f"Найдено {len(result)} дубликатов:")
            for row in result:
                duplicates = row[1] - row[2]  # вычисляем количество дубликатов
                print(f"Timestamp: {row[0]}, Всего записей: {row[1]}, Уникальных: {row[2]}, Дубликатов: {duplicates}")
            return result
        except Exception as e:
            print(f"Ошибка поиска дубликатов: {str(e)}")
            return []

    def get_row_count(self):
        """Returns the number of rows in the minute data table"""
        try:
            result = self.client.execute("SELECT count() FROM crypto_data.btc_usdt_1m")
            return result[0][0] if result else 0
        except Exception as e:
            print(f"Error getting row count: {e}")
            return 0        
    def validate_row(self, row):
        """Проверка корректности данных строки"""
        try:
            if not all(key in row for key in ['timestamp', 'open', 'high', 'low', 'close', 'volume']):
                raise ValueError("Неполные данные в строке")
            int(row['timestamp'])  
            float(row['open'])
            float(row['high'])
            float(row['low'])
            float(row['close'])
            float(row['volume'])
            return True
        except Exception as e:
            print(f"Некорректные данные: {str(e)}")
            return False        
    def check_table(self):
        """Проверяет структуру и содержимое таблицы и выводит в лог"""
        if self.client is None:
            print("[CLICKHOUSE] Не подключено к серверу")
            return
        try:
            table_info = self.client.execute("DESCRIBE TABLE crypto_data.btc_usdt_1m")
            count = self.client.execute("SELECT count() FROM crypto_data.btc_usdt_1m")[0][0]
            print(f"[CLICKHOUSE] МИНУТЫ: {count}")
            sample_data = self.client.execute("""
                SELECT 
                    toString(timestamp) as ts,
                    open, high, low, close, volume 
                FROM crypto_data.btc_usdt_1m 
                LIMIT 1
            """)
        except Exception as e:
            print(f"[CLICKHOUSE ERROR] Ошибка проверки таблицы: {str(e)}")
            import traceback
            traceback.print_exc()
    def init_db(self):
        """Инициализация с защитой от дубликатов"""
        try:
            self.client.execute("""
                CREATE DATABASE IF NOT EXISTS crypto_data
            """)
            self.client.execute("""
                CREATE TABLE IF NOT EXISTS crypto_data.btc_usdt_1m (
                    timestamp DateTime,
                    open Float64,
                    high Float64,
                    low Float64,
                    close Float64,
                    volume Float64
                ) ENGINE = ReplacingMergeTree()
                ORDER BY timestamp
                SETTINGS 
                    index_granularity = 8192,
                    clean_deleted_rows = 'always'
            """)
        except Exception as e:
            print(f"Ошибка инициализации БД: {str(e)}")
            raise
    def _insert_batch(self, batch):
        """Вставка пакета данных с повторными попытками и правильными типами"""
        retries = 3
        for attempt in range(retries):
            try:
                if not self.client.connection.connected:
                    self.connect()
                self.client.execute(
                    "INSERT INTO crypto_data.btc_usdt_1m (timestamp, open, high, low, close, volume) VALUES",
                    batch,
                    types_check=True,
                    settings={
                        'input_format_allow_errors_num': 10,
                        'input_format_allow_errors_ratio': 0.1
                    }
                )
                time.sleep(0.1)  
                return
            except ch_errors.SocketTimeoutError:
                print(f"Таймаут соединения. Попытка {attempt+1}/{retries}")
                time.sleep(2)
                self.connect()
            except ch_errors.ServerException as e:
                if 'Code: 53' in str(e):  
                    print(f"Ошибка типа данных: {e}")
                    self._insert_batch_with_debug(batch)
                    return
                raise
        raise Exception("Не удалось вставить пакет после нескольких попыток")
    def _insert_batch_with_debug(self, batch):
        """Вставка с детальным логированием проблемных строк"""
        for i, row in enumerate(batch):
            try:
                self.client.execute(
                    "INSERT INTO crypto_data.btc_usdt_1m VALUES",
                    [row],
                    types_check=True
                )
            except Exception as e:
                print(f"Ошибка в строке {i}: {row}")
                print(f"Типы: {[type(x) for x in row]}")
                print(f"Ошибка: {e}")
                raise    
    def validate_timestamp(self, ts):
        """Validate timestamp in milliseconds"""
        try:
            ts_int = int(ts)
            if 946684800000 <= ts_int <= 4102444800000:  
                return ts_int
            return int(time.time() * 1000)  
        except:
            return int(time.time() * 1000)  
    def insert_candles(self, candles):
        """Надежная вставка свечей в ClickHouse с проверкой дубликатов"""
        if not candles:
            return False
        try:
            # Получаем существующие временные метки
            min_ts = datetime.fromtimestamp(candles[0][0]/1000)
            max_ts = datetime.fromtimestamp(candles[-1][0]/1000)
            existing = self.client.execute(
                "SELECT timestamp FROM crypto_data.btc_usdt_1m WHERE timestamp >= %(min)s AND timestamp <= %(max)s",
                {'min': min_ts, 'max': max_ts}
            )
            existing_ts = {row[0] for row in existing}

            # Фильтруем дубликаты
            data = []
            for candle in candles:
                ts = datetime.fromtimestamp(candle[0]/1000)
                if ts not in existing_ts:
                    data.append([
                        ts,
                        float(candle[1]),
                        float(candle[2]),
                        float(candle[3]),
                        float(candle[4]),
                        float(candle[5])
                    ])

            if not data:
                print("Все свечи уже существуют в базе")
                return True

            # Вставляем пачками
            batch_size = 1000
            for i in range(0, len(data), batch_size):
                batch = data[i:i + batch_size]
                self.client.execute(
                    "INSERT INTO crypto_data.btc_usdt_1m (timestamp, open, high, low, close, volume) VALUES",
                    batch
                )
            print(f"Успешно вставлено {len(data)} свечей")
            return True
        except Exception as e:
            print(f"Ошибка вставки свечей: {e}")
            return False

class GapFinderDialog(QtWidgets.QDialog):
    def __init__(self, ch_manager, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Поиск разрывов в минутных данных")
        self.setMinimumSize(800, 600)
        self.ch_manager = ch_manager
        layout = QtWidgets.QVBoxLayout(self)
        self.worker = None
        # Кнопка поиска
        self.btn_find = QtWidgets.QPushButton("Найти разрывы")
        self.btn_find.clicked.connect(self.find_gaps)
        layout.addWidget(self.btn_find)
        # Таблица с результатами
        self.table = QtWidgets.QTableWidget()
        self.table.setColumnCount(4)
        self.table.setHorizontalHeaderLabels(["Начало разрыва", "Конец разрыва", "Длительность (мин)", "Действия"])
        layout.addWidget(self.table)
        # Прогресс бар
        self.progress = QtWidgets.QProgressBar()
        self.progress.setVisible(False)
        layout.addWidget(self.progress)
        # Кнопка закрытия
        btn_close = QtWidgets.QPushButton("Закрыть")
        btn_close.clicked.connect(self.accept)
        layout.addWidget(btn_close)
    def find_gaps(self):
        """Запускает поиск разрывов и отображает результаты"""
        gaps = self.ch_manager.find_data_gaps()
        self.table.setRowCount(len(gaps))
        for i, (gap_start, gap_end, gap_minutes) in enumerate(gaps):
            self.table.setItem(i, 0, QtWidgets.QTableWidgetItem(str(gap_start)))
            self.table.setItem(i, 1, QtWidgets.QTableWidgetItem(str(gap_end)))
            self.table.setItem(i, 2, QtWidgets.QTableWidgetItem(str(gap_minutes)))
            # Кнопка для загрузки пропущенных данных
            btn_fetch = QtWidgets.QPushButton("Загрузить")
            btn_fetch.clicked.connect(lambda _, s=gap_start, e=gap_end: self.fetch_missing_data(s, e))
            self.table.setCellWidget(i, 3, btn_fetch)
        self.table.resizeColumnsToContents()
    def fetch_missing_data(self, start_dt, end_dt):
        try:
            # Проверяем, не выполняется ли уже загрузка
            if hasattr(self, 'worker') and self.worker and self.worker.isRunning():
                QtWidgets.QMessageBox.warning(self, "Внимание", "Загрузка уже выполняется")
                return
            start = datetime.strptime(start_dt, '%Y-%m-%d %H:%M:%S')
            end = datetime.strptime(end_dt, '%Y-%m-%d %H:%M:%S')
            self.worker = GapFillerWorker(self.ch_manager, start, end)
            self.worker.progress_signal.connect(self.update_progress)
            self.worker.finished_signal.connect(self.on_gap_filled)
            self.worker.error_signal.connect(self.on_gap_error)
            self.progress.setVisible(True)
            self.progress.setValue(0)
            self.btn_find.setEnabled(False)
            self.worker.start()
        except Exception as e:
            self.reset_ui()
            QtWidgets.QMessageBox.critical(self, "Ошибка", f"Не удалось начать загрузку: {str(e)}")
    def update_progress(self, value):
        """Обновляет прогресс бар"""
        self.progress.setValue(value)
    def on_gap_filled(self, message):
        """Обработка успешного завершения загрузки"""
        self.progress.setVisible(False)
        QtWidgets.QMessageBox.information(
            self, 
            "Успех", 
            message
        )
        # Обновляем список разрывов после загрузки
        self.find_gaps()
    def on_gap_error(self, error_msg):
        """Обработка ошибки загрузки"""
        self.progress.setVisible(False)
        QtWidgets.QMessageBox.critical(
            self, 
            "Ошибка", 
            error_msg
        )
    def reset_ui(self):
        """Восстановление UI после завершения/ошибки"""
        self.btn_find.setEnabled(True)
        self.progress.setVisible(False)
        if self.worker:
            if self.worker.isRunning():
                self.worker.stop()
                self.worker.wait(2000)  # Даем время на завершение
            self.worker = None
    def closeEvent(self, event):
        """При закрытии окна останавливаем worker"""
        self.reset_ui()
        event.accept()

class DcmDeduplicateWorker(QtCore.QThread):
    finished_signal = QtCore.pyqtSignal(str)
    error_signal = QtCore.pyqtSignal(str)
    status_signal = QtCore.pyqtSignal(str)

    def __init__(self, ch_client):
        super().__init__()
        self.ch_client = ch_client

    def run(self):
        try:
            self.status_signal.emit("Проверка дубликатов...")
            # Проверяем, есть ли дубликаты
            dup_query = """
                SELECT timeframe, id, count()
                FROM crypto_data.dcm_precomputed
                GROUP BY timeframe, id
                HAVING count() > 1
                LIMIT 1
            """
            dup_check = self.ch_client.execute(dup_query)
            if not dup_check:
                self.finished_signal.emit("Дубликатов не найдено.")
                return

            # Создаём временную таблицу без дубликатов
            self.status_signal.emit("Создание временной таблицы...")
            self.ch_client.execute("""
                CREATE TABLE IF NOT EXISTS crypto_data.dcm_precomputed_dedup
                ENGINE = MergeTree()
                ORDER BY (timeframe, id)
                AS
                SELECT timeframe, id, dog_time, cat_time, manul_time
                FROM crypto_data.dcm_precomputed
                WHERE (timeframe, id, dog_time) IN (
                    SELECT timeframe, id, MIN(dog_time)
                    FROM crypto_data.dcm_precomputed
                    GROUP BY timeframe, id
                )
            """)

            # Подсчитываем, сколько записей останется
            old_count = self.ch_client.execute("SELECT count() FROM crypto_data.dcm_precomputed")[0][0]
            new_count = self.ch_client.execute("SELECT count() FROM crypto_data.dcm_precomputed_dedup")[0][0]
            self.status_signal.emit(f"Было {old_count}, станет {new_count} (удалено {old_count - new_count})")

            # Заменяем таблицу
            self.status_signal.emit("Замена таблицы...")
            self.ch_client.execute("DROP TABLE crypto_data.dcm_precomputed")
            self.ch_client.execute("RENAME TABLE crypto_data.dcm_precomputed_dedup TO crypto_data.dcm_precomputed")

            self.finished_signal.emit(f"Дедупликация завершена. Удалено {old_count - new_count} дубликатов.")

        except Exception as e:
            self.error_signal.emit(str(e))
        
class GapFillerWorker(QtCore.QThread):
    progress_signal = QtCore.pyqtSignal(int)
    finished_signal = QtCore.pyqtSignal(str)
    error_signal = QtCore.pyqtSignal(str)
    def __init__(self, ch_manager, start_dt, end_dt):
        super().__init__()
        self.ch_manager = ch_manager
        self.start_dt = start_dt
        self.end_dt = end_dt
        session = requests.Session()
        session.trust_env = False
        self.exchange = ccxt.binance({
            'enableRateLimit': True,
            'timeout': 60000,
            'verify': False,
            'session': session
        })
        self._is_running = False
    def run(self):
        self._is_running = True
        try:
            # Конвертируем в timestamp в миллисекундах
            start_ts = int(self.start_dt.timestamp() * 1000)
            end_ts = int(self.end_dt.timestamp() * 1000)
            # Проверка валидности диапазона
            if start_ts >= end_ts:
                self.error_signal.emit("Неверный временной диапазон: начальная дата позже конечной")
                return
            total_ms = end_ts - start_ts
            loaded_candles = 0
            batch_size = 1440  # 1 день в минутах
            while self._is_running and start_ts < end_ts:
                try:
                    # Получаем данные порциями
                    candles = self.exchange.fetch_ohlcv(
                        'BTC/USDT',
                        '1m',
                        since=start_ts,
                        limit=batch_size
                    )
                    if not candles:
                        break
                    # Фильтруем свечи, которые попадают в наш диапазон
                    valid_candles = [c for c in candles if c[0] < end_ts]
                    if not valid_candles:
                        break
                    # Вставляем в ClickHouse
                    if self.ch_manager.insert_candles(valid_candles):
                        loaded_candles += len(valid_candles)
                        start_ts = valid_candles[-1][0] + 60000  # Следующая минута
                        # Обновляем прогресс
                        progress = int((start_ts - int(self.start_dt.timestamp() * 1000)) / total_ms * 100)
                        self.progress_signal.emit(min(progress, 100))
                    # Задержка для соблюдения rate limit
                    time.sleep(1)
                    print(f"SSL verify state: {self.exchange.session.verify}")  # Должно быть False
                except Exception as e:
                    self.error_signal.emit(f"Ошибка при загрузке данных: {str(e)}")
                    break
            if loaded_candles > 0:
                self.finished_signal.emit(f"Успешно загружено {loaded_candles} свечей")
                self.progress_signal.emit(100)
            else:
                self.error_signal.emit("Не удалось загрузить ни одной свечи")
        except Exception as e:
            self.error_signal.emit(f"Критическая ошибка: {str(e)}")
        finally:
            self._is_running = False
            self.exchange.close()
    def stop(self):
        """Безопасная остановка загрузки"""
        self._is_running = False
class TimeframeManager:
    def __init__(self, clickhouse_client):
        self.client = clickhouse_client
        self.ch_client = clickhouse_client  # Add this line
        self.chart_instance = None  # Добавляем атрибут 
        self.timeframes = {
            '1m': 1, '30m': 30, '1h': 60, '4h': 240
        }
        self.current_timeframe = '1m'
         # Только файлы для хранения пользовательских данных (не OHLCV)
        self.time_pairs_files = {
            tf: f"time_pairs_{tf}.csv" for tf in self.timeframes
        }
        self.dcm_results_files = {
            tf: f"dcm_results_{tf}.csv" for tf in self.timeframes
        }
        # Добавляем файлы для корректировок
        self.correction_files = {
            tf: f"corrections_{tf}.csv" for tf in self.timeframes
        }
        self.init_timeframe_tables()
    def get_correction_file(self, timeframe=None):
        """Возвращает путь к файлу корректировок для указанного таймфрейма"""
        if timeframe is None:
            timeframe = self.current_timeframe
        return self.correction_files.get(timeframe)
    def update_and_redraw(self, chart_instance):
        """Обновляет данные и перерисовывает график"""
        current_tf = self.current_timeframe
        if current_tf != '1m':
            self.generate_timeframe_data(current_tf)
        chart_instance.load_data()
        chart_instance.draw_lines() 
    def save_all_timeframes_data(self):
        """Сохраняет данные для всех таймфреймов"""
        for timeframe in self.timeframes:
            time_pairs_file = self.get_time_pairs_file(timeframe)
            if os.path.exists(time_pairs_file):
                # Здесь можно добавить логику сохранения
                print(f"Данные для {timeframe} сохранены")
    def load_timeframe_data(self):
        """Load data for current timeframe from ClickHouse"""
        table_name = self.get_current_table_name()
        try:
            data = self.client.execute(f"""
                SELECT 
                    timestamp,
                    open, high, low, close, volume 
                FROM {table_name}
                ORDER BY timestamp
            """)
            print(f"Loaded {len(data)} records from {table_name}")
            if data:
                print(f"First record: {data[0]}")
                print(f"Last record: {data[-1]}")
            return data
        except Exception as e:
            print(f"[CRITICAL] Error loading from {table_name}: {str(e)}")
            raise
    def get_current_table_name(self):
        """Returns the table name for current timeframe"""
        return f'crypto_data.btc_usdt_{self.current_timeframe}'        
    def load_current_timeframe_data(self):
        """Load data only for the current timeframe"""
        if self.current_timeframe == '1m':
            return
        table_name = f'crypto_data.btc_usdt_{self.current_timeframe}'
        try:
            self.ch_client.execute(f"TRUNCATE TABLE {table_name}")
            self.generate_timeframe_data(self.current_timeframe)
            print(f"Loaded data for {self.current_timeframe} timeframe")
        except Exception as e:
            print(f"Error loading {self.current_timeframe} data: {str(e)}")        
    def set_timeframe_by_index(self, index):
        timeframe_map = {
            0: '1m', 1: '30m', 2: '1h', 3: '4h'
        }
        selected_tf = timeframe_map.get(index, '1m')
        if selected_tf != self.current_timeframe:
            self.current_timeframe = selected_tf
            print(f"Switched to {selected_tf} timeframe")
            return True
        return False
    def init_timeframe_tables(self):
        """Инициализирует таблицы для всех таймфреймов в ClickHouse"""
        try:
            for timeframe in self.timeframes:
                if timeframe == '1m':
                    continue  
                table_name = f'crypto_data.btc_usdt_{timeframe}'
                self.ch_client.execute(f"""
                    CREATE TABLE IF NOT EXISTS {table_name} (
                        timestamp DateTime,
                        open Float64,
                        high Float64,
                        low Float64,
                        close Float64,
                        volume Float64
                    ) ENGINE = MergeTree()
                    ORDER BY timestamp
                """)
        except Exception as e:
            print(f"Ошибка инициализации таблиц таймфреймов: {str(e)}")
    def generate_timeframe_data(self, timeframe):
        """Линия закрытия рисуется правильно"""        
        if timeframe == '1m':
            import traceback
            stack = traceback.format_stack()
            print(f"⚠️ [INVALID TF] Попытка генерации данных для 1m. Вызов из:\n{''.join(stack[-3:-1])}")
            return
        minutes = self.timeframes[timeframe]
        table_name = f'crypto_data.btc_usdt_{timeframe}'         
        try:
            # Удаляем старые данные
            self.client.execute(f"TRUNCATE TABLE {table_name}")
            # Генерируем новые данные с правильным приведением времени
            query = f"""
            INSERT INTO {table_name}
            SELECT 
                toStartOfMinute(toDateTime(toUnixTimestamp(timestamp) - (toUnixTimestamp(timestamp) % {minutes*60}))) AS timestamp,
                any(open) AS open,
                max(high) AS high,
                min(low) AS low,
                anyLast(close) AS close,
                sum(volume) AS volume
            FROM crypto_data.btc_usdt_1m
            GROUP BY timestamp
            ORDER BY timestamp
            """
            self.client.execute(query)
            print(f"[ГЕНЕРАЦИЯ] Данные для {timeframe} успешно сгенерированы")
        except Exception as e:
            print(f"[ГЕНЕРАЦИЯ] Ошибка генерации {timeframe} данных: {str(e)}")
            import traceback
            traceback.print_exc()
            raise
    def _create_empty_csv(self, file_path, headers):
        """Создает пустой CSV файл с заголовками"""
        try:
            with open(file_path, 'w', newline='', encoding='utf-8') as f:
                writer = csv.writer(f)
                writer.writerow(headers)
        except Exception as e:
            print(f"Ошибка создания файла {file_path}: {e}")         
    def _initialize_files(self):
        """Создает все необходимые файлы при инициализации"""
        for tf in self.timeframes:
            # Для всех таймфреймов, кроме 1m, генерируем данные (если нужно)
            if tf != '1m':
                self.generate_timeframe_data(tf)
            # Создаем пустые файлы для пар дат и результатов DCM, если их нет
            if not os.path.exists(self.time_pairs_files[tf]):
                self._create_empty_csv(self.time_pairs_files[tf], [
                    'start_time', 'start_price', 'end_time',
                    'end_price', 'start_index', 'end_index'
                ])
            if not os.path.exists(self.dcm_results_files[tf]):
                self._create_empty_csv(self.dcm_results_files[tf], [
                    'dog_time', 'cat_time', 'manul_time', 'price',
                    'dog_index', 'cat_index', 'manul_index'
                ])
    def create_empty_time_pairs_file(self, timeframe):
        """Создает файл пар дат с примером данных"""
        try:
            with open(self.time_pairs_files[timeframe], 'w', newline='', encoding='utf-8') as f:
                writer = csv.writer(f)
                example_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                writer.writerow([example_time, 0.0, example_time, 0.0, 0, 0])
        except Exception as e:
            print(f"Ошибка создания файла пар дат: {e}")
    def create_empty_dcm_results_file(self, timeframe):
        """Создает пустой файл результатов DCM"""
        try:
            with open(self.dcm_results_files[timeframe], 'w', newline='', encoding='utf-8') as f:
                writer = csv.writer(f)
                writer.writerow([
                    'dog_time', 'cat_time', 'manul_time', 'price',
                    'dog_index', 'cat_index', 'manul_index'
                ])
        except Exception as e:
            print(f"Ошибка создания файла DCM для {timeframe}: {str(e)}")          
    def set_timeframe(self, timeframe):
        """
        Устанавливает текущий таймфрейм.
        Args:
            timeframe (str): Код таймфрейма (например, '5m', '1h')
        Returns:
            bool: True если таймфрейм установлен, False если недопустимый таймфрейм
        """
        if timeframe in self.timeframes:
            self.current_timeframe = timeframe
            return True
        return False
    def get_time_pairs_file(self, timeframe=None):
        """Возвращает путь к файлу пар дат для указанного таймфрейма"""
        if timeframe is None:
            timeframe = self.current_timeframe
        return self.time_pairs_files.get(timeframe)
    def get_dcm_results_file(self, timeframe=None):
        """Возвращает путь к файлу результатов DCM"""
        if timeframe is None:
            timeframe = self.current_timeframe
        return self.dcm_results_files.get(timeframe)
    def update_all_timeframes(self):
        print("Обновление текущего таймфрейма...")  # Изменено сообщение
        try:
            count = self.ch_client.execute("SELECT count() FROM crypto_data.btc_usdt_1m")[0][0]
            if count == 0:
                print("Нет минутных данных для обновления таймфреймов")
                return

            current_tf = self.current_timeframe
            if current_tf != '1m':  # 1m данные берутся напрямую
                    print(f"  ▪ Генерация {current_tf} данных...")
                    self.generate_timeframe_data(current_tf)
                    # Если передан экземпляр графика и это текущий таймфрейм - перерисовываем
                    if self.chart_instance and current_tf == self.current_timeframe:
                        self.chart_instance.load_data()
                        self.chart_instance.draw_lines()            
        except Exception as e:
            print(f"Ошибка обновления таймфреймов: {str(e)}")
    def get_available_timeframes(self):
        """Возвращает список доступных таймфреймов."""
        return list(self.timeframes.keys())
class DCMResultsManager:
    def __init__(self, plot_widget, time_pairs_file, results_file, timeframe_manager):
        self.plot_widget = plot_widget
        self.time_pairs_file = time_pairs_file
        self.results_file = results_file
        self.timeframe_manager = timeframe_manager
        self.results = []
        self.marker_items = []
        self.pair_markers = []

        self.file_watcher = QtCore.QFileSystemWatcher()
        self.file_watcher.addPath(time_pairs_file)
        #self.file_watcher.fileChanged.connect(self.on_time_pairs_changed)
        self.load_results()

    def on_time_pairs_changed(self, path):
        """Вызывается при изменении файла time_pairs.csv"""
        print(f"Файл {path} изменен, пересчитываем результаты...")
        QtCore.QTimer.singleShot(10, self.calculate_dcm_results)
    def load_time_pairs(self):
        """Загружает пары дат из файла, пропуская заголовок"""
        time_pairs = []
        if not os.path.exists(self.time_pairs_file):
            return time_pairs
        with open(self.time_pairs_file, 'r', encoding='utf-8') as file:
            reader = csv.reader(file)
            next(reader)  
            for row in reader:
                if len(row) >= 6:
                    try:
                        dt1 = datetime.strptime(row[0], '%Y-%m-%d %H:%M:%S')
                        price1 = float(row[1])
                        dt2 = datetime.strptime(row[2], '%Y-%m-%d %H:%M:%S')
                        price2 = float(row[3])
                        index1 = int(row[4])
                        index2 = int(row[5])
                        time_pairs.append((dt1, price1, dt2, price2, index1, index2))
                    except (ValueError, IndexError) as e:
                        print(f"Ошибка обработки строки {row}: {e}")
                        continue
        return time_pairs

    def load_time_pairs_from_file(self, file_path):
        """Загружает пары дат из указанного файла"""
        time_pairs = []
        if not os.path.exists(file_path):
            print(f"[WARNING] Файл {file_path} не найден, создаем пустой список")
            return time_pairs
        try:
            with open(file_path, 'r', encoding='utf-8') as file:
                reader = csv.reader(file)
                next(reader)  # Пропускаем заголовок
                for row in reader:
                    if len(row) >= 6:
                        try:
                            dt1 = datetime.strptime(row[0], '%Y-%m-%d %H:%M:%S')
                            price1 = float(row[1])
                            dt2 = datetime.strptime(row[2], '%Y-%m-%d %H:%M:%S')
                            price2 = float(row[3])
                            index1 = int(row[4])
                            index2 = int(row[5])
                            time_pairs.append((dt1, price1, dt2, price2, index1, index2))
                        except (ValueError, IndexError) as e:
                            print(f"Ошибка обработки строки {row}: {e}")
                            continue
            return time_pairs
        except Exception as e:
            print(f"Ошибка загрузки файла {file_path}: {e}")
            return []     
    def create_marker(self, x, y, symbol_code, number, color):
        """Создает метку с указанным символом (числовой код) и номером"""
        if len(color) > 3:
            color = tuple(color[:3])  
        marker = pg.ScatterPlotItem(
            x=[x],
            y=[y],
            symbol=symbol_code,  
            size=18,
            pen=pg.mkPen(color=(150, 150, 150), width=1),
            brush=pg.mkBrush(color),
            pxMode=True
        )
        text = pg.TextItem(
            text=str(number),
            anchor=(0.5, 0.5),
            color='white',
            fill=(0, 0, 0, 0),
            border=None
        )
        text.setPos(x, y)
        marker.text = text
        return marker

    def clear_markers(self):
        """Удаляет все метки с графика"""
        for marker in self.marker_items:
            if hasattr(marker, 'text'):
                try:
                    self.plot_widget.removeItem(marker.text)
                except:
                    pass
            try:
                self.plot_widget.removeItem(marker)
            except:
                pass
        self.marker_items = []
    def get_line_color(self, price1, price2):
        """Определяет цвет линии/метки в зависимости от разницы цен"""
        try:
            if price2 > price1:  
                return (150, 0, 0, 150)  
            else:  
                return (0, 150, 0, 150)  
        except Exception as e:
            print(f"Ошибка в get_line_color: {e}")
            return (255, 255, 0, 100)  
    def calculate_dcm_results(self):
        """Вычисляет результаты по формуле DCM (без автоматической корректировки)"""
        time_pairs = self.load_time_pairs()
        self.results = []
        # Получаем текущий таймфрейм и его параметры
        current_tf = self.timeframe_manager.current_timeframe
        tf_minutes = self.timeframe_manager.timeframes[current_tf]
        # Логируем только для первой пары
        if time_pairs:
            first_pair = time_pairs[0]
            dt1, price1, dt2, price2, idx1, idx2 = first_pair

        for i, (dt1, price1, dt2, price2, idx1, idx2) in enumerate(time_pairs):
            try:
                # Основные расчеты DCM с учетом текущего таймфрейма
                tf_15 = 15 * tf_minutes * 60  
                tf_30 = 30 * tf_minutes * 60   
                tf_1 = 2.3333 * tf_minutes * 60    
                FirstTimeGAS3 = idx2 + (idx2 - idx1)
                FirstGasCorrect15 = idx1 + tf_15
                FirstFakeGAS15diff = abs(FirstTimeGAS3 - FirstGasCorrect15) / 2
                FirstFakeGAS15 = FirstTimeGAS3 + tf_1 + FirstFakeGAS15diff
                FirstGasCorrect30 = idx1 + tf_30
                FirstGas30diff = abs(FirstTimeGAS3 - FirstGasCorrect30) / 2
                FirstGas30 = FirstTimeGAS3 + tf_1 + FirstGas30diff
                FirstGas23diff = (FirstGas30 - FirstFakeGAS15) / 2
                FirstGas23 = round(FirstFakeGAS15 + FirstGas23diff)
                FirstTimeGAS4 = FirstTimeGAS3 + (FirstTimeGAS3 - idx1)
                FirstMiddleGAS = FirstTimeGAS3 + (FirstTimeGAS3 - idx2)
                FirstEchoGASdiff15 = abs(FirstMiddleGAS - FirstGasCorrect15) / 2
                FirstEchoGAS15 = FirstTimeGAS4 + FirstEchoGASdiff15
                FirstEchoGASdiff30 = abs(FirstMiddleGAS - FirstGasCorrect30) / 2
                FirstEchoGAS30 = FirstTimeGAS4 + FirstEchoGASdiff30
                FirstEchoGASdiff23 = (FirstEchoGAS30 - FirstEchoGAS15) / 2
                FirstEchoGAS23 = round(FirstEchoGAS15 + FirstEchoGASdiff23)
                FirstFinalGASdiff23 = (FirstEchoGAS23 - FirstGas23) / 2
                FirstFinalGAS23 = round(FirstGas23 + FirstFinalGASdiff23)
                FirstEndGASdiff = abs(FirstEchoGAS23 - FirstFinalGAS23) / 2
                FirstEndGASdiff19 = abs(FirstFinalGAS23 - FirstGas23) / 2
                FirstEndGAS = round(FirstFinalGAS23 + FirstEndGASdiff)
                FirstEndGAS19 = round(FirstGas23 + FirstEndGASdiff19)
                
                # ===== СТАРАЯ КОРРЕКТИРОВКА ПОЛНОСТЬЮ УДАЛЕНА =====
                # Корректировка больше не применяется здесь
                # Новая система корректировки вынесена в отдельный модуль CorrectionDialog
                # Используем исходные значения без изменений
                FirstGas23correct = FirstGas23
                FirstEndGAScorrect = FirstEndGAS
                FirstEndGAS19correct = FirstEndGAS19

                self.results.append({
                    'dog_time': datetime.fromtimestamp(FirstGas23correct).strftime('%Y-%m-%d %H:%M:%S'),
                    'cat_time': datetime.fromtimestamp(FirstEndGAScorrect).strftime('%Y-%m-%d %H:%M:%S'),
                    'manul_time': datetime.fromtimestamp(FirstEndGAS19correct).strftime('%Y-%m-%d %H:%M:%S'),
                    'price': price2,
                    'dog_index': FirstGas23correct,
                    'cat_index': FirstEndGAScorrect,
                    'manul_index': FirstEndGAS19correct,
                    'pair_start_time': dt1.strftime('%Y-%m-%d %H:%M:%S'),
                    'pair_start_price': price1,
                    'pair_end_time': dt2.strftime('%Y-%m-%d %H:%M:%S'),
                    'pair_end_price': price2,                    
                    'timeframe': current_tf  # Сохраняем информацию о таймфрейме
                })
            except Exception as e:
                print(f"\n[ОШИБКА] для пары {dt1}-{dt2}: {str(e)}")
                continue
        self.save_results()
    
    def load_price_data(self):
        """Загружает данные цен с преобразованием timestamp"""
        try:
            query = """
            SELECT 
                toUnixTimestamp(timestamp) as timestamp_sec,
                open, high, low, close, volume 
            FROM crypto_data.btc_usdt_1m
            ORDER BY timestamp_sec
            """
            data = self.timeframe_manager.ch_client.execute(query)
            if not data:
                print("[WARNING] Нет данных из ClickHouse")
                return None
            df = pd.DataFrame(data, columns=['timestamp', 'open', 'high', 'low', 'close', 'volume'])
            df['timestamp'] = df['timestamp'] * 1000  
            return df
        except Exception as e:
            print(f"[ERROR] Ошибка загрузки ценовых данных: {str(e)}")
            return None
      
    def load_results(self):
        """Загружает результаты из файла, включая данные о парах точек"""
        if not os.path.exists(self.results_file):
            self.calculate_dcm_results()
            return
    
        self.results = []
        with open(self.results_file, 'r', encoding='utf-8') as file:
            reader = csv.DictReader(file)
            for row in reader:
                try:
                    result = {
                        'dog_time': row['dog_time'],
                        'cat_time': row['cat_time'],
                        'manul_time': row['manul_time'],
                        'price': float(row['price']),
                        'dog_index': int(float(row['dog_index'])),
                        'cat_index': int(float(row['cat_index'])),
                        'manul_index': int(float(row['manul_index'])),
                        'timeframe': row.get('timeframe', self.timeframe_manager.current_timeframe)
                    }
                    
                    # Добавляем данные о парах, если они есть
                    if row.get('pair_start_time') and row.get('pair_end_time'):
                        result.update({
                            'pair_start_time': row['pair_start_time'],
                            'pair_start_price': float(row['pair_start_price']),
                            'pair_end_time': row['pair_end_time'],
                            'pair_end_price': float(row['pair_end_price'])
                        })
                    
                    self.results.append(result)
                except (ValueError, KeyError) as e:
                    print(f"Ошибка обработки строки {row}: {e}")
                    continue

    def save_results(self):
        """Сохраняет результаты в CSV файл с добавлением данных о парах дат"""
        if not self.results:
            return

        # Загружаем пары дат для текущего таймфрейма
        time_pairs = self.load_time_pairs()
    
        with open(self.results_file, 'w', newline='', encoding='utf-8') as file:
            # Расширяем заголовки
            fieldnames = [
                'dog_time', 'cat_time', 'manul_time', 'price',
                'dog_index', 'cat_index', 'manul_index',
                'pair_start_time', 'pair_start_price', 
                'pair_end_time', 'pair_end_price',
                'timeframe'  # Добавляем таймфрейм для отслеживания
            ]
    
            writer = csv.DictWriter(file, fieldnames=fieldnames)
            writer.writeheader()
    
            # Сохраняем данные, добавляя информацию о парах
            for i, result in enumerate(self.results):
                row_data = {
                    'dog_time': result.get('dog_time', ''),
                    'cat_time': result.get('cat_time', ''),
                    'manul_time': result.get('manul_time', ''),
                    'price': result.get('price', ''),
                    'dog_index': result.get('dog_index', ''),
                    'cat_index': result.get('cat_index', ''),
                    'manul_index': result.get('manul_index', ''),
                    'timeframe': self.timeframe_manager.current_timeframe
                }
            
                # Добавляем данные пары, если она существует для этого индекса
                if i < len(time_pairs):
                    pair = time_pairs[i]
                    row_data.update({
                        'pair_start_time': pair[0].strftime('%Y-%m-%d %H:%M:%S'),
                        'pair_start_price': pair[1],
                        'pair_end_time': pair[2].strftime('%Y-%m-%d %H:%M:%S'),
                        'pair_end_price': pair[3]
                    })
                else:
                    row_data.update({
                        'pair_start_time': '',
                        'pair_start_price': '',
                        'pair_end_time': '',
                        'pair_end_price': ''
                    })
            
                writer.writerow(row_data)
    def show_results_dialog(self):
        """Показывает диалог с результатами и настройками расчета"""
        dialog = QtWidgets.QDialog()
        dialog.setWindowTitle("Собака-Кот-Манул (настройки расчета)")
        dialog.setMinimumSize(1000, 600)
        layout = QtWidgets.QVBoxLayout(dialog)

        # Таблица с результатами
        table = QtWidgets.QTableWidget()
        table.setColumnCount(7)
        table.setHorizontalHeaderLabels([
            "Время Собаки", "Время Манула", "Время Кота", 
            "Цена меток", "Индекс Собаки", "Индекс Манула", "Индекс Кота"
        ])
        table.setRowCount(len(self.results))
        for i, result in enumerate(self.results):
            table.setItem(i, 0, QtWidgets.QTableWidgetItem(result['dog_time']))
            table.setItem(i, 1, QtWidgets.QTableWidgetItem(result['manul_time']))
            table.setItem(i, 2, QtWidgets.QTableWidgetItem(result['cat_time']))
            table.setItem(i, 3, QtWidgets.QTableWidgetItem(f"{result['price']:.2f}"))
            table.setItem(i, 4, QtWidgets.QTableWidgetItem(str(result['dog_index'])))
            table.setItem(i, 5, QtWidgets.QTableWidgetItem(str(result['manul_index'])))
            table.setItem(i, 6, QtWidgets.QTableWidgetItem(str(result['cat_index'])))
        table.resizeColumnsToContents()
        layout.addWidget(table)
        btn_close = QtWidgets.QPushButton("Закрыть")
        btn_close.clicked.connect(dialog.accept)
        layout.addWidget(btn_close)
        dialog.exec()
    def recalculate_and_update(self, dialog, table):
        """Пересчитывает результаты и обновляет таблицу"""
        self.calculate_dcm_results()
        table.setRowCount(len(self.results))
        for i, result in enumerate(self.results):
            table.setItem(i, 0, QtWidgets.QTableWidgetItem(result['dog_time']))
            table.setItem(i, 1, QtWidgets.QTableWidgetItem(result['manul_time']))
            table.setItem(i, 2, QtWidgets.QTableWidgetItem(result['cat_time']))
            table.setItem(i, 3, QtWidgets.QTableWidgetItem(f"{result['price']:.2f}"))
            table.setItem(i, 4, QtWidgets.QTableWidgetItem(str(result['dog_index'])))
            table.setItem(i, 5, QtWidgets.QTableWidgetItem(str(result['manul_index'])))
            table.setItem(i, 6, QtWidgets.QTableWidgetItem(str(result['cat_index'])))
        table.resizeColumnsToContents()
        QtWidgets.QMessageBox.information(dialog, "Успех", "Данные пересчитаны!")

class AverageResultsManager:
    def __init__(self, timeframe_manager):
        self.timeframe_manager = timeframe_manager
        self.average_file = "FINAL_RESULTS.csv"
        self.current_selections = {}
        self.selected_timeframes_file = "selected_timeframes.txt"
        self.selected_timeframes = self.load_selected_timeframes()
        self.vertical_lines = []
        self.plot_widget = None
        self._correction_dialog = None
        self.rounding_checkbox = QtWidgets.QCheckBox()
        self.rounding_checkbox.setChecked(True)
        self.load_animal_selections()
        self.save_averages_to_file()
        self._show_vertical_lines = False
    
    def load_animal_selections(self):
        """Загружает сохраненные выборы животных и типов цепи из файла"""
        if not os.path.exists(self.average_file):
            return
        try:
            with open(self.average_file, 'r', encoding='utf-8-sig') as f:
                reader = csv.DictReader(f, delimiter=';')
                for row in reader:
                    try:
                        position = int(row['Позиция'])
                        animal = row.get('Животное', '')
                        chain_type = row.get('Тип цепи', '')
                        if animal and animal != "не выбрано":
                            self.current_selections[position] = {
                                'animal': animal,
                                'chain_type': chain_type if chain_type else 'серия'
                            }
                    except (ValueError, KeyError) as e:
                        continue
        except Exception as e:
            print(f"Ошибка загрузки сохраненных выборов: {e}")
    
    def load_time_pairs(self, time_pairs_file):
        """Загрузка пар с проверкой формата"""
        time_pairs = []
        if not os.path.exists(time_pairs_file):
            return time_pairs
        try:
            with open(time_pairs_file, 'r', encoding='utf-8') as file:
                reader = csv.reader(file)
                next(reader)
                for row_num, row in enumerate(reader, 1):
                    if len(row) >= 6:
                        try:
                            dt1 = datetime.strptime(row[0], '%Y-%m-%d %H:%M:%S')
                            price1 = float(row[1])
                            dt2 = datetime.strptime(row[2], '%Y-%m-%d %H:%M:%S')
                            price2 = float(row[3])
                            index1 = int(float(row[4]))
                            index2 = int(float(row[5]))
                            time_pairs.append((dt1, price1, dt2, price2, index1, index2))
                        except Exception as e:
                            continue
            return time_pairs
        except Exception as e:
            print(f"Ошибка чтения файла: {e}")
            return []
    
    def set_plot_widget(self, plot_widget):
        """Set the plot widget to draw lines on"""
        self.plot_widget = plot_widget
    
    def set_correction_dialog(self, correction_dialog):
        """Устанавливает ссылку на диалог корректировки для проверки привитости"""
        self._correction_dialog = correction_dialog
        print(f"[AVERAGE_MANAGER] Ссылка на CorrectionDialog установлена")
        
        if hasattr(self, '_grafted_cache'):
            self._grafted_cache.clear()
        else:
            self._grafted_cache = {}
        
        # Принудительно обновляем линии
        if hasattr(self, 'plot_widget') and self.plot_widget:
            if hasattr(self, '_last_draw_time'):
                delattr(self, '_last_draw_time')
            self.draw_vertical_lines()
    
    def draw_vertical_lines(self):
        """Рисует вертикальные линии на графике"""
        # (оставь существующую реализацию без изменений)
        pass
    
    def clear_vertical_lines(self):
        """Remove all vertical lines from the plot"""
        if not self.plot_widget:
            return
        for line in self.vertical_lines:
            try:
                self.plot_widget.removeItem(line)
            except:
                pass
        self.vertical_lines = []
    
    def load_selected_timeframes(self):
        """Загружает сохраненные выбранные таймфреймы из файла"""
        if not os.path.exists(self.selected_timeframes_file):
            return list(self.timeframe_manager.timeframes.keys())
        try:
            with open(self.selected_timeframes_file, 'r', encoding='utf-8') as f:
                return [line.strip() for line in f if line.strip() in self.timeframe_manager.timeframes]
        except Exception:
            return list(self.timeframe_manager.timeframes.keys())
    
    def save_selected_timeframes(self, timeframes):
        """Сохраняет выбранные таймфреймы в файл"""
        try:
            with open(self.selected_timeframes_file, 'w', encoding='utf-8') as f:
                for tf in timeframes:
                    f.write(f"{tf}\n")
            self.selected_timeframes = timeframes
        except Exception as e:
            print(f"Ошибка сохранения выбранных таймфреймов: {e}")
    
    def save_calculated_averages(self, averages):
        """Сохраняет рассчитанные средние в FINAL_RESULTS.csv (только позиция, времена, цена, цвет)"""
        if not averages:
            return
        
        filename = "FINAL_RESULTS.csv"
        try:
            with open(filename, 'w', newline='', encoding='utf-8-sig') as f:
                writer = csv.writer(f, delimiter=';')
                writer.writerow(['Позиция', 'Собака', 'Кот', 'Манул', 'Цена', 'Цвет'])
                for item in averages:
                    writer.writerow([
                        item['position'],
                        item['avg_dog'],
                        item['avg_cat'],
                        item['avg_manul'],
                        item.get('price', 0),
                        item.get('color', 'red')
                    ])
            print(f"[УСРЕДНЕНИЕ] Сохранено {len(averages)} записей в {filename}")
        except Exception as e:
            print(f"[УСРЕДНЕНИЕ] Ошибка сохранения: {str(e)}")
    
    def calculate_averages_with_rounding(self, selected_timeframes=None):
        """
        Вычисляет средние значения из DCM-файлов.
        Если selected_timeframes не указаны — берутся все доступные таймфреймы.
        """
        if selected_timeframes is None:
            selected_timeframes = list(self.timeframe_manager.timeframes.keys())
        
        all_data = []
        
        for timeframe in selected_timeframes:
            dcm_file = self.timeframe_manager.get_dcm_results_file(timeframe)
            if not os.path.exists(dcm_file):
                continue
            
            try:
                df = pd.read_csv(dcm_file)
                timeframe_data = []
                for idx, row in df.iterrows():
                    try:
                        dog_time = pd.to_datetime(row['dog_time'])
                        cat_time = pd.to_datetime(row['cat_time'])
                        manul_time = pd.to_datetime(row['manul_time'])
                        timeframe_data.append({
                            'dog': dog_time,
                            'cat': cat_time,
                            'manul': manul_time,
                            'price': float(row.get('price', 0))
                        })
                    except:
                        continue
                
                if timeframe_data:
                    all_data.append((timeframe, timeframe_data))
                    
            except Exception as e:
                print(f"[УСРЕДНЕНИЕ] Ошибка чтения {dcm_file}: {e}")
                continue
        
        if not all_data:
            return []
        
        max_pairs = max(len(td) for _, td in all_data)
        
        averages = []
        for i in range(max_pairs):
            dog_times = []
            cat_times = []
            manul_times = []
            prices = []
            
            for timeframe, timeframe_data in all_data:
                if i < len(timeframe_data):
                    dog_times.append(timeframe_data[i]['dog'])
                    cat_times.append(timeframe_data[i]['cat'])
                    manul_times.append(timeframe_data[i]['manul'])
                    prices.append(timeframe_data[i].get('price', 0))
            
            if dog_times and cat_times and manul_times:
                avg_dog = pd.Series(dog_times).mean()
                avg_cat = pd.Series(cat_times).mean()
                avg_manul = pd.Series(manul_times).mean()
                avg_price = sum(prices) / len(prices) if prices else 0
                
                averages.append({
                    'position': i + 1,
                    'avg_dog': avg_dog.strftime('%Y-%m-%d %H:%M:%S'),
                    'avg_cat': avg_cat.strftime('%Y-%m-%d %H:%M:%S'),
                    'avg_manul': avg_manul.strftime('%Y-%m-%d %H:%M:%S'),
                    'price': avg_price
                })
        
        print(f"[УСРЕДНЕНИЕ] Рассчитано {len(averages)} позиций")
        return averages
    
    def save_averages_to_file(self):
        """Сохраняет усреднённые данные в FINAL_RESULTS.csv (только позиция, времена, цена, цвет)"""
        averages = self.calculate_averages_with_rounding()
        if not averages:
            print("[УСРЕДНЕНИЕ] Нет данных для сохранения")
            return False
        
        all_time_pairs = []
        for timeframe in self.selected_timeframes:
            time_pairs_file = self.timeframe_manager.get_time_pairs_file(timeframe)
            if os.path.exists(time_pairs_file):
                pairs = self.load_time_pairs(time_pairs_file)
                all_time_pairs.extend(pairs)
        
        data_to_save = []
        for i, avg in enumerate(averages):
            color = "red"
            found_pair = None
            for pair in all_time_pairs:
                pair_position = all_time_pairs.index(pair) + 1
                if pair_position == avg['position']:
                    found_pair = pair
                    break
            if found_pair:
                _, price1, _, price2, _, _ = found_pair
                if price2 > price1:
                    color = "red"
                elif price2 < price1:
                    color = "green"
                else:
                    color = "yellow"
            
            data_to_save.append({
                'position': avg['position'],
                'dog_time': avg['avg_dog'],
                'cat_time': avg['avg_cat'],
                'manul_time': avg['avg_manul'],
                'price': avg.get('price', 0),
                'color': color
            })
        
        filename = "FINAL_RESULTS.csv"
        try:
            with open(filename, 'w', newline='', encoding='utf-8-sig') as f:
                writer = csv.writer(f, delimiter=';')
                writer.writerow(['Позиция', 'Собака', 'Кот', 'Манул', 'Цена', 'Цвет'])
                for item in data_to_save:
                    writer.writerow([
                        item['position'],
                        item['dog_time'],
                        item['cat_time'],
                        item['manul_time'],
                        item['price'],
                        item['color']
                    ])
            print(f"[УСРЕДНЕНИЕ] Сохранено {len(data_to_save)} записей в {filename}")
            return True
        except Exception as e:
            print(f"[УСРЕДНЕНИЕ] Ошибка записи файла: {str(e)}")
            return False
    
    def update_averages_table(self, dialog):
        """Обновляет таблицу с учетом выбранных таймфреймов"""
        try:
            selected_tfs = [tf for tf, cb in self.timeframe_checkboxes.items() if cb.isChecked()]
            if not selected_tfs:
                QtWidgets.QMessageBox.warning(dialog, "Ошибка", "Выберите хотя бы один таймфрейм")
                return
            
            self.selected_timeframes = selected_tfs
            self.save_selected_timeframes(selected_tfs)
            
            averages = self.calculate_averages_with_rounding(selected_tfs)
            
            if not averages:
                QtWidgets.QMessageBox.warning(dialog, "Ошибка", "Нет данных для выбранных таймфреймов")
                return
            
            self.save_calculated_averages(averages)
            
            # Только 5 колонок (позиция, собака, кот, манул, цена)
            self.table.setColumnCount(5)
            self.table.setHorizontalHeaderLabels([
                "Позиция", "Собака", "Кот", "Манул", "Цена"
            ])
            
            self.table.setRowCount(len(averages))
            for i, avg in enumerate(averages):
                self.table.setItem(i, 0, QtWidgets.QTableWidgetItem(str(avg['position'])))
                self.table.setItem(i, 1, QtWidgets.QTableWidgetItem(avg['avg_dog']))
                self.table.setItem(i, 2, QtWidgets.QTableWidgetItem(avg['avg_cat']))
                self.table.setItem(i, 3, QtWidgets.QTableWidgetItem(avg['avg_manul']))
                self.table.setItem(i, 4, QtWidgets.QTableWidgetItem(f"{avg.get('price', 0):.2f}"))
            
            self.table.resizeColumnsToContents()
            
        except Exception as e:
            QtWidgets.QMessageBox.critical(dialog, "Ошибка", f"Не удалось обновить таблицу:\n{str(e)}")
            import traceback
            traceback.print_exc()
    
    def show_averages_dialog_with_selection(self):
        """Диалог с выбором таймфреймов (без выбора животных, они в главной таблице)"""
        try:
            if not any(os.path.exists(self.timeframe_manager.get_dcm_results_file(tf)) 
                      for tf in self.timeframe_manager.timeframes):
                QtWidgets.QMessageBox.warning(None, "Нет данных", "Файлы с результатами DCM не найдены.")
                return
            
            dialog = QtWidgets.QDialog()
            dialog.setWindowTitle("Усреднение с настройками")
            dialog.setMinimumSize(800, 600)
            layout = QtWidgets.QVBoxLayout(dialog)
            
            timeframe_group = QtWidgets.QGroupBox("Выберите таймфреймы для усреднения")
            timeframe_layout = QtWidgets.QHBoxLayout()
            self.timeframe_checkboxes = {}
            for tf in sorted(self.timeframe_manager.timeframes.keys()):
                cb = QtWidgets.QCheckBox(tf)
                cb.setChecked(tf in self.selected_timeframes)
                self.timeframe_checkboxes[tf] = cb
                timeframe_layout.addWidget(cb)
            timeframe_group.setLayout(timeframe_layout)
            layout.addWidget(timeframe_group)
            
            settings_group = QtWidgets.QGroupBox("Настройки")
            settings_layout = QtWidgets.QHBoxLayout()
            
            btn_recalculate = QtWidgets.QPushButton("Пересчитать")
            btn_recalculate.clicked.connect(lambda: self.update_averages_table(dialog))
            settings_layout.addWidget(btn_recalculate)
            
            settings_group.setLayout(settings_layout)
            layout.addWidget(settings_group)
            
            self.table = QtWidgets.QTableWidget()
            self.update_averages_table(dialog)
            layout.addWidget(self.table)
            
            buttons = QtWidgets.QHBoxLayout()
            btn_close = QtWidgets.QPushButton("Закрыть")
            btn_close.clicked.connect(dialog.accept)
            buttons.addWidget(btn_close)
            
            layout.addLayout(buttons)
            dialog.exec()
            
        except Exception as e:
            QtWidgets.QMessageBox.critical(None, "Ошибка", f"Произошла ошибка:\n{str(e)}")
    
    def save_animal_selections(self, dialog):
        """Сохраняет выбранные животное и тип цепи для каждой позиции"""
        try:
            for i in range(self.table.rowCount()):
                animal_combo = self.table.cellWidget(i, 4)
                chain_combo = self.table.cellWidget(i, 5)
                animal = animal_combo.currentText() if animal_combo.currentText() != "не выбрано" else ""
                chain_type = chain_combo.currentText() if chain_combo.currentText() else ""
                if animal:
                    self.current_selections[i+1] = {'animal': animal, 'chain_type': chain_type}
                elif (i+1) in self.current_selections:
                    del self.current_selections[i+1]
            self.save_averages_to_file()
            self.draw_vertical_lines()
        except Exception as e:
            QtWidgets.QMessageBox.critical(dialog, "Ошибка", f"Не удалось сохранить данные:\n{str(e)}")

    def draw_vertical_lines(self):
        """Рисует вертикальные линии на графике без нижних меток о привитости."""
        # ВРЕМЕННОЕ ОТКЛЮЧЕНИЕ вертикальных линий из Зазеркалья
        # Чтобы вернуть, установите self._show_vertical_lines = True
        if not getattr(self, '_show_vertical_lines', False):
            return

        # Увеличиваем интервал до 1 секунды
        if hasattr(self, '_last_draw_time'):
            if time.time() - self._last_draw_time < 1.0:
                return

        self.clear_vertical_lines()
        if not self.plot_widget:
            return

        # Получаем текущие границы видимой области
        view_range = self.plot_widget.getViewBox().viewRange()
        if not view_range or len(view_range) < 2:
            return
        x_min, x_max = view_range[0]
        y_min, y_max = view_range[1]

        # Смещение текста вниз от верхней границы
        text_y_offset_top = (y_max - y_min) * 0.12
        text_y_position_top = y_max - text_y_offset_top

        correction_file = "TAIL_CORRECTIONS.csv"
        if not os.path.exists(correction_file):
            return

        # Загружаем цвета из FINAL_RESULTS.csv
        if not hasattr(self, '_colors_cache'):
            self._colors_cache = {}
            try:
                if os.path.exists(self.average_file):
                    with open(self.average_file, 'r', encoding='utf-8-sig') as f:
                        reader = csv.DictReader(f, delimiter=';')
                        for row in reader:
                            try:
                                position = int(row.get('Позиция', 0))
                                color = row.get('Цвет', 'yellow')
                                self._colors_cache[position] = color
                            except (ValueError, KeyError):
                                continue
            except Exception as e:
                print(f"Error loading colors from average file: {e}")

        # Загружаем типы линий из TAIL_CORRECTIONS.csv
        if not hasattr(self, '_line_types_cache'):
            self._line_types_cache = {}
            try:
                df = pd.read_csv(correction_file, sep=';', encoding='utf-8-sig')
                if 'Тип' in df.columns:
                    for idx, row in df.iterrows():
                        position = row.get('ID', idx + 1)
                        line_type = row.get('Тип', 'главный')
                        if pd.notna(line_type):
                            self._line_types_cache[position] = str(line_type)
            except Exception as e:
                print(f"Error loading line types: {e}")

        try:
            df = pd.read_csv(correction_file, sep=';', encoding='utf-8-sig')
        except Exception as e:
            print(f"Error reading correction file: {e}")
            return

        top_font = QtGui.QFont()
        top_font.setPointSize(11)
        top_font.setBold(True)

        lines_visible = 0

        for idx, row in df.iterrows():
            position = row.get('ID', idx + 1)
            time_str = row.get('Поправка_прогноза', '')

            if not time_str or pd.isna(time_str) or time_str == '':
                continue

            try:
                dt = datetime.strptime(str(time_str), '%Y-%m-%d %H:%M:%S')
                timestamp = dt.timestamp() * 1000

                if not (x_min <= timestamp <= x_max):
                    continue

                lines_visible += 1
                animal = row.get('Животное', '')
                chain_type = row.get('Тип_цепи', '')
                line_type = self._line_types_cache.get(position, 'главный')
                base_color = self._colors_cache.get(position, row.get('Цвет', 'yellow'))

                # Определяем цвет линии
                if base_color == "red":
                    if line_type == "импульс":
                        line_color = (255, 140, 0, 150)
                    else:
                        line_color = (255, 0, 0, 150)
                    text_color = 'aqua'
                elif base_color == "green":
                    if line_type == "импульс":
                        line_color = (160, 32, 240, 150)
                    else:
                        line_color = (0, 255, 0, 150)
                    text_color = 'yellow'
                else:
                    line_color = (255, 255, 0, 150)
                    text_color = 'white'

                # Создаем линию
                if chain_type == "серия":
                    line = pg.InfiniteLine(
                        pos=timestamp,
                        angle=90,
                        pen=pg.mkPen(
                            line_color,
                            width=1,
                            style=QtCore.Qt.PenStyle.DashLine,
                            dash=[16, 16]
                        )
                    )
                else:
                    line = pg.InfiniteLine(
                        pos=timestamp,
                        angle=90,
                        pen=pg.mkPen(line_color, width=1)
                    )

                # Верхняя метка (ID, животное, время)
                label_text = f"{position} {animal} {time_str}"
                label_top = pg.TextItem(
                    text=label_text,
                    anchor=(0.5, 0.5),
                    angle=90,
                    color=text_color,
                    fill=(0, 0, 0, 0),
                    border=None
                )
                label_top.setFont(top_font)
                label_top.setPos(timestamp, text_y_position_top)

                self.plot_widget.addItem(line)
                self.plot_widget.addItem(label_top)
                self.vertical_lines.extend([line, label_top])

            except ValueError as e:
                continue
            except Exception as e:
                continue

        if lines_visible > 0:
            print(f"[ВЕРТИКАЛЬНЫЕ] Видимых линий: {lines_visible}")

        self._last_draw_time = time.time()
    
    def clear_vertical_lines(self):
        """Remove all vertical lines from the plot"""
        if not self.plot_widget:
            return
        for line in self.vertical_lines:
            try:
                self.plot_widget.removeItem(line)
            except:
                pass
        self.vertical_lines = []            

class ChainManager:
    """Менеджер для работы с цепочками ID из TAIL_CORRECTIONS.csv"""
    
    def __init__(self, corrections_file="TAIL_CORRECTIONS.csv", chains_file="CHAINS_DATA.json"):
        self.corrections_file = corrections_file
        self.chains_file = chains_file
        self.chains_data = self.load_chains()
        
    def load_chains(self):
        """Загружает готовые цепочки из JSON файла"""
        if os.path.exists(self.chains_file):
            try:
                with open(self.chains_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                print(f"[CHAINS] Загружено {len(data.get('chains', {}))} цепочек из {self.chains_file}")
                return data
            except Exception as e:
                print(f"[CHAINS] Ошибка загрузки: {str(e)}")
                return {"last_update": "", "chains": {}}
        return {"last_update": "", "chains": {}}
    
    def save_chains(self):
        try:
            self.chains_data["last_update"] = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            with open(self.chains_file, 'w', encoding='utf-8') as f:
                json.dump(self.chains_data, f, indent=2, ensure_ascii=False, default=str)
            logger.info(f"[CHAINS] Сохранено {len(self.chains_data['chains'])} ID с цепочками в {self.chains_file}")
            return True
        except Exception as e:
            logger.error(f"[CHAINS] Ошибка сохранения: {str(e)}")
            return False

    def build_chain_for_id_and_animal(self, start_id, animal, ch_client=None):
        """
        Строит цепочку, начиная с ID start_id и животного animal.
        Пасс в строке должен быть в формате 'ID|Тип'.
        Возвращает словарь с цепочкой или None.
        """
        if not os.path.exists(self.corrections_file):
            logger.error(f"[ЦЕПОЧКА] Файл {self.corrections_file} не найден")
            return None

        df = pd.read_csv(self.corrections_file, sep=';', encoding='utf-8-sig')
        df['ID'] = df['ID'].astype(str)

        chain_ids = []
        chain_pairs = []
        current_id = start_id
        current_animal = animal
        visited = set()

        while current_id is not None and current_id != 0 and (current_id, current_animal) not in visited:
            visited.add((current_id, current_animal))
            chain_ids.append(current_id)

            # Ищем строку с данным ID и животным
            row = df[(df['ID'] == str(current_id)) & (df['Животное'] == current_animal)]
            if row.empty:
                logger.info(f"[ЦЕПОЧКА] ID {current_id} не найден для животного {current_animal}")
                break

            pass_val = row.iloc[0].get('цепь', '')
            if not pass_val or pd.isna(pass_val) or pass_val == '':
                logger.info(f"[ЦЕПОЧКА] Пустой пасс для ID {current_id}, животное {current_animal}")
                break

            # Парсим пасс: ожидается "ID|Тип"
            parts = str(pass_val).split('|')
            if len(parts) != 2:
                # fallback: если только ID, используем тип по умолчанию (текущее животное)
                try:
                    next_id = int(parts[0])
                    next_type = current_animal
                except:
                    logger.warning(f"[ЦЕПОЧКА] Некорректный пасс '{pass_val}' для ID {current_id}")
                    break
            else:
                try:
                    next_id = int(parts[0])
                    next_type = parts[1].strip()
                    if next_type not in ["Общая средняя", "Кот", "Собака", "Манул", "Двойная средняя"]:
                        next_type = current_animal
                except:
                    logger.warning(f"[ЦЕПОЧКА] Некорректный пасс '{pass_val}' для ID {current_id}")
                    break

            if next_id == 0:
                logger.info(f"[ЦЕПОЧКА] Достигнут ID 0, цепочка прервана")
                break

            # Проверяем, существует ли строка с таким ID и типом
            next_row = df[(df['ID'] == str(next_id)) & (df['Животное'] == next_type)]
            if next_row.empty:
                # Если нет, пробуем искать по ID без типа (fallback)
                next_row = df[df['ID'] == str(next_id)]
                if next_row.empty:
                    logger.info(f"[ЦЕПОЧКА] ID {next_id} не найден ни с каким животным")
                    break
                # берём первое попавшееся животное
                next_type = next_row.iloc[0].get('Животное', current_animal)
                logger.info(f"[ЦЕПОЧКА] Для ID {next_id} использован тип {next_type} (fallback)")

            # Добавляем пару (данные для линии)
            from_time = row.iloc[0].get('Поправка_прогноза', '')
            to_time = next_row.iloc[0].get('Поправка_прогноза', '')
            chain_pairs.append({
                'from_id': current_id,
                'to_id': next_id,
                'from_type': current_animal,
                'to_type': next_type,
                'from_time': from_time,
                'to_time': to_time,
                # Цвета и стили можно взять из строк
            })

            current_id = next_id
            current_animal = next_type

        if len(chain_ids) < 2:
            logger.info(f"[ЦЕПОЧКА] Недостаточно ID для цепочки (нужно минимум 2)")
            return None

        # Сортируем пары по времени (если есть)
        # (дополнительно можно отсортировать цепочку по времени из колонки 'Поправка_прогноза')
        try:
            # Преобразуем времена в datetime для сортировки
            sorted_pairs = []
            for pair in chain_pairs:
                try:
                    from_dt = datetime.strptime(pair['from_time'], '%Y-%m-%d %H:%M:%S') if pair['from_time'] else None
                    to_dt = datetime.strptime(pair['to_time'], '%Y-%m-%d %H:%M:%S') if pair['to_time'] else None
                    sorted_pairs.append((pair, from_dt, to_dt))
                except:
                    sorted_pairs.append((pair, None, None))
            # Сортируем по from_time, если есть
            sorted_pairs.sort(key=lambda x: x[1] if x[1] else datetime.min)
            chain_pairs = [p[0] for p in sorted_pairs]
        except Exception as e:
            logger.warning(f"[ЦЕПОЧКА] Не удалось отсортировать пары: {e}")

        result = {
            'chain_ids': chain_ids,
            'chain_pairs': chain_pairs,
            'animal': animal
        }
        logger.info(f"[ЦЕПОЧКА] Построена цепочка для ID {start_id}, животное {animal}, пар: {len(chain_pairs)}")
        return result

    def get_chain_for_id_and_animal(self, id_val, animal):
        """Возвращает цепочку для указанного ID и животного."""
        chains = self.chains_data.get("chains", {})
        id_str = str(id_val)
        if id_str in chains and animal in chains[id_str]:
            return chains[id_str][animal]
        return None
    
    def build_all_chains(self, ch_client=None):
        """Строит все цепочки из TAIL_CORRECTIONS.csv и сохраняет их"""
        if not os.path.exists(self.corrections_file):
            print(f"[CHAINS] Файл {self.corrections_file} не найден")
            return False
        
        try:
            df = pd.read_csv(self.corrections_file, sep=';', encoding='utf-8-sig')
            chains = {}
            
            # Загружаем FINAL_RESULTS.csv для цветов
            final_results = None
            if os.path.exists("FINAL_RESULTS.csv"):
                final_results = pd.read_csv("FINAL_RESULTS.csv", sep=';', encoding='utf-8-sig')
            
            # Для каждого ID строим цепочку
            for idx, row in df.iterrows():
                start_id = row.get('ID')
                if pd.isna(start_id):
                    continue
                
                start_id = int(start_id)
                chain = self.build_chain_for_id(start_id, df, final_results, ch_client)
                if chain and len(chain) > 1:  # Сохраняем только цепочки с хотя бы одной связью
                    chains[str(start_id)] = chain
            
            self.chains_data["chains"] = chains
            self.save_chains()

            return True
            
        except Exception as e:
            print(f"[CHAINS] Ошибка построения цепочек: {str(e)}")
            import traceback
            traceback.print_exc()
            return False
    
    def build_chain_for_id(self, start_id, df, final_results=None, ch_client=None):
        """
        Строит цепочку для конкретного ID
        """
        # ⭐ ЗАЩИТА ОТ РЕКУРСИИ ⭐
        if hasattr(self, '_building_chain') and self._building_chain:
            print(f"[BUILD_CHAIN] ⚠️ Уже строится цепочка, пропускаем ID {start_id}")
            return None

        self._building_chain = True

        try:
            chain_ids = []
            chain_pairs = []
            current_id = start_id
            visited = set()

            # Сначала собираем все ID в цепочке
            while current_id is not None and current_id != 0 and current_id not in visited:
                visited.add(current_id)
                chain_ids.append(current_id)

                # Ищем строку с текущим ID
                row = df[df['ID'].astype(str) == str(current_id)]
                if row.empty:
                    print(f"[BUILD_CHAIN] ❌ ID {current_id} не найден в DataFrame, прерываем")
                    break

                pass_value = row.iloc[0].get('цепь', '')

                try:
                    if pass_value and str(pass_value).strip() and str(pass_value).strip() != '':
                        next_id = int(float(str(pass_value).strip()))

                        if next_id == 0:
                            print(f"[BUILD_CHAIN] Достигнут ID 0, прерываем")
                            break
                        current_id = next_id
                    else:
                        print(f"[BUILD_CHAIN] Пустое значение 'цепь', прерываем")
                        break
                except (ValueError, TypeError) as e:
                    print(f"[BUILD_CHAIN] Ошибка преобразования: {e}")
                    break

            if len(chain_ids) < 2:
                print(f"[BUILD_CHAIN] ❌ Недостаточно ID для цепочки (нужно минимум 2), возвращаем None")
                return None

            # Получаем времена для каждого ID
            id_time_map = {}
            for id_val in chain_ids:
                row = df[df['ID'].astype(str) == str(id_val)]
                if not row.empty:
                    time_str = row.iloc[0].get('Поправка_прогноза', '')
                    if time_str and not pd.isna(time_str) and time_str != '':
                        try:
                            dt = datetime.strptime(str(time_str), '%Y-%m-%d %H:%M:%S')
                            id_time_map[id_val] = dt
                        except Exception as e:
                            print(f"[BUILD_CHAIN]   ❌ Ошибка парсинга времени для ID {id_val}: {e}")
                            pass
                    else:
                        print(f"[BUILD_CHAIN]   ⚠️ Пустое время для ID {id_val}")
                else:
                    print(f"[BUILD_CHAIN]   ❌ ID {id_val} не найден при поиске времени")

            if len(id_time_map) < 2:
                print(f"[BUILD_CHAIN] ❌ Недостаточно временных меток (нужно минимум 2), возвращаем None")
                return None

            # Сортируем по времени
            sorted_ids = sorted(id_time_map.keys(), key=lambda x: id_time_map[x])

            # Создаем пары в хронологическом порядке
            for i in range(len(sorted_ids) - 1):
                left_id = sorted_ids[i]
                right_id = sorted_ids[i + 1]

                left_row = df[df['ID'].astype(str) == str(left_id)]
                right_row = df[df['ID'].astype(str) == str(right_id)]

                if left_row.empty or right_row.empty:
                    print(f"[BUILD_CHAIN]   ⚠️ Не найдены строки для {left_id} или {right_id}, пропускаем")
                    continue

                # Получаем данные
                left_time_str = left_row.iloc[0].get('Поправка_прогноза', '')
                right_time_str = right_row.iloc[0].get('Поправка_прогноза', '')

                if not left_time_str or pd.isna(left_time_str) or left_time_str == '':
                    print(f"[BUILD_CHAIN]   ⚠️ Пустое left_time, пропускаем")
                    continue
                if not right_time_str or pd.isna(right_time_str) or right_time_str == '':
                    print(f"[BUILD_CHAIN]   ⚠️ Пустое right_time, пропускаем")
                    continue

                # Получаем тип цепи из правой точки
                chain_type = right_row.iloc[0].get('Тип_цепи', 'серия')

                # Получаем цвет и тип линии
                base_color = "yellow"
                line_type = "главный"

                if final_results is not None:
                    color_row = final_results[final_results['Позиция'].astype(str) == str(right_id)]
                    if not color_row.empty:
                        color_from_final = color_row.iloc[0].get('Цвет', '')
                        if pd.notna(color_from_final) and color_from_final != '':
                            base_color = str(color_from_final).lower()

                        type_from_final = color_row.iloc[0].get('Тип', '')
                        if pd.notna(type_from_final) and type_from_final != '':
                            line_type = str(type_from_final)

                if base_color == "yellow":
                    base_color_from_corr = right_row.iloc[0].get('Цвет', 'yellow')
                    if pd.notna(base_color_from_corr) and base_color_from_corr != '':
                        base_color = str(base_color_from_corr).lower()

                if line_type == "главный":
                    type_from_corr = right_row.iloc[0].get('Тип', 'главный')
                    if pd.notna(type_from_corr) and type_from_corr != '':
                        line_type = str(type_from_corr)

                # ========== ПОЛУЧЕНИЕ ЦЕН ИЗ БД (ОБЯЗАТЕЛЬНО) ==========
                if ch_client is None:
                    print(f"[BUILD_CHAIN] ❌ ch_client не передан, невозможно получить цены для ID {start_id}")
                    return None

                try:
                    left_dt = datetime.strptime(str(left_time_str), '%Y-%m-%d %H:%M:%S')
                    right_dt = datetime.strptime(str(right_time_str), '%Y-%m-%d %H:%M:%S')
                except Exception as e:
                    print(f"[BUILD_CHAIN] ❌ Ошибка парсинга времени: {e}")
                    continue

                left_price = self._get_nearest_price(ch_client, left_dt, left_id)
                right_price = self._get_nearest_price(ch_client, right_dt, right_id)

                if left_price is None or right_price is None:
                    print(f"[BUILD_CHAIN] ⚠️ Не удалось получить цены для пары {left_id}->{right_id}, пропускаем")
                    continue

                # Создаем пару
                pair = {
                    "from_id": left_id,
                    "to_id": right_id,
                    "chain_type": chain_type,
                    "color": base_color,
                    "line_type": line_type,
                    "from_time": left_time_str,
                    "to_time": right_time_str,
                    "from_price": left_price,
                    "to_price": right_price
                }
                chain_pairs.append(pair)

            if not chain_pairs:
                print(f"[BUILD_CHAIN] ❌ Не создано ни одной пары, возвращаем None")
                return None

            result = {
                "chain_ids": chain_ids,
                "chain_pairs": chain_pairs
            }
            print(f"[BUILD_CHAIN] ===== УСПЕШНО построена цепочка для ID {start_id} с {len(chain_pairs)} парами =====\n")
            return result

        except Exception as e:
            print(f"[BUILD_CHAIN] ❌ Критическая ошибка: {str(e)}")
            import traceback
            traceback.print_exc()
            return None

        finally:
            self._building_chain = False
    
    def _get_nearest_price(self, ch_client, target_dt, id_val):
        """Находит ближайшую цену из БД (как в оригинальном коде)"""
        try:
            # Сначала пробуем точное совпадение
            query = f"""
                SELECT close 
                FROM crypto_data.btc_usdt_1m 
                WHERE timestamp = '{target_dt.strftime('%Y-%m-%d %H:%M:%S')}'
                LIMIT 1
            """
            result = ch_client.execute(query)
            if result and len(result) > 0:
                return float(result[0][0])
            
            # Ищем ближайшее
            query_before = f"""
                SELECT timestamp, close 
                FROM crypto_data.btc_usdt_1m 
                WHERE timestamp <= '{target_dt.strftime('%Y-%m-%d %H:%M:%S')}'
                ORDER BY timestamp DESC
                LIMIT 1
            """
            result_before = ch_client.execute(query_before)
            
            query_after = f"""
                SELECT timestamp, close 
                FROM crypto_data.btc_usdt_1m 
                WHERE timestamp >= '{target_dt.strftime('%Y-%m-%d %H:%M:%S')}'
                ORDER BY timestamp ASC
                LIMIT 1
            """
            result_after = ch_client.execute(query_after)
            
            best_price = None
            best_diff = float('inf')
            
            if result_before and len(result_before) > 0:
                ts_before = result_before[0][0]
                price_before = float(result_before[0][1])
                diff_before = abs((ts_before - target_dt).total_seconds() / 60)
                if diff_before < best_diff:
                    best_diff = diff_before
                    best_price = price_before
            
            if result_after and len(result_after) > 0:
                ts_after = result_after[0][0]
                price_after = float(result_after[0][1])
                diff_after = abs((ts_after - target_dt).total_seconds() / 60)
                if diff_after < best_diff:
                    best_diff = diff_after
                    best_price = price_after
            
            if best_price is not None and best_diff <= 1:  # Допустимая разница 1 минута
                return best_price
            
            # ⭐ ИСПРАВЛЕНИЕ: Если цена не найдена в интервале, возвращаем последнюю свечу из базы ⭐
            query_last = """
                SELECT close 
                FROM crypto_data.btc_usdt_1m 
                ORDER BY timestamp DESC 
                LIMIT 1
            """
            result_last = ch_client.execute(query_last)
            if result_last and len(result_last) > 0:
                last_price = float(result_last[0][0])
                print(f"    [БД] Цена для ID {id_val} не найдена, используем последнюю свечу: {last_price:.2f}")
                return last_price
            
        except Exception as e:
            print(f"    [БД] Ошибка поиска цены для ID {id_val}: {str(e)}")
        
        # Если даже последнюю свечу не удалось получить, возвращаем 50000 как запасной вариант
        print(f"    [БД] Критическая ошибка для ID {id_val}, возвращаем 50000")
        return None
    
    def get_chain_for_id(self, id_val):
        """Возвращает готовую цепочку для указанного ID"""
        return self.chains_data.get("chains", {}).get(str(id_val))

class ChainManagerDialog(QtWidgets.QDialog):
    """Диалог для просмотра и удаления цепочек из CHAINS_DATA.json"""
    def __init__(self, chain_manager, parent=None):
        super().__init__(parent)
        self.chain_manager = chain_manager
        self.setWindowTitle("Менеджер цепочек")
        self.setMinimumSize(800, 600)
        layout = QtWidgets.QVBoxLayout(self)

        self.table = QtWidgets.QTableWidget()
        self.table.setColumnCount(4)
        self.table.setHorizontalHeaderLabels(["ID", "Животное", "Цепочка", "Действие"])
        self.table.horizontalHeader().setStretchLastSection(True)
        layout.addWidget(self.table)

        # Кнопки управления
        btn_layout = QtWidgets.QHBoxLayout()
        btn_refresh = QtWidgets.QPushButton("Обновить")
        btn_refresh.clicked.connect(self.refresh_table)
        btn_close = QtWidgets.QPushButton("Закрыть")
        btn_close.clicked.connect(self.accept)
        btn_layout.addWidget(btn_refresh)
        btn_layout.addStretch()
        btn_layout.addWidget(btn_close)
        layout.addLayout(btn_layout)

        self.refresh_table()

    def refresh_table(self):
        """Обновляет таблицу, загружая актуальные цепочки из chain_manager"""
        self.table.setRowCount(0)
        chains = self.chain_manager.chains_data.get("chains", {})

        # Множество животных, которые используются как ключи
        animal_keys = {"Кот", "Собака", "Манул", "Общая средняя", "Двойная средняя"}

        for id_str, data in chains.items():
            if not data:
                continue  # пустой объект, например "178": {}

            # Проверяем, есть ли на верхнем уровне цепочка (поля chain_ids, chain_pairs)
            has_top_level_chain = "chain_ids" in data and "chain_pairs" in data

            # Собираем вложенные животные
            animal_entries = {}
            for key, value in data.items():
                if key in animal_keys and isinstance(value, dict):
                    if "chain_ids" in value and "chain_pairs" in value:
                        animal_entries[key] = value

            # Если есть верхнеуровневая цепочка – показываем её как "Общая"
            if has_top_level_chain:
                chain_ids = data.get("chain_ids", [])
                chain_str = " -> ".join(str(id) for id in chain_ids) if chain_ids else "(пусто)"
                row = self.table.rowCount()
                self.table.insertRow(row)
                self.table.setItem(row, 0, QtWidgets.QTableWidgetItem(id_str))
                self.table.setItem(row, 1, QtWidgets.QTableWidgetItem("Общая"))
                self.table.setItem(row, 2, QtWidgets.QTableWidgetItem(chain_str))
                btn_delete = QtWidgets.QPushButton("🗑️ Удалить")
                btn_delete.clicked.connect(lambda checked, i=id_str, a="Общая": self.delete_chain(i, a))
                self.table.setCellWidget(row, 3, btn_delete)

            # Показываем каждое вложенное животное
            for animal, animal_data in animal_entries.items():
                chain_ids = animal_data.get("chain_ids", [])
                chain_str = " -> ".join(str(id) for id in chain_ids) if chain_ids else "(пусто)"
                row = self.table.rowCount()
                self.table.insertRow(row)
                self.table.setItem(row, 0, QtWidgets.QTableWidgetItem(id_str))
                self.table.setItem(row, 1, QtWidgets.QTableWidgetItem(animal))
                self.table.setItem(row, 2, QtWidgets.QTableWidgetItem(chain_str))
                btn_delete = QtWidgets.QPushButton("🗑️ Удалить")
                btn_delete.clicked.connect(lambda checked, i=id_str, a=animal: self.delete_chain(i, a))
                self.table.setCellWidget(row, 3, btn_delete)

        self.table.resizeColumnsToContents()

    def delete_chain(self, id_str, animal):
        """Удаляет цепочку для указанного ID и животного после подтверждения"""
        reply = QtWidgets.QMessageBox.question(
            self,
            "Подтверждение удаления",
            f"Удалить цепочку для ID {id_str} и животного '{animal}'?",
            QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No
        )
        if reply == QtWidgets.QMessageBox.Yes:
            chains = self.chain_manager.chains_data.get("chains", {})
            if id_str in chains:
                if animal == "Общая":
                    # Удаляем верхнеуровневую цепочку (поля chain_ids, chain_pairs)
                    chains[id_str].pop("chain_ids", None)
                    chains[id_str].pop("chain_pairs", None)
                    # Если после удаления объект пуст – удаляем весь ID
                    if not chains[id_str]:
                        del chains[id_str]
                else:
                    # Удаляем вложенное животное
                    if animal in chains[id_str]:
                        del chains[id_str][animal]
                        if not chains[id_str]:  # если животных не осталось
                            del chains[id_str]
                self.chain_manager.save_chains()
                self.refresh_table()
                QtWidgets.QMessageBox.information(self, "Успех", f"Цепочка для ID {id_str} ({animal}) удалена.")

class DcmAntiBuilderWorker(QtCore.QThread):
    finished_signal = QtCore.pyqtSignal(dict)
    error_signal = QtCore.pyqtSignal(str)
    progress_signal = QtCore.pyqtSignal(int, int)
    log_signal = QtCore.pyqtSignal(str)
    status_signal = QtCore.pyqtSignal(str)

    def __init__(self, ch_config, timeframe):
        super().__init__()
        self.ch_config = ch_config
        self.timeframe = timeframe
        self._is_running = True
        self._client = None

    def run(self):
        try:
            self._client = ClickHouseClient(
                host=self.ch_config['host'],
                port=self.ch_config['port'],
                user=self.ch_config['user'],
                password=self.ch_config['password'],
                settings={'insert_block_size': 10000, 'connect_timeout': 30}
            )

            self.log_signal.emit(f"[DCM-ANTI] Загрузка анти-ID из {self.timeframe}...")
            self.status_signal.emit("Загрузка анти-ID...")

            # 1. Загружаем все анти-ID (antilong и antishort)
            query_ids = f"""
                SELECT id, start_time, end_time, direction
                FROM crypto_data.auto_ids
                WHERE timeframe = '{self.timeframe}'
                  AND direction IN ('antilong', 'antishort')
                ORDER BY id
            """
            rows = self._client.execute(query_ids)
            total = len(rows)
            if total == 0:
                self.error_signal.emit("Нет анти-ID для обработки")
                return

            self.log_signal.emit(f"[DCM-ANTI] Загружено {total} анти-ID")
            self.status_signal.emit(f"Загружено {total} анти-ID. Начинаем расчёт DCM...")

            # 2. Создаём таблицу, если её нет
            self._ensure_table()

            # 3. Удаляем старые записи для этого ТФ
            self._client.execute(
                f"ALTER TABLE crypto_data.dcm_anti_precomputed DELETE WHERE timeframe = '{self.timeframe}'"
            )
            self.log_signal.emit("[DCM-ANTI] Старые записи удалены")

            # 4. Расчёт DCM для каждого ID (пакетная вставка)
            tf_minutes = {'30m': 30, '1h': 60, '4h': 240}[self.timeframe]
            batch_size = 10000
            buffer = []
            total_inserted = 0
            start_time = time.time()

            self.status_signal.emit("Расчёт DCM...")

            for idx, (id_val, start_dt, end_dt, direction) in enumerate(rows):
                if not self._is_running:
                    break

                # Вычисляем DCM через функцию compute_dcm_from_seconds
                start_sec = int(start_dt.timestamp())
                end_sec = int(end_dt.timestamp())
                dog_ts, cat_ts, manul_ts = compute_dcm_from_seconds(start_sec, end_sec, tf_minutes)

                dog_dt = datetime.fromtimestamp(dog_ts)
                cat_dt = datetime.fromtimestamp(cat_ts)
                manul_dt = datetime.fromtimestamp(manul_ts)

                buffer.append((id_val, self.timeframe, direction, dog_dt, cat_dt, manul_dt))

                if len(buffer) >= batch_size:
                    self._flush_buffer(buffer)
                    buffer.clear()
                    total_inserted += len(buffer)  # но buffer уже очищен, поэтому надо считать до очистки
                    # Пересчитаем: правильнее считать накопленное количество
                    # Мы будем считать общее количество вставленных записей через len(buffer) до flush

                # Обновляем прогресс каждые 1000 ID
                if idx % 1000 == 0 or idx == total - 1:
                    self.progress_signal.emit(idx + 1, total)
                    elapsed = time.time() - start_time
                    if elapsed > 0 and idx > 0:
                        rate = (idx + 1) / elapsed
                        remaining = total - (idx + 1)
                        eta = remaining / rate if rate > 0 else 0
                        eta_min = int(eta // 60)
                        eta_sec = int(eta % 60)
                        self.status_signal.emit(
                            f"Обработано {idx+1}/{total} анти-ID, вставлено {total_inserted} DCM-записей, "
                            f"скорость {rate:.1f} ID/сек, ETA {eta_min} мин {eta_sec} сек"
                        )

            # Остатки
            if buffer:
                self._flush_buffer(buffer)
                total_inserted += len(buffer)

            elapsed_total = time.time() - start_time
            self.log_signal.emit(f"[DCM-ANTI] Готово. Вставлено {total_inserted} DCM-записей за {elapsed_total:.2f} сек")
            self.status_signal.emit(f"Готово! Вставлено {total_inserted} DCM-записей за {elapsed_total:.2f} сек")
            self.finished_signal.emit({self.timeframe: total_inserted})

        except Exception as e:
            self.error_signal.emit(str(e))
            import traceback
            self.log_signal.emit(traceback.format_exc())
        finally:
            if self._client:
                try:
                    self._client.disconnect()
                except:
                    pass

    def _ensure_table(self):
        """Создаёт таблицу dcm_anti_precomputed, если её нет."""
        self._client.execute("""
            CREATE TABLE IF NOT EXISTS crypto_data.dcm_anti_precomputed (
                id UInt64,
                timeframe String,
                direction String,
                dog_time DateTime,
                cat_time DateTime,
                manul_time DateTime
            ) ENGINE = MergeTree()
            ORDER BY (timeframe, id)
        """)

    def _flush_buffer(self, buffer):
        if not buffer:
            return
        self._client.execute(
            "INSERT INTO crypto_data.dcm_anti_precomputed (id, timeframe, direction, dog_time, cat_time, manul_time) VALUES",
            buffer
        )
        self.log_signal.emit(f"[DCM-ANTI] Вставлено {len(buffer)} записей")

    def stop(self):
        self._is_running = False
        self.log_signal.emit("[DCM-ANTI] Остановка по запросу")

# =====================================================================
# НОВЫЙ КЛАСС: AntiMatcherTestWorker – сопоставитель анти-ID с группами
# =====================================================================
class AntiMatcherTestWorker(QtCore.QThread):
    """
    Тестовый сопоставитель для анти-ID (второй мир).
    Для каждой позиции из time_pairs_4h.csv берёт 9 пар дат из групп (1-2, 3-4, ... 17-18),
    затем по датам каждой пары ищет соответствующий анти-ID в БД (направление antilong/antishort),
    и для найденного анти-ID ищет пересечения квалификаторов на 1h и 30m.
    """
    finished_signal = QtCore.pyqtSignal(list)  # список результатов
    error_signal = QtCore.pyqtSignal(str)
    progress_signal = QtCore.pyqtSignal(int, int)
    status_signal = QtCore.pyqtSignal(str)
    log_signal = QtCore.pyqtSignal(str)

    def __init__(self, ch_config, source_timeframe='4h', target_timeframes=None, animal='Собака', target_ids=None):
        """
        ch_config: dict с параметрами ClickHouse
        source_timeframe: ТФ, из которого берутся анти-ID (всегда 4h)
        target_timeframes: список ТФ для поиска пересечений (по умолчанию ['1h', '30m'])
        animal: животное, чьи даты групп использовать ('Собака', 'Кот', 'Манул')
        target_ids: список номеров позиций (из time_pairs_4h.csv) для обработки; если None – все
        """
        super().__init__()
        self.ch_config = ch_config
        self.source_tf = source_timeframe
        self.target_tfs = target_timeframes or ['1h', '30m']
        self.animal = animal
        self.target_ids = target_ids  # список позиций (номеров строк)
        self._client = None
        self._is_running = True

    def run(self):
        try:
            self._client = ClickHouseClient(
                host=self.ch_config['host'],
                port=self.ch_config['port'],
                user=self.ch_config['user'],
                password=self.ch_config['password'],
                settings={'insert_block_size': 10000, 'connect_timeout': 30}
            )
            self.log_signal.emit("[ANTI-MATCHER] Загрузка позиций из time_pairs_4h.csv...")
            self.status_signal.emit("Загрузка позиций из файла...")

            # 1. Загружаем позиции из time_pairs_4h.csv
            time_pairs_file = "time_pairs_4h.csv"
            if not os.path.exists(time_pairs_file):
                self.error_signal.emit(f"Файл {time_pairs_file} не найден")
                return

            positions = []
            with open(time_pairs_file, 'r', encoding='utf-8') as f:
                reader = csv.reader(f)
                try:
                    next(reader)  # пропускаем заголовок
                except StopIteration:
                    self.error_signal.emit("Файл time_pairs_4h.csv пуст")
                    return
                for idx, row in enumerate(reader, start=1):
                    if len(row) >= 6:
                        try:
                            datetime.strptime(row[0], '%Y-%m-%d %H:%M:%S')
                            datetime.strptime(row[2], '%Y-%m-%d %H:%M:%S')
                            if self.target_ids:
                                if idx in self.target_ids:
                                    positions.append(idx)
                            else:
                                positions.append(idx)
                        except:
                            continue

            if not positions:
                self.error_signal.emit("Нет позиций для обработки (проверьте фильтр ID)")
                return

            total = len(positions)
            self.log_signal.emit(f"[ANTI-MATCHER] Загружено {total} позиций")
            self.status_signal.emit(f"Загружено {total} позиций. Загружаем пересечения...")

            # 2. Загружаем пересечения для целевых ТФ
            intersections = {}
            for tf in self.target_tfs:
                query = f"""
                    SELECT timestamp, intersection_type, (price1 + price2)/2 AS price
                    FROM crypto_data.qualifier_intersections
                    WHERE timeframe = '{tf}'
                    ORDER BY timestamp
                """
                rows_inter = self._client.execute(query)
                if not rows_inter:
                    self.error_signal.emit(f"Нет пересечений для таймфрейма {tf}. Сначала запустите генерацию пересечений.")
                    return

                tf_data = {}
                for ts, inter_type, price in rows_inter:
                    tf_data.setdefault(inter_type, []).append((ts, float(price)))
                intersections[tf] = tf_data
                self.log_signal.emit(f"[ANTI-MATCHER] Загружено {len(rows_inter)} пересечений для {tf}")

            # 3. Загружаем группы для всех позиций из JSON-файлов
            self.log_signal.emit("[ANTI-MATCHER] Загрузка данных групп из JSON...")
            group_data = self._load_group_data_for_positions(positions)
            if not group_data:
                self.error_signal.emit("Не удалось загрузить данные групп из JSON-файлов")
                return

            # 4. Для каждой позиции и каждой пары дат ищем соответствующий анти-ID в БД
            self.log_signal.emit("[ANTI-MATCHER] Поиск анти-ID по датам пар в БД...")
            anti_ids_cache = {}  # {pos: {pair_key: (anti_id, start_dt, end_dt)}}
            for pos, id_groups in group_data.items():
                anti_ids_cache[pos] = {}
                for pair_key, pair in id_groups.items():
                    start_dt = pair['start']
                    end_dt = pair['end']
                    anti_id = self._find_anti_id_by_dates(start_dt, end_dt, self.source_tf)
                    if anti_id:
                        anti_ids_cache[pos][pair_key] = anti_id
                        self.log_signal.emit(f"[ANTI-MATCHER] Позиция {pos}, пара {pair_key} -> анти-ID {anti_id}")
                    else:
                        self.log_signal.emit(f"[ANTI-MATCHER] Позиция {pos}, пара {pair_key} -> анти-ID не найден")

            # 5. Обрабатываем каждую позицию
            results = []
            processed = 0
            start_time = time.time()

            for idx, pos in enumerate(positions):
                if not self._is_running:
                    break

                pos_anti = anti_ids_cache.get(pos, {})
                if not pos_anti:
                    self.log_signal.emit(f"[ANTI-MATCHER] Для позиции {pos} не найдено ни одного анти-ID, пропускаем")
                    continue

                result_row = {
                    'position': pos,
                    'direction': None,  # будет заполнено при обработке первого анти-ID
                    'groups': []
                }

                # Для каждой пары, для которой найден анти-ID, используем его
                for pair_key, anti_id in pos_anti.items():
                    # Получаем start и end из group_data
                    pair_data = group_data[pos].get(pair_key)
                    if not pair_data:
                        continue
                    start_group = pair_data['start']
                    end_group = pair_data['end']

                    # Теперь получаем направление анти-ID из БД (это нужно для выбора типов пересечений)
                    direction = self._get_direction_for_anti_id(anti_id, self.source_tf)
                    if not direction:
                        self.log_signal.emit(f"[ANTI-MATCHER] Не удалось получить направление для анти-ID {anti_id}")
                        continue
                    result_row['direction'] = direction  # задаём направление для всей позиции (все пары одного направления)

                    # Определяем типы пересечений в зависимости от направления
                    if direction == 'antilong':
                        first_type = 'long_start_short_end_down'
                        first_extreme = 'max'
                        second_type = 'short_start_long_end_up'
                        second_extreme = 'min'
                    else:  # antishort
                        first_type = 'short_start_long_end_up'
                        first_extreme = 'min'
                        second_type = 'long_start_short_end_down'
                        second_extreme = 'max'

                    tf_results = {}
                    for tf in self.target_tfs:
                        tf_data = intersections.get(tf)
                        if not tf_data:
                            continue

                        first_ts, first_price = self._find_extreme_in_range(
                            tf_data.get(first_type, []),
                            start_group,
                            start_group + timedelta(hours=9),
                            first_extreme
                        )
                        second_ts, second_price = self._find_extreme_in_range(
                            tf_data.get(second_type, []),
                            end_group - timedelta(hours=9),
                            end_group,
                            second_extreme
                        )

                        tf_results[tf] = {
                            'first_ts': first_ts,
                            'first_price': first_price,
                            'second_ts': second_ts,
                            'second_price': second_price
                        }

                    result_row['groups'].append({
                        'group_pair': pair_key,
                        'start_dt': start_group,
                        'end_dt': end_group,
                        'anti_id': anti_id,
                        'targets': tf_results
                    })

                if result_row['groups']:
                    results.append(result_row)

                processed = idx + 1
                if processed % 5 == 0 or processed == total:
                    elapsed = time.time() - start_time
                    rate = processed / elapsed if elapsed > 0 else 0
                    eta = (total - processed) / rate if rate > 0 else 0
                    self.status_signal.emit(
                        f"Обработано {processed}/{total} позиций, "
                        f"скорость {rate:.1f} поз/сек, ETA {eta:.0f} сек"
                    )
                    self.progress_signal.emit(processed, total)

            self.finished_signal.emit(results)

        except Exception as e:
            self.error_signal.emit(str(e))
            import traceback
            self.log_signal.emit(traceback.format_exc())
        finally:
            if self._client:
                try:
                    self._client.disconnect()
                except:
                    pass

    def _find_anti_id_by_dates(self, start_dt, end_dt, timeframe, tolerance_seconds=60):
        """Ищет анти-ID в БД по точному совпадению дат (с допуском)."""
        start_str = start_dt.strftime('%Y-%m-%d %H:%M:%S')
        end_str = end_dt.strftime('%Y-%m-%d %H:%M:%S')
        query = f"""
            SELECT id
            FROM crypto_data.auto_ids
            WHERE timeframe = '{timeframe}'
              AND direction IN ('antilong', 'antishort')
              AND abs(dateDiff('second', start_time, toDateTime('{start_str}'))) <= {tolerance_seconds}
              AND abs(dateDiff('second', end_time, toDateTime('{end_str}'))) <= {tolerance_seconds}
            LIMIT 1
        """
        try:
            rows = self._client.execute(query)
            if rows:
                return rows[0][0]
        except Exception as e:
            self.log_signal.emit(f"[ANTI-MATCHER] Ошибка поиска анти-ID: {e}")
        return None

    def _get_direction_for_anti_id(self, anti_id, timeframe):
        """Возвращает направление анти-ID из БД."""
        query = f"SELECT direction FROM crypto_data.auto_ids WHERE id = {anti_id} AND timeframe = '{timeframe}' LIMIT 1"
        try:
            rows = self._client.execute(query)
            if rows:
                return rows[0][0]
        except Exception as e:
            self.log_signal.emit(f"[ANTI-MATCHER] Ошибка получения направления: {e}")
        return None

    def _load_group_data_for_positions(self, positions):
        """
        Загружает из GROUP_TIMES_DATA.json и MIRROR_GROUP_TIMES.json
        даты групп для указанных позиций (условных ID) для ТФ self.source_tf.
        Возвращает словарь {position: {pair_key: {'start': dt, 'end': dt}}}
        """
        group_data = {}
        animal = self.animal

        group_file = "GROUP_TIMES_DATA.json"
        mirror_file = "MIRROR_GROUP_TIMES.json"

        if not os.path.exists(group_file) or not os.path.exists(mirror_file):
            self.log_signal.emit("[ANTI-MATCHER] JSON-файлы групп не найдены")
            return {}

        try:
            with open(group_file, 'r', encoding='utf-8') as f:
                group_json = json.load(f)
            with open(mirror_file, 'r', encoding='utf-8') as f:
                mirror_json = json.load(f)
        except Exception as e:
            self.log_signal.emit(f"[ANTI-MATCHER] Ошибка чтения JSON: {e}")
            return {}

        def get_animal_time(val):
            if isinstance(val, dict):
                return val.get(animal)
            elif isinstance(val, str):
                return val if animal == "Собака" else None
            return None

        for pos in positions:
            id_str = str(pos)
            group_data[pos] = {}

            pairs = [
                (1, 2, '1-2'),
                (3, 4, '3-4'),
                (5, 6, '5-6'),
                (7, 8, '7-8'),
                (9, 10, '9-10'),
                (11, 12, '11-12'),
                (13, 14, '13-14'),
                (15, 16, '15-16'),
                (17, 18, '17-18')
            ]

            for g1, g2, key in pairs:
                start_dt = None
                end_dt = None

                if g1 <= 6:
                    times_dict = group_json.get(f'group{g1}_times', {}).get(self.source_tf, {})
                else:
                    times_dict = mirror_json.get(f'mirror_group{g1}_times', {}).get(self.source_tf, {})

                if id_str in times_dict:
                    val = times_dict[id_str]
                    time_str = get_animal_time(val)
                    if time_str:
                        try:
                            start_dt = datetime.strptime(time_str, '%Y-%m-%d %H:%M:%S')
                        except:
                            pass

                if g2 <= 6:
                    times_dict2 = group_json.get(f'group{g2}_times', {}).get(self.source_tf, {})
                else:
                    times_dict2 = mirror_json.get(f'mirror_group{g2}_times', {}).get(self.source_tf, {})

                if id_str in times_dict2:
                    val = times_dict2[id_str]
                    time_str = get_animal_time(val)
                    if time_str:
                        try:
                            end_dt = datetime.strptime(time_str, '%Y-%m-%d %H:%M:%S')
                        except:
                            pass

                if start_dt and end_dt:
                    group_data[pos][key] = {
                        'start': start_dt,
                        'end': end_dt
                    }

        return group_data

    def _find_extreme_in_range(self, points, start_dt, end_dt, extreme):
        """Ищет точку с экстремальной ценой (max или min) среди points в [start_dt, end_dt]."""
        if not points:
            return None, None
        start_ts = start_dt.timestamp()
        end_ts = end_dt.timestamp()
        import bisect
        timestamps = [p[0].timestamp() for p in points]
        left = bisect.bisect_left(timestamps, start_ts)
        right = bisect.bisect_right(timestamps, end_ts)
        if left >= right:
            return None, None
        if extreme == 'max':
            best_idx = max(range(left, right), key=lambda i: points[i][1])
        else:
            best_idx = min(range(left, right), key=lambda i: points[i][1])
        return points[best_idx]

    def stop(self):
        self._is_running = False
            
class Worker(QtCore.QThread):
    update_signal = QtCore.pyqtSignal(object)
    error_signal = QtCore.pyqtSignal(str)
    def __init__(self, timeframe_manager, parent=None):
        super().__init__(parent)
        self.log_ssl_info()
        self.timeframe_manager = timeframe_manager
        # Создаём сессию с отключением системного прокси
        session = requests.Session()
        session.trust_env = False
        # Явно указываем путь к сертификатам (для WSL/Windows)
        session.verify = certifi.where()  # используем certifi
        # Увеличиваем таймауты
        session.timeout = (30, 60)  # (connect, read) секунд
        
        self.exchange = ccxt.binance({
            'enableRateLimit': True,
            'timeout': 60000,          # увеличен до 60 секунд
            'verify': False,           # отключаем проверку SSL (временно)
            'session': session,
            'options': {
                'adjustForTimeDifference': True,
            }
        })
        # Дополнительно отключаем проверку SSL для exchange
        self.exchange.session.verify = False
        requests.packages.urllib3.disable_warnings()
        self.log_file = "minute_candles_update.log"
        self.ch_client = ClickHouseManager()
        self._is_running = True
    def run(self):
        logger.info("[Worker] Запущен")
        self._log_message("Starting candle update process")
        self._log_message(f"Current timeframe: {self.timeframe_manager.current_timeframe}")
        try:
            last_ts = self._get_last_clickhouse_timestamp()
            now = int(time.time() * 1000)
            if last_ts >= now:
                self._log_message("Data already up to date")
                logger.info("[Worker] Данные уже актуальны")
                return
            new_data = self._fetch_new_candles(last_ts, now)
            self._log_message(f"Fetched {len(new_data)} new candles" if new_data else "No new candles")
            logger.info(f"[Worker] Получено {len(new_data) if new_data else 0} новых свечей")
            if not new_data:
                return
            self._insert_to_clickhouse(new_data)
            self._log_message(f"Inserted {len(new_data)} candles to ClickHouse")
            self.update_signal.emit(new_data)
        except Exception as e:
            error_msg = f"Worker error: {str(e)}"
            self._log_message(error_msg)
            logger.error(f"[Worker] Ошибка: {error_msg}", exc_info=True)
            self.error_signal.emit(error_msg)

    def log_ssl_info(self):
        """Логирование всей SSL-информации"""
        print("\n" + "="*50)
        print("SSL DIAGNOSTICS")
        print("="*50)
        
        # Версии библиотек
        import requests, urllib3, OpenSSL
        print(f"\n=== Версии библиотек ===")
        print(f"OpenSSL: {ssl.OPENSSL_VERSION}")
        print(f"Requests: {requests.__version__}")
        print(f"urllib3: {urllib3.__version__}")
        
        
        # Дополнительная проверка
        print("\n=== Проверка подключения ===")
        try:
            import requests
            r = requests.get('https://api.hbdm.com', timeout=5)
            print(f"HTTPS Connection: OK (Status {r.status_code})")
        except Exception as e:
            print(f"HTTPS Connection Failed: {type(e).__name__} - {e}")           
    def _insert_to_clickhouse(self, candles):
        """Insert candles directly to ClickHouse with duplicate check"""
        if not candles:
            return
        try:
            # Проверяем, есть ли уже такие данные в базе
            existing_timestamps = set()
            result = self.ch_client.client.execute(
                "SELECT timestamp FROM crypto_data.btc_usdt_1m WHERE timestamp >= %(min_time)s AND timestamp <= %(max_time)s",
                {
                    'min_time': datetime.fromtimestamp(candles[0][0]/1000),
                    'max_time': datetime.fromtimestamp(candles[-1][0]/1000)
                }
            )
            existing_timestamps = {row[0] for row in result}

            data = []
            for c in candles:
                ts = datetime.fromtimestamp(c[0]/1000)
                if ts not in existing_timestamps:
                    data.append((
                        ts,
                        float(c[1]),
                        float(c[2]),
                        float(c[3]),
                        float(c[4]),
                        float(c[5])
                    ))

            if not data:
                print("No new data to insert")
                return

            batch_size = 1000
            for i in range(0, len(data), batch_size):
                batch = data[i:i+batch_size]
                self.ch_client.client.execute(
                    "INSERT INTO crypto_data.btc_usdt_1m (timestamp, open, high, low, close, volume) VALUES",
                    batch
                )
            print(f"           Вставлено минутных свечей:  {len(data)}")
        except Exception as e:
            print(f"Error inserting to ClickHouse: {str(e)}")
            raise
    def _get_last_clickhouse_timestamp(self):
        """Get last timestamp from ClickHouse"""
        try:
            result = self.ch_client.client.execute(
                "SELECT max(timestamp) FROM crypto_data.btc_usdt_1m"
            )
            return int(result[0][0].timestamp() * 1000) if result[0][0] else 0
        except Exception as e:
            self._log_message(f"Error getting last timestamp: {str(e)}")
            return 0   
    def _log_message(self, message):
        """Log a message with timestamp to the log file"""
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        log_entry = f"[{timestamp}] {message}\n"
        try:
            with open(self.log_file, 'a', encoding='utf-8') as f:
                f.write(log_entry)
        except Exception as e:
            print(f"Error writing to log file: {e}")
    def _load_file_data(self):
        """Load existing data handling both 6 and 7 column formats"""
        if not os.path.exists(self.file_path):
            return np.empty((0, 6))
        try:
            df = pd.read_csv(self.file_path)
            if len(df.columns) >= 7:
                self._log_message("Detected 7-column format, using first 6 columns")
                return df.iloc[:, :6].values
            elif len(df.columns) == 6:
                return df.values
            else:
                raise ValueError(f"Unexpected number of columns: {len(df.columns)}")
        except Exception as e:
            self._log_message(f"Error loading file: {str(e)}")
            raise
    def _fetch_new_candles(self, last_ts, now):
        logger.info(f"[Worker] _fetch_new_candles: last_ts={last_ts}, now={now}")
        try:
            if last_ts >= now:
                print("[DEBUG] Data already up to date")
                return []
            candles = []
            current_ts = last_ts
            max_retries = 3
            retry_delay = 2
            while current_ts < now and len(candles) < 1000:
                for attempt in range(max_retries):
                    try:
                        logger.debug(f"[Worker] Запрос свечей с {current_ts}, попытка {attempt+1}")
                        chunk = self.exchange.fetch_ohlcv(
                            'BTC/USDT',
                            '1m',
                            since=current_ts,
                            limit=min(200, 1000 - len(candles))
                        )
                        if not chunk:
                            break
                        for candle in chunk:
                            if candle[0] + 60000 <= now:  
                                candles.append([
                                    int(candle[0]),    
                                    float(candle[1]),  
                                    float(candle[2]),  
                                    float(candle[3]),  
                                    float(candle[4]),  
                                    float(candle[5])   
                                ])
                        if chunk:
                            current_ts = chunk[-1][0] + 60000
                        break  # успешно, выходим из retry
                    except Exception as e:
                        logger.error(f"[Worker] Error fetching chunk (attempt {attempt+1}): {str(e)}")
                        if attempt < max_retries - 1:
                            time.sleep(retry_delay * (attempt + 1))
                        else:
                            raise  # после всех попыток выбрасываем исключение
                time.sleep(0.1)  
            logger.info(f"[Worker] Всего загружено {len(candles)} свечей")
            return candles[:1000]  
        except Exception as e:
            logger.error(f"[Worker] Error in _fetch_new_candles: {str(e)}", exc_info=True)
            raise
    def _merge_data(self, file_data, new_data):
        """Merge existing and new data, ensuring no duplicates"""
        if not new_data:
            return file_data
        file_array = np.array(file_data)
        new_array = np.array(new_data)
        if len(file_array) == 0:
            return new_array
        last_file_ts = file_array[-1, 0]
        mask = new_array[:, 0] > last_file_ts
        new_to_add = new_array[mask]
        if len(new_to_add) == 0:
            return file_array
        return np.vstack([file_array, new_to_add])
    def _save_data(self, data):
        """Save data ensuring 6 columns"""
        try:
            temp_file = self.file_path + '.tmp'
            df = pd.DataFrame(data[:, :6], 
                            columns=['timestamp', 'open', 'high', 'low', 'close', 'volume'])
            df['timestamp'] = df['timestamp'].apply(self.validate_timestamp)
            df.to_csv(temp_file, index=False, float_format='%.8f')
            if os.path.exists(temp_file):
                if os.path.exists(self.file_path):
                    os.remove(self.file_path)
                os.rename(temp_file, self.file_path)
                print(f"💾 [DATA SAVE] Сохранение данных. Текущий TF: {self.timeframe_manager.current_timeframe}")
                if self.timeframe_manager.current_timeframe == '1m':
                     print("   🚨 Опасность: попытка сохранения с одновременным обновлением 1m!")                
                self.timeframe_manager.update_all_timeframes()
        except Exception as e:
            self._log_message(f"Save error: {str(e)}")
            raise 
    def fetch_chunked_data(self, start_ts, end_ts):
        """Загружает пропущенные свечи с биржи"""
        try:
            timeframe_ms = 60 * 1000
            missing_count = int((end_ts - start_ts) / timeframe_ms)
            if missing_count <= 0:
                return np.empty((0, 6))
            all_data = []
            remaining = missing_count
            chunk_size = 1000
            while remaining > 0:
                try:
                    current_limit = min(chunk_size, remaining)
                    chunk = self.exchange.fetch_ohlcv(
                        'BTC/USDT',
                        '1m',
                        since=start_ts,
                        limit=current_limit
                    )
                    if not chunk:
                        break
                    all_data.extend(chunk)
                    remaining -= len(chunk)
                    start_ts = chunk[-1][0] + timeframe_ms
                except Exception as e:
                    print(f"[ERROR] Ошибка загрузки: {str(e)}")
                    break
            return np.array(all_data) if all_data else np.empty((0, 6))
        except Exception as e:
            self.error_signal.emit(f"Ошибка загрузки пропущенных данных: {str(e)}")
            return np.empty((0, 6))
  
class MarkerManager:
    def __init__(self, plot_widget, timeframe_manager, dcm_manager, timestamps, opens, main_app=None):
        self.plot_widget = plot_widget
        self.timeframe_manager = timeframe_manager
        self.dcm_manager = dcm_manager  # Сохраняем ссылку
        self.timestamps = timestamps  # Добавляем параметр
        self.opens = opens            # Добавляем параметр
        self.main_app = main_app      # <-- НОВОЕ
        self.time_pairs = []
        self._load_time_pairs()
        self.average_file = "FINAL_RESULTS.csv"
        self.time_pairs_dialogs = []  # Добавьте эту строку

    def normalize_time_pairs_files(self):
        """
        Проходит по всем файлам time_pairs_{tf}.csv и обрезает секунды во всех датах до 00.
        Перезаписывает файлы с обновлёнными датами и индексами.
        """
        import logging
        logger = logging.getLogger(__name__)
        for tf in self.timeframe_manager.timeframes.keys():
            file_path = self.timeframe_manager.get_time_pairs_file(tf)
            if not os.path.exists(file_path):
                continue
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    lines = f.readlines()
                if len(lines) < 2:
                    continue
                header = lines[0].strip()
                new_lines = [header]
                modified = False
                for line in lines[1:]:
                    parts = line.strip().split(',')
                    if len(parts) < 6:
                        new_lines.append(line)
                        continue
                    start_time_str = parts[0].strip()
                    end_time_str = parts[2].strip()
                    try:
                        start_dt = datetime.strptime(start_time_str, '%Y-%m-%d %H:%M:%S')
                        end_dt = datetime.strptime(end_time_str, '%Y-%m-%d %H:%M:%S')
                    except:
                        new_lines.append(line)
                        continue
                    # Обрезаем секунды
                    if start_dt.second != 0 or end_dt.second != 0:
                        modified = True
                        start_dt = start_dt.replace(second=0)
                        end_dt = end_dt.replace(second=0)
                        # Пересчитываем индексы (части 4 и 5 - start_index, end_index)
                        try:
                            start_index = int(parts[4])
                            end_index = int(parts[5])
                            new_start_index = int(start_dt.timestamp())
                            new_end_index = int(end_dt.timestamp())
                            parts[0] = start_dt.strftime('%Y-%m-%d %H:%M:%S')
                            parts[2] = end_dt.strftime('%Y-%m-%d %H:%M:%S')
                            parts[4] = str(new_start_index)
                            parts[5] = str(new_end_index)
                            logger.warning(f"[НОРМАЛИЗАЦИЯ] Файл {file_path}: исправлены секунды: {start_time_str}->{parts[0]}, {end_time_str}->{parts[2]}")
                        except Exception as e:
                            logger.error(f"[НОРМАЛИЗАЦИЯ] Ошибка обновления индексов для строки: {line} - {e}")
                    new_lines.append(','.join(parts))
                if modified:
                    with open(file_path, 'w', encoding='utf-8') as f:
                        f.write('\n'.join(new_lines))
                    logger.info(f"[НОРМАЛИЗАЦИЯ] Файл {file_path} обновлён (секунды обрезаны).")
            except Exception as e:
                logger.error(f"[НОРМАЛИЗАЦИЯ] Ошибка обработки файла {file_path}: {e}")

    def _get_existing_pairs_from_db(self, timeframe):
        """Возвращает множество строк вида 'start->end' для пар, существующих в auto_ids."""
        try:
            query = f"""
                SELECT DISTINCT toStartOfMinute(start_time) as start, toStartOfMinute(end_time) as end
                FROM crypto_data.auto_ids
                WHERE timeframe = '{timeframe}'
            """
            rows = self.timeframe_manager.ch_client.execute(query)
            existing = set()
            for row in rows:
                start_dt = row[0]
                end_dt = row[1]
                key = f"{start_dt.strftime('%Y-%m-%d %H:%M:00')}->{end_dt.strftime('%Y-%m-%d %H:%M:00')}"
                existing.add(key)
            return existing
        except Exception as e:
            print(f"[PAIRS DB] Ошибка загрузки существующих пар: {e}")
            return set()

    def _check_pair_in_db(self, start_dt, end_dt, timeframe):
        """
        Проверяет, существует ли пара дат (start_time, end_time) в таблице auto_ids
        для указанного таймфрейма (с точностью до минуты).
        Возвращает True, если существует, иначе False.
        """
        try:
            start_str = start_dt.replace(second=0, microsecond=0).strftime('%Y-%m-%d %H:%M:00')
            end_str = end_dt.replace(second=0, microsecond=0).strftime('%Y-%m-%d %H:%M:00')
            query = f"""
                SELECT 1 FROM crypto_data.auto_ids
                WHERE timeframe = '{timeframe}'
                  AND toStartOfMinute(start_time) = toStartOfMinute(toDateTime('{start_str}'))
                  AND toStartOfMinute(end_time) = toStartOfMinute(toDateTime('{end_str}'))
                LIMIT 1
            """
            rows = self.timeframe_manager.ch_client.execute(query)
            return len(rows) > 0
        except Exception as e:
            print(f"[CHECK PAIR] Ошибка: {e}")
            return False                

    def get_price_for_timestamp(self, timestamp_ms):
        """Находит цену по временной метке из данных графика"""
        try:
            # Найти индекс ближайшего времени в массиве self.timestamps
            idx = np.abs(self.timestamps - timestamp_ms).argmin()
            return float(self.opens[idx])
        except Exception as e:
            print(f"[ERROR] Ошибка получения цены для временной метки: {str(e)}")
            return None
        
    def verify_time_pairs_integrity(self, timeframe):
        """Проверяет целостность пар дат для указанного таймфрейма"""
        time_pairs_file = self.timeframe_manager.get_time_pairs_file(timeframe)
        if not os.path.exists(time_pairs_file):
            print(f"[INTEGRITY CHECK] No time pairs file for {timeframe}")
            return False
        try:
            with open(time_pairs_file, 'r', encoding='utf-8') as f:
                reader = csv.reader(f)
                headers = next(reader, None)
                if headers != ['start_time', 'start_price', 'end_time', 'end_price', 'start_index', 'end_index']:
                    print(f"[INTEGRITY CHECK] Invalid headers in {timeframe} file")
                    return False
                pairs = list(reader)
                valid_pairs = 0
                for row in pairs:
                    if len(row) != 6:
                        print(f"[INTEGRITY CHECK] Invalid row length in {timeframe}: {row}")
                        continue
                    try:
                        datetime.strptime(row[0], '%Y-%m-%d %H:%M:%S')
                        float(row[1])
                        datetime.strptime(row[2], '%Y-%m-%d %H:%M:%S')
                        float(row[3])
                        int(row[4])
                        int(row[5])
                        valid_pairs += 1
                    except ValueError as e:
                        print(f"[INTEGRITY CHECK] Invalid data in {timeframe} row: {row} - {e}")
                        continue
                print(f"[INTEGRITY CHECK] {timeframe} has {valid_pairs}/{len(pairs)} valid pairs")
                return valid_pairs == len(pairs)
        except Exception as e:
            print(f"[INTEGRITY CHECK ERROR] Failed to check {timeframe}: {str(e)}")
            return False       
    def get_current_timeframe_file(self):
        """Возвращает путь к файлу пар дат для текущего таймфрейма"""
        current_tf = self.timeframe_manager.current_timeframe
        return self.timeframe_manager.get_time_pairs_file(current_tf)
    
    def manual_backup(self):
        """Создает резервную копию текущих данных вручную (включая все файлы корректировок и группы ветвей)"""
        try:
            backup_root = "time_pairs_full_backups"
            if not os.path.exists(backup_root):
                os.makedirs(backup_root)

            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            backup_dir = os.path.join(backup_root, f"manual_backup_{timestamp}")
            os.makedirs(backup_dir)

            # 1. Копируем файлы таймфреймов
            for timeframe in self.timeframe_manager.timeframes.keys():
                # Основные файлы пар дат и DCM
                time_pairs_file = self.timeframe_manager.get_time_pairs_file(timeframe)
                if os.path.exists(time_pairs_file):
                    shutil.copy2(time_pairs_file, os.path.join(backup_dir, f"time_pairs_{timeframe}.csv"))

                dcm_file = self.timeframe_manager.get_dcm_results_file(timeframe)
                if os.path.exists(dcm_file):
                    shutil.copy2(dcm_file, os.path.join(backup_dir, f"dcm_results_{timeframe}.csv"))

                # Файлы корректировок для таймфреймов
                correction_file = self.timeframe_manager.get_correction_file(timeframe)
                if os.path.exists(correction_file):
                    shutil.copy2(correction_file, os.path.join(backup_dir, f"corrections_{timeframe}.csv"))

            # 2. Копируем файлы корректировки ГОЛОВА (усы) и ХВОСТ
            correction_files = [
                "TAIL_CORRECTIONS.csv",
                "GROUP_TIMES_DATA.json",
                "FINAL_RESULTS.csv",
                "CHAINS_DATA.json",
                "EVENT_JOURNAL.json",
                "NEWS_HIGHLIGHT.json",
                "force_results.csv",
                "settings.json", 
                "MIRROR_GROUP_TIMES.json"      # добавлено
            ]

            for file_name in correction_files:
                if os.path.exists(file_name):
                    shutil.copy2(file_name, os.path.join(backup_dir, file_name))

            QtWidgets.QMessageBox.information(
                None,
                "Успех",
                f"Ручная резервная копия создана:\n{backup_dir}\n"
                f"Сохранено: пары дат, DCM-результаты, корректировки таймфреймов,\n"
                f"TAIL_CORRECTIONS, GROUP_TIMES_DATA, FINAL_RESULTS,\n"
                f"CHAINS_DATA, MIRROR_GROUP_TIMES, EVENT_JOURNAL"
            )
            return backup_dir
        except Exception as e:
            QtWidgets.QMessageBox.critical(
                None,
                "Ошибка",
                f"Не удалось создать резервную копию:\n{str(e)}"
            )
            return None
    def get_current_time_pairs_file(self):
        """Возвращает путь к файлу пар дат для текущего таймфрейма"""
        current_tf = self.timeframe_manager.current_timeframe
        return self.timeframe_manager.get_time_pairs_file(current_tf)        
    def get_price_from_chart(self, timestamp_ms):
        """Находит цену открытия по данным графика (без запроса к БД)"""
        try:
            # Найти индекс ближайшего времени в массиве self.timestamps
            idx = np.abs(self.timestamps - timestamp_ms).argmin()
            return float(self.opens[idx])
        except Exception as e:
            print(f"[ERROR] Ошибка получения цены из графика: {str(e)}")
            return None
    def delete_time_pair(self, dialog, table):
        """Удаляет выбранную пару дат"""
        selected = table.currentRow()
        if selected < 0:
            QtWidgets.QMessageBox.warning(dialog, "Ошибка", "Выберите пару для удаления")
            return
        try:
            # Удалить из списка
            del self.time_pairs[selected]
            # Обновить таблицу
            table.removeRow(selected)
            # Сохранить изменения
            self.save_time_pairs()
            # Обновить графики
            if hasattr(self, 'dcm_manager'):
                self.dcm_manager.calculate_dcm_results()
        except Exception as e:
            QtWidgets.QMessageBox.critical(dialog, "Ошибка", f"Не удалось удалить: {str(e)}")        
    def load_time_pairs_from_file(self, file_path):
        """Загружает пары дат из указанного файла, обрезая секунды."""
        time_pairs = []
        if not os.path.exists(file_path):
            print(f"[ЗАГРУЗКА ПАР] Файл {file_path} не найден")
            return time_pairs
            
        try:
            with open(file_path, 'r', encoding='utf-8') as file:
                reader = csv.reader(file)
                next(reader)  # пропускаем заголовок
                for row_num, row in enumerate(reader, 1):
                    if len(row) >= 6:
                        try:
                            dt1 = datetime.strptime(row[0], '%Y-%m-%d %H:%M:%S')
                            if dt1.second != 0:
                                print(f"[ПРЕДУПРЕЖДЕНИЕ] В файле {file_path} строка {row_num}: секунды в start_time ({row[0]}) будут обрезаны")
                                dt1 = dt1.replace(second=0)
                            price1 = float(row[1])
                            dt2 = datetime.strptime(row[2], '%Y-%m-%d %H:%M:%S')
                            if dt2.second != 0:
                                print(f"[ПРЕДУПРЕЖДЕНИЕ] В файле {file_path} строка {row_num}: секунды в end_time ({row[2]}) будут обрезаны")
                                dt2 = dt2.replace(second=0)
                            price2 = float(row[3])
                            index1 = int(row[4])
                            index2 = int(row[5])
                            time_pairs.append((dt1, price1, dt2, price2, index1, index2))
                        except (ValueError, IndexError) as e:
                            print(f"Ошибка обработки строки {row_num} в {file_path}: {e}")
                            continue
            print(f"[ЗАГРУЗКА ПАР] Загружено {len(time_pairs)} пар из {file_path}")
            return time_pairs
        except Exception as e:
            print(f"Ошибка загрузки файла {file_path}: {e}")
            return []
        
    def add_time_pair(self, dialog, table):
        """Добавляет пару, используя данные из графика (немодальный режим)"""
        # Создаем диалог
        pair_dialog = QtWidgets.QDialog(dialog)
        pair_dialog.setWindowTitle("Добавить пару дат")
        pair_dialog.setMinimumSize(400, 200)

        # Делаем его немодальным
        pair_dialog.setWindowFlags(
            QtCore.Qt.WindowType.Window |
            QtCore.Qt.WindowType.WindowCloseButtonHint
        )
        pair_dialog.setModal(False)
        pair_dialog.setWindowModality(QtCore.Qt.WindowModality.NonModal)

        layout = QtWidgets.QVBoxLayout(pair_dialog)

        form_layout = QtWidgets.QFormLayout()

        start_edit = QtWidgets.QDateTimeEdit()
        start_edit.setCalendarPopup(True)
        start_edit.setDateTime(QtCore.QDateTime.currentDateTime())
        form_layout.addRow("Начальная дата:", start_edit)

        end_edit = QtWidgets.QDateTimeEdit()
        end_edit.setCalendarPopup(True)
        end_edit.setDateTime(QtCore.QDateTime.currentDateTime().addDays(1))
        form_layout.addRow("Конечная дата:", end_edit)

        layout.addLayout(form_layout)

        buttons = QtWidgets.QHBoxLayout()
        ok_btn = QtWidgets.QPushButton("OK")
        cancel_btn = QtWidgets.QPushButton("Отмена")
        buttons.addWidget(ok_btn)
        buttons.addWidget(cancel_btn)
        layout.addLayout(buttons)

        # Результат
        result = {"start": None, "end": None, "ok": False}

        def on_ok():
            result["start"] = start_edit.dateTime().toPyDateTime()
            result["end"] = end_edit.dateTime().toPyDateTime()
            result["ok"] = True
            pair_dialog.accept()

        ok_btn.clicked.connect(on_ok)
        cancel_btn.clicked.connect(pair_dialog.reject)

        # Показываем немодально и ждем в цикле событий
        pair_dialog.show()

        # Ждем закрытия без блокировки графика
        while pair_dialog.isVisible():
            QtWidgets.QApplication.processEvents()
            QtCore.QThread.msleep(10)

        if not result["ok"]:
            return

        try:
            start = result["start"]
            end = result["end"]
            start_ts = int(start.timestamp() * 1000)
            end_ts = int(end.timestamp() * 1000)

            price1 = self.get_price_for_timestamp(start_ts)
            price2 = self.get_price_for_timestamp(end_ts)

            if price1 is None or price2 is None:
                QtWidgets.QMessageBox.warning(dialog, "Ошибка данных", "Цены не найдены для выбранных дат")
                return

            # Добавляем новую пару
            new_pair = (
                start,
                price1,
                end,
                price2,
                int(start.timestamp()),
                int(end.timestamp())
            )
            self.time_pairs.append(new_pair)

            # Сохраняем и обновляем
            self.save_time_pairs()
            self.update_table(table)

            # Пересчитываем DCM
            if hasattr(self, 'dcm_manager'):
                self.dcm_manager.calculate_dcm_results()

        except Exception as e:
            QtWidgets.QMessageBox.critical(dialog, "Ошибка", f"Ошибка добавления: {str(e)}")
            
    def restore_from_backup(self, backup_file):
        """Восстанавливает пары дат из резервной копии"""
        try:
            if not os.path.exists(backup_file):
                QtWidgets.QMessageBox.warning(
                    None,
                    "Ошибка",
                    f"Резервный файл не найден:\n{backup_file}"
                )
                return False
            filename = os.path.basename(backup_file)
            parts = filename.split('_')
            if len(parts) < 4:
                QtWidgets.QMessageBox.warning(
                    None,
                    "Ошибка",
                    "Неверный формат имени файла резервной копии"
                )
                return False
            timeframe = parts[2]  
            if timeframe not in self.timeframe_manager.timeframes:
                QtWidgets.QMessageBox.warning(
                    None,
                    "Ошибка",
                    f"Неизвестный таймфрейм в резервной копии: {timeframe}"
                )
                return False
            target_file = self.timeframe_manager.get_time_pairs_file(timeframe)
            shutil.copy2(backup_file, target_file)
            if timeframe == self.timeframe_manager.current_timeframe:
                self.load_time_pairs_from_csv()
                if hasattr(self, 'dcm_manager'):
                    self.dcm_manager.calculate_dcm_results()
            QtWidgets.QMessageBox.information(
                None,
                "Успех",
                f"Резервная копия успешно восстановлена для таймфрейма {timeframe}"
            )
            return True
        except Exception as e:
            QtWidgets.QMessageBox.critical(
                None,
                "Ошибка",
                f"Ошибка восстановления из резервной копии:\n{str(e)}"
            )
            return False
        
    def restore_from_folder(self, backup_folder):
        """Восстанавливает все файлы из резервной копии (включая корректировки, цепочки и группы ветвей)"""
        try:
            if not os.path.exists(backup_folder):
                QtWidgets.QMessageBox.warning(
                    None,
                    "Ошибка",
                    f"Папка с резервной копией не найдена:\n{backup_folder}"
                )
                return False

            restored_files = []

            # 1. Восстанавливаем файлы для каждого таймфрейма
            for timeframe in self.timeframe_manager.timeframes.keys():
                # time_pairs_*.csv
                src_time_pairs = os.path.join(backup_folder, f"time_pairs_{timeframe}.csv")
                if os.path.exists(src_time_pairs):
                    dest_time_pairs = self.timeframe_manager.get_time_pairs_file(timeframe)
                    shutil.copy2(src_time_pairs, dest_time_pairs)
                    restored_files.append(f"time_pairs_{timeframe}.csv")

                # dcm_results_*.csv
                src_dcm = os.path.join(backup_folder, f"dcm_results_{timeframe}.csv")
                if os.path.exists(src_dcm):
                    dest_dcm = self.timeframe_manager.get_dcm_results_file(timeframe)
                    shutil.copy2(src_dcm, dest_dcm)
                    restored_files.append(f"dcm_results_{timeframe}.csv")

                # corrections_*.csv
                src_corrections = os.path.join(backup_folder, f"corrections_{timeframe}.csv")
                if os.path.exists(src_corrections):
                    dest_corrections = self.timeframe_manager.get_correction_file(timeframe)
                    shutil.copy2(src_corrections, dest_corrections)
                    restored_files.append(f"corrections_{timeframe}.csv")

            # 2. Восстанавливаем основные файлы системы
            main_files = [
                "TAIL_CORRECTIONS.csv",
                "GROUP_TIMES_DATA.json",
                "FINAL_RESULTS.csv",
                "CHAINS_DATA.json",
                "selected_timeframes.txt",
                "EVENT_JOURNAL.json",
                "force_results.csv",
                "settings.json",
                "NEWS_HIGHLIGHT.json",
                "MIRROR_GROUP_TIMES.json"      # добавлено
            ]

            for file_name in main_files:
                src_file = os.path.join(backup_folder, file_name)
                if os.path.exists(src_file):
                    shutil.copy2(src_file, file_name)
                    restored_files.append(file_name)
                    print(f"[ВОССТАНОВЛЕНИЕ] Файл {file_name} восстановлен")

            # 3. Обновляем текущие данные
            current_tf = self.timeframe_manager.current_timeframe
            self.load_time_pairs_from_csv()

            if hasattr(self, 'dcm_manager'):
                self.dcm_manager.calculate_dcm_results()

            # 4. Если есть открытые диалоги корректировки, перезагружаем их данные
            if hasattr(self, 'correction_dialogs'):
                for dialog in self.correction_dialogs:
                    if hasattr(dialog, 'load_results_table'):
                        print(f"[ВОССТАНОВЛЕНИЕ] Перезагружаем таблицу результатов в диалоге")
                        dialog.load_results_table()
                    if hasattr(dialog, 'load_group_times'):
                        print(f"[ВОССТАНОВЛЕНИЕ] Перезагружаем времена групп в диалоге")
                        dialog.load_group_times()
                    if hasattr(dialog, 'load_mirror_group_times'):   # добавлено
                        print(f"[ВОССТАНОВЛЕНИЕ] Перезагружаем зеркальные группы в диалоге")
                        dialog.load_mirror_group_times()
                    if hasattr(dialog, 'load_auto_group_times'):
                        print(f"[ВОССТАНОВЛЕНИЕ] Перезагружаем авто-группы в диалоге")
                        dialog.load_auto_group_times()
                    if hasattr(dialog, 'reload_branch_groups'):
                        print(f"[ВОССТАНОВЛЕНИЕ] Перезагружаем группы ветвей в диалоге")
                        dialog.reload_branch_groups()
                    if hasattr(dialog, 'refresh_groups_table'):
                        print(f"[ВОССТАНОВЛЕНИЕ] Обновляем таблицу групп в диалоге")
                        dialog.refresh_groups_table()

            # 5. Обновляем вертикальные линии на графике
            if hasattr(self, 'average_manager') and self.average_manager:
                self.average_manager.draw_vertical_lines()

            QtWidgets.QMessageBox.information(
                None,
                "Успех",
                f"✅ Резервная копия успешно восстановлена!\n\n"
                f"📁 Папка: {os.path.basename(backup_folder)}\n"
                f"📊 Восстановлено файлов: {len(restored_files)}\n\n"
                f"Файлы:\n" + "\n".join(restored_files[:10])
            )
            return True

        except Exception as e:
            QtWidgets.QMessageBox.critical(
                None,
                "Ошибка",
                f"❌ Ошибка восстановления из резервной копии:\n{str(e)}"
            )
            import traceback
            traceback.print_exc()
            return False
        
    def show_restore_dialog(self):
        """Показывает диалог с возможностью восстановления и ручного сохранения"""
        try:
            backup_root = "time_pairs_full_backups"
            if not os.path.exists(backup_root):
                os.makedirs(backup_root)  # Создаем папку, если её нет
            dialog = QtWidgets.QDialog()
            dialog.setWindowTitle("Управление резервными копиями")
            dialog.setMinimumSize(800, 600)
            layout = QtWidgets.QVBoxLayout(dialog)
            # Кнопка "Сохранить текущие данные в бэкап"
            btn_save_backup = QtWidgets.QPushButton("Сохранить в бэкап (ручное)")
            btn_save_backup.clicked.connect(lambda: (
                self.manual_backup(),
                dialog.accept()  # Закрываем диалог после сохранения
            ))
            layout.addWidget(btn_save_backup)
            # Разделитель
            layout.addWidget(QtWidgets.QLabel("Доступные резервные копии:"))
            # Список существующих бэкапов
            backup_folders = []
            for folder in os.listdir(backup_root):
                folder_path = os.path.join(backup_root, folder)
                if os.path.isdir(folder_path) and (folder.startswith("backup_") or folder.startswith("manual_backup_")):
                    mtime = os.path.getmtime(folder_path)
                    dt = datetime.fromtimestamp(mtime).strftime('%Y-%m-%d %H:%M:%S')
                    backup_folders.append((dt, folder_path))
            if not backup_folders:
                layout.addWidget(QtWidgets.QLabel("Нет доступных резервных копий."))
            else:
                backup_folders.sort(reverse=True, key=lambda x: x[0])  # Сортируем по дате (новые сверху)
                table = QtWidgets.QTableWidget()
                table.setColumnCount(3)
                table.setHorizontalHeaderLabels(["Дата создания", "Имя папки", "Файлов"])
                table.setRowCount(len(backup_folders))
                for i, (dt, folder_path) in enumerate(backup_folders):
                    table.setItem(i, 0, QtWidgets.QTableWidgetItem(dt))
                    table.setItem(i, 1, QtWidgets.QTableWidgetItem(os.path.basename(folder_path)))
                    file_count = len([f for f in os.listdir(folder_path) if os.path.isfile(os.path.join(folder_path, f))])
                    table.setItem(i, 2, QtWidgets.QTableWidgetItem(str(file_count)))
                table.resizeColumnsToContents()
                layout.addWidget(table)
                # Кнопка восстановления выбранного
                btn_restore = QtWidgets.QPushButton("Восстановить выбранное")
                btn_restore.clicked.connect(lambda: (
                    self.restore_selected_backup(dialog, table),
                    dialog.accept()  # Закрываем диалог после восстановления
                ))
                layout.addWidget(btn_restore)
            # Кнопка закрытия
            btn_close = QtWidgets.QPushButton("Закрыть")
            btn_close.clicked.connect(dialog.reject)
            layout.addWidget(btn_close)
            dialog.exec()
        except Exception as e:
            QtWidgets.QMessageBox.critical(
                None,
                "Ошибка",
                f"Ошибка при открытии диалога:\n{str(e)}"
            )
    def restore_selected_backup(self, dialog, table):
        """Восстанавливает все файлы из выбранной папки с резервной копией"""
        selected = table.currentRow()
        if selected < 0:
            QtWidgets.QMessageBox.warning(
                dialog,
                "Ошибка",
                "Выберите резервную копию для восстановления"
            )
            return
        folder_name = table.item(selected, 1).text()
        backup_root = "time_pairs_full_backups"
        backup_folder = os.path.join(backup_root, folder_name)
        if not os.path.exists(backup_folder):
            QtWidgets.QMessageBox.warning(
                dialog,
                "Ошибка",
                f"Папка с резервной копией не найдена:\n{backup_folder}"
            )
            return
        try:
            for filename in os.listdir(backup_folder):
                if filename.startswith("time_pairs_") or filename.startswith("dcm_results_"):
                    parts = filename.split('_')
                    if len(parts) >= 3:
                        file_type = parts[0]  
                        timeframe = parts[2].split('.')[0]  
                        if file_type == "time":
                            dest_file = self.timeframe_manager.get_time_pairs_file(timeframe)
                        else:
                            dest_file = self.timeframe_manager.get_dcm_results_file(timeframe)
                        shutil.copy2(os.path.join(backup_folder, filename), dest_file)
            current_tf = self.timeframe_manager.current_timeframe
            self.load_time_pairs_from_csv()
            if hasattr(self, 'dcm_manager'):
                self.dcm_manager.calculate_dcm_results()
            QtWidgets.QMessageBox.information(
                dialog,
                "Успех",
                "Резервная копия успешно восстановлена"
            )
            dialog.accept()
        except Exception as e:
            QtWidgets.QMessageBox.critical(
                dialog,
                "Ошибка",
                f"Ошибка восстановления из резервной копии:\n{str(e)}"
            )     
    def backup_time_pairs(self):
        """Создает полную резервную копию всех файлов в отдельной папке"""
        try:
            backup_root = "time_pairs_full_backups"
            if not os.path.exists(backup_root):
                os.makedirs(backup_root)
            
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            backup_dir = os.path.join(backup_root, f"backup_{timestamp}")
            os.makedirs(backup_dir)
            
            # 1. Файлы таймфреймов
            for timeframe in self.timeframe_manager.timeframes.keys():
                time_pairs_file = self.timeframe_manager.get_time_pairs_file(timeframe)
                if os.path.exists(time_pairs_file):
                    shutil.copy2(time_pairs_file, os.path.join(backup_dir, f"time_pairs_{timeframe}.csv"))
                
                dcm_file = self.timeframe_manager.get_dcm_results_file(timeframe)
                if os.path.exists(dcm_file):
                    shutil.copy2(dcm_file, os.path.join(backup_dir, f"dcm_results_{timeframe}.csv"))
                
                correction_file = self.timeframe_manager.get_correction_file(timeframe)
                if os.path.exists(correction_file):
                    shutil.copy2(correction_file, os.path.join(backup_dir, f"corrections_{timeframe}.csv"))
            
            # 2. Основные файлы системы
            system_files = [
                "TAIL_CORRECTIONS.csv",
                "GROUP_TIMES_DATA.json",
                "FINAL_RESULTS.csv",
                "CHAINS_DATA.json",
                "selected_timeframes.txt",
                "EVENT_JOURNAL.json"  
            ]
            
            for file_name in system_files:
                if os.path.exists(file_name):
                    shutil.copy2(file_name, os.path.join(backup_dir, file_name))
            
            print(f"✅ Создана полная резервная копия в {backup_dir}")
            print(f"   Файлов скопировано: {len(os.listdir(backup_dir))}")
            return backup_dir
            
        except Exception as e:
            print(f"❌ Ошибка создания полной резервной копии: {e}")
            import traceback
            traceback.print_exc()
            return None
    def _load_time_pairs(self):
        """Загружает пары дат для текущего таймфрейма"""
        current_tf = self.timeframe_manager.current_timeframe
        file_path = self.timeframe_manager.time_pairs_files[current_tf]
        self.time_pairs = []
        if not os.path.exists(file_path):
            return
        with open(file_path, 'r', encoding='utf-8') as file:
            reader = csv.reader(file)
            next(reader)  
            for row in reader:
                if len(row) >= 6:
                    try:
                        dt1 = datetime.strptime(row[0], '%Y-%m-%d %H:%M:%S')
                        price1 = float(row[1])
                        dt2 = datetime.strptime(row[2], '%Y-%m-%d %H:%M:%S')
                        price2 = float(row[3])
                        index1 = int(row[4])
                        index2 = int(row[5])
                        self.time_pairs.append((dt1, price1, dt2, price2, index1, index2))
                    except ValueError as e:
                        print(f"Ошибка обработки строки: {row} - {e}")
                        continue        
    def update_table(self, table):
        """Полностью обновляет таблицу"""
        table.setRowCount(len(self.time_pairs))
        for i, (start, price1, end, price2, index1, index2) in enumerate(self.time_pairs):
            table.setItem(i, 0, QtWidgets.QTableWidgetItem(start.strftime('%Y-%m-%d %H:%M:%S')))
            table.setItem(i, 1, QtWidgets.QTableWidgetItem(f"{price1:.2f}"))
            table.setItem(i, 2, QtWidgets.QTableWidgetItem(end.strftime('%Y-%m-%d %H:%M:%S')))
            table.setItem(i, 3, QtWidgets.QTableWidgetItem(f"{price2:.2f}"))
            time_diff = (end - start).total_seconds() / 60
            table.setItem(i, 4, QtWidgets.QTableWidgetItem(f"{time_diff:.1f}"))
            table.setItem(i, 5, QtWidgets.QTableWidgetItem(str(index1)))
            table.setItem(i, 6, QtWidgets.QTableWidgetItem(str(index2)))
        table.resizeColumnsToContents()      
    def load_time_pairs_from_csv(self):
        """Загружает пары дат из файла текущего таймфрейма"""
        file_path = self.get_current_time_pairs_file()
        self.time_pairs = []
        if not os.path.exists(file_path):
            return self.time_pairs
        with open(file_path, 'r', encoding='utf-8') as file:
            reader = csv.reader(file)
            next(reader)  # Пропускаем заголовок
            for row in reader:
                if len(row) >= 6:
                    try:
                        dt1 = datetime.strptime(row[0], '%Y-%m-%d %H:%M:%S')
                        price1 = float(row[1])
                        dt2 = datetime.strptime(row[2], '%Y-%m-%d %H:%M:%S')
                        price2 = float(row[3])
                        index1 = int(row[4])
                        index2 = int(row[5])
                        self.time_pairs.append((dt1, price1, dt2, price2, index1, index2))
                    except (ValueError, IndexError) as e:
                        print(f"Ошибка обработки строки {row}: {e}")
                        continue
        return self.time_pairs
    def save_time_pairs(self):
        """Сохраняет пары дат в файл текущего таймфрейма с расширенным логированием"""
        file_path = self.get_current_time_pairs_file()
        current_tf = self.timeframe_manager.current_timeframe
        print(f"📝 [PAIRS SAVE] Сохранение пар для {current_tf}. Вызов из:")
        import traceback
        print(''.join(traceback.format_stack(limit=3)[:-1]))  # Логируем 3 последних вызова
        if current_tf == '1m':
            print("   🚨 Критично: сохранение пар для 1m!")    
        print(f"[CURRENT_PAIRS] Count: {len(self.time_pairs)}")
        try:
            with open(file_path, 'w', newline='', encoding='utf-8') as file:
                writer = csv.writer(file)
                writer.writerow(['start_time', 'start_price', 'end_time', 'end_price', 'start_index', 'end_index'])
                saved_count = 0
                for i, (dt1, price1, dt2, price2, index1, index2) in enumerate(self.time_pairs):
                    # Проверка данных перед записью
                    if None in (dt1, price1, dt2, price2, index1, index2):
                        print(f"[INVALID_PAIR_SKIPPED] Index {i}: Contains None values")
                        continue
                    writer.writerow([
                        dt1.strftime('%Y-%m-%d %H:%M:%S'),
                        price1,
                        dt2.strftime('%Y-%m-%d %H:%M:%S'),
                        price2,
                        index1,
                        index2
                    ])
                    saved_count += 1
                print(f"[SAVE_COMPLETE] Successfully saved {saved_count}/{len(self.time_pairs)} pairs")
            
            # === СБРОС КЭША ТРЕНДА ===
            if self.main_app is not None:
                if hasattr(self.main_app, 'correction_dialog') and self.main_app.correction_dialog is not None:
                    self.main_app.correction_dialog.invalidate_trend_cache()
                    logger.info("[TREND] Кэш тренда сброшен после сохранения пар дат")
        except Exception as e:
            print(f"[SAVE_ERROR] Failed to save pairs: {str(e)}")
            raise
    def manage_time_pairs_dialog(self):
        """Диалог управления парами дат (немодальный, с пересчетом DCM при закрытии) с подсветкой отсутствующих в БД."""
        try:
            current_tf = self.timeframe_manager.current_timeframe
            dialog = QtWidgets.QDialog()
            dialog.setWindowTitle(f"Управление парами дат ({self.timeframe_manager.current_timeframe})")
            dialog.setMinimumSize(800, 600)
            
            # Настраиваем как независимое окно (немодальное)
            dialog.setWindowFlags(
                QtCore.Qt.WindowType.Window |
                QtCore.Qt.WindowType.WindowCloseButtonHint |
                QtCore.Qt.WindowType.WindowMinimizeButtonHint |
                QtCore.Qt.WindowType.WindowMaximizeButtonHint
            )
            
            # Убираем модальность
            dialog.setModal(False)
            dialog.setWindowModality(QtCore.Qt.WindowModality.NonModal)
            
            layout = QtWidgets.QVBoxLayout(dialog)
            
            self.load_time_pairs_from_csv()
            
            table = QtWidgets.QTableWidget()
            table.setColumnCount(8)
            table.setHorizontalHeaderLabels([
                "Начало", "Цена начала", "Конец", 
                "Цена конца", "Минуты", "Бары", "Нач. индекс", "Кон. индекс"
            ])
            table.setRowCount(len(self.time_pairs))
            
            current_tf = self.timeframe_manager.current_timeframe
            tf_minutes = self.timeframe_manager.timeframes[current_tf]
            
            # Загружаем существующие пары из БД для этого ТФ (в виде строк)
            existing_pairs = self._get_existing_pairs_from_db(current_tf)
            
            for i, (start, price1, end, price2, index1, index2) in enumerate(self.time_pairs):
                # Создаём ячейки
                start_item = QtWidgets.QTableWidgetItem(start.strftime('%Y-%m-%d %H:%M:%S'))
                end_item = QtWidgets.QTableWidgetItem(end.strftime('%Y-%m-%d %H:%M:%S'))
                table.setItem(i, 0, start_item)
                table.setItem(i, 1, QtWidgets.QTableWidgetItem(f"{price1:.2f}"))
                table.setItem(i, 2, end_item)
                table.setItem(i, 3, QtWidgets.QTableWidgetItem(f"{price2:.2f}"))
                time_diff = (end - start).total_seconds() / 60
                table.setItem(i, 4, QtWidgets.QTableWidgetItem(f"{time_diff:.1f}"))
                bars = time_diff / tf_minutes
                table.setItem(i, 5, QtWidgets.QTableWidgetItem(f"{bars:.0f}"))
                table.setItem(i, 6, QtWidgets.QTableWidgetItem(str(index1)))
                table.setItem(i, 7, QtWidgets.QTableWidgetItem(str(index2)))
                
                # Проверяем наличие пары в БД (сравниваем строки)
                start_key = start.replace(second=0, microsecond=0)
                end_key = end.replace(second=0, microsecond=0)
                key = f"{start_key.strftime('%Y-%m-%d %H:%M:00')}->{end_key.strftime('%Y-%m-%d %H:%M:00')}"
                if key not in existing_pairs:
                    # Подсвечиваем ячейки с датами красным (30% прозрачности)
                    start_item.setBackground(QtGui.QColor(255, 0, 0, 77))
                    end_item.setBackground(QtGui.QColor(255, 0, 0, 77))
                    # Добавляем подсказку
                    start_item.setToolTip("Эта пара отсутствует в БД auto_ids")
                    end_item.setToolTip("Эта пара отсутствует в БД auto_ids")
            
            table.resizeColumnsToContents()
            layout.addWidget(table)
            
            buttons = QtWidgets.QHBoxLayout()
            btn_add = QtWidgets.QPushButton("Добавить")
            btn_add.clicked.connect(lambda: self.add_time_pair(dialog, table))
            buttons.addWidget(btn_add)
            
            btn_edit = QtWidgets.QPushButton("Редактировать")
            btn_edit.clicked.connect(lambda: self.edit_time_pair(dialog, table))
            buttons.addWidget(btn_edit)
            
            btn_delete = QtWidgets.QPushButton("Удалить")
            btn_delete.clicked.connect(lambda: self.delete_time_pair(dialog, table))
            buttons.addWidget(btn_delete)
            
            btn_close = QtWidgets.QPushButton("Закрыть")
            btn_close.clicked.connect(dialog.accept)
            buttons.addWidget(btn_close)
            
            layout.addLayout(buttons)
            
            # При закрытии диалога — пересчитываем DCM
            def on_dialog_close():
                print(f"[ПАРЫ] Диалог закрыт, пересчитываем DCM для таймфрейма {current_tf}")
                if hasattr(self, 'dcm_manager') and self.dcm_manager:
                    try:
                        self.dcm_manager.calculate_dcm_results()
                        print(f"[ПАРЫ] DCM пересчитан успешно")
                    except Exception as e:
                        print(f"[ПАРЫ] Ошибка пересчета DCM: {str(e)}")
            
            dialog.finished.connect(on_dialog_close)
            
            # Показываем окно без блокировки
            dialog.show()
            
            # Сохраняем ссылку для предотвращения сборки мусора
            if not hasattr(self, 'time_pairs_dialogs'):
                self.time_pairs_dialogs = []
            self.time_pairs_dialogs.append(dialog)
            
            # Удаляем из списка при закрытии
            dialog.destroyed.connect(lambda: self.time_pairs_dialogs.remove(dialog))
            
        except Exception as e:
            print(f"Ошибка открытия диалога пар дат: {e}")
            QtWidgets.QMessageBox.critical(None, "Ошибка", f"Не удалось открыть диалог: {str(e)}")
            
    def edit_time_pair(self, dialog, table):
        """Редактирует пару и сохраняет файл напрямую (немодальный режим)"""
        current_tf = self.timeframe_manager.current_timeframe
        print(f"Редактирование пары для таймфрейма {current_tf}")

        selected = table.currentRow()
        if selected < 0:
            QtWidgets.QMessageBox.warning(dialog, "Ошибка", "Выберите пару для редактирования")
            return

        try:
            old_pair = self.time_pairs[selected]

            # Создаем немодальный диалог
            pair_dialog = QtWidgets.QDialog(dialog)
            pair_dialog.setWindowTitle("Редактировать пару дат")
            pair_dialog.setMinimumSize(400, 200)

            pair_dialog.setWindowFlags(
                QtCore.Qt.WindowType.Window |
                QtCore.Qt.WindowType.WindowCloseButtonHint
            )
            pair_dialog.setModal(False)
            pair_dialog.setWindowModality(QtCore.Qt.WindowModality.NonModal)

            layout = QtWidgets.QVBoxLayout(pair_dialog)

            form_layout = QtWidgets.QFormLayout()

            start_edit = QtWidgets.QDateTimeEdit()
            start_edit.setCalendarPopup(True)
            start_dt = QtCore.QDateTime.fromString(
                old_pair[0].strftime('%Y-%m-%d %H:%M:%S'),
                'yyyy-MM-dd HH:mm:ss'
            )
            start_edit.setDateTime(start_dt)
            form_layout.addRow("Начальная дата:", start_edit)

            end_edit = QtWidgets.QDateTimeEdit()
            end_edit.setCalendarPopup(True)
            end_dt = QtCore.QDateTime.fromString(
                old_pair[2].strftime('%Y-%m-%d %H:%M:%S'),
                'yyyy-MM-dd HH:mm:ss'
            )
            end_edit.setDateTime(end_dt)
            form_layout.addRow("Конечная дата:", end_edit)

            layout.addLayout(form_layout)

            buttons = QtWidgets.QHBoxLayout()
            ok_btn = QtWidgets.QPushButton("OK")
            cancel_btn = QtWidgets.QPushButton("Отмена")
            buttons.addWidget(ok_btn)
            buttons.addWidget(cancel_btn)
            layout.addLayout(buttons)

            result = {"start": None, "end": None, "ok": False}

            def on_ok():
                result["start"] = start_edit.dateTime().toPyDateTime()
                result["end"] = end_edit.dateTime().toPyDateTime()
                result["ok"] = True
                pair_dialog.accept()

            ok_btn.clicked.connect(on_ok)
            cancel_btn.clicked.connect(pair_dialog.reject)

            pair_dialog.show()

            # Ждем закрытия
            while pair_dialog.isVisible():
                QtWidgets.QApplication.processEvents()
                QtCore.QThread.msleep(10)

            if not result["ok"]:
                return

            new_start = result["start"]
            new_end = result["end"]

            new_price1 = self.get_price_for_timestamp(new_start.timestamp() * 1000)
            new_price2 = self.get_price_for_timestamp(new_end.timestamp() * 1000)

            # Обновить в памяти
            self.time_pairs[selected] = (
                new_start,
                new_price1 or old_pair[1],
                new_end,
                new_price2 or old_pair[3],
                int(new_start.timestamp()),
                int(new_end.timestamp())
            )

            # Сохранить и обновить
            self.save_time_pairs()
            self.update_table(table)

            # Пересчитать DCM
            if hasattr(self, 'dcm_manager'):
                self.dcm_manager.calculate_dcm_results()

            print(f"[EDIT] Пара {selected+1} отредактирована")

        except Exception as e:
            QtWidgets.QMessageBox.critical(dialog, "Ошибка", f"Ошибка редактирования: {str(e)}")
            import traceback
            traceback.print_exc()
            
class TimePairDialog(QtWidgets.QDialog):
    def __init__(self, pair=None, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Редактировать пару дат" if pair else "Добавить пару дат")
        layout = QtWidgets.QVBoxLayout(self)
        form_layout = QtWidgets.QFormLayout()
        self.start_edit = QtWidgets.QDateTimeEdit()
        self.start_edit.setCalendarPopup(True)
        self.start_edit.setDateTime(QtCore.QDateTime.currentDateTime())
        self.end_edit = QtWidgets.QDateTimeEdit()
        self.end_edit.setCalendarPopup(True)
        self.end_edit.setDateTime(QtCore.QDateTime.currentDateTime().addDays(1))
        if pair:
            start_dt = QtCore.QDateTime.fromString(pair[0].strftime('%Y-%m-%d %H:%M:%S'), 'yyyy-MM-dd HH:mm:ss')
            end_dt = QtCore.QDateTime.fromString(pair[1].strftime('%Y-%m-%d %H:%M:%S'), 'yyyy-MM-dd HH:mm:ss')
            self.start_edit.setDateTime(start_dt)
            self.end_edit.setDateTime(end_dt)
        form_layout.addRow("Начальная дата:", self.start_edit)
        form_layout.addRow("Конечная дата:", self.end_edit)
        layout.addLayout(form_layout)
        buttons = QtWidgets.QHBoxLayout()
        ok_btn = QtWidgets.QPushButton("OK")
        ok_btn.clicked.connect(self.accept)  
        cancel_btn = QtWidgets.QPushButton("Отмена")
        cancel_btn.clicked.connect(self.reject)  
        buttons.addWidget(ok_btn)
        buttons.addWidget(cancel_btn)
        layout.addLayout(buttons)
    def get_pair(self):
        """Возвращает пару дат в виде кортежа datetime"""
        start_dt = self.start_edit.dateTime().toPyDateTime()
        end_dt = self.end_edit.dateTime().toPyDateTime()
        return (start_dt, end_dt)

class AutoLinesManager:
    """Менеджер для отрисовки автоматических линий на графике"""
    def __init__(self, plot_widget, timeframe_manager):
        """Инициализация менеджера авто-линий"""
        self.plot_widget = plot_widget
        self.timeframe_manager = timeframe_manager
        self.line_items = []
        self.slope_line_items = []
        self.current_position_id = None
        self._last_slope_position_id = None
        self._group_label_data = []          # для хранения вертикальных меток автогрупп

        # Цвета для разных типов групп
        self.group_colors = {
            1: (255, 255, 255, 200),
            2: (255, 255, 255, 200),
            3: (0, 0, 255, 200),
            4: (0, 0, 255, 200),
            5: (255, 105, 180, 200),
            6: (255, 105, 180, 200),
            7: (255, 255, 0, 200),
            8: (255, 255, 0, 200)
        }

        # Стили линий для разных групп
        self.group_styles = {
            1: QtCore.Qt.PenStyle.DashLine,
            2: QtCore.Qt.PenStyle.DashLine,
            3: QtCore.Qt.PenStyle.DashLine,
            4: QtCore.Qt.PenStyle.DashLine,
            5: QtCore.Qt.PenStyle.DashLine,
            6: QtCore.Qt.PenStyle.DashLine,
            7: QtCore.Qt.PenStyle.DashLine,
            8: QtCore.Qt.PenStyle.DashLine
        }

    def _get_direction_by_dates(self, ch_client, timeframe, start_dt, end_dt, tolerance_minutes=2):
        """
        Находит направление (long/short) по паре дат из auto_ids.
        Использует приблизительный поиск с допуском tolerance_minutes (без секунд).
        Возвращает строку 'long' или 'short', либо None, если не найдено.
        """
        try:
            start_str = start_dt.strftime('%Y-%m-%d %H:%M:00')
            end_str = end_dt.strftime('%Y-%m-%d %H:%M:00')
            query = f"""
                SELECT direction
                FROM crypto_data.auto_ids
                WHERE timeframe = '{timeframe}'
                  AND abs(dateDiff('minute', toStartOfMinute(start_time), toStartOfMinute(toDateTime('{start_str}')))) <= {tolerance_minutes}
                  AND abs(dateDiff('minute', toStartOfMinute(end_time), toStartOfMinute(toDateTime('{end_str}')))) <= {tolerance_minutes}
                LIMIT 1
            """
            rows = ch_client.execute(query)
            if rows:
                return rows[0][0]
            return None
        except Exception as e:
            logger.error(f"[AutoLines] Ошибка получения направления по датам {start_dt}–{end_dt}: {e}")
            return None    

    def _get_price_from_db(self, ch_client, dt_str):
        """
        Возвращает цену close ближайшей свечи 1m к переданному времени.
        """
        try:
            dt = datetime.strptime(dt_str, '%Y-%m-%d %H:%M:%S')
            # Ищем предыдущую свечу
            query = f"""
                SELECT close FROM crypto_data.btc_usdt_1m
                WHERE timestamp <= '{dt.strftime('%Y-%m-%d %H:%M:%S')}'
                ORDER BY timestamp DESC LIMIT 1
            """
            rows = ch_client.execute(query)
            if rows:
                return float(rows[0][0])
            # Если нет, ищем следующую
            query2 = f"""
                SELECT close FROM crypto_data.btc_usdt_1m
                WHERE timestamp >= '{dt.strftime('%Y-%m-%d %H:%M:%S')}'
                ORDER BY timestamp ASC LIMIT 1
            """
            rows2 = ch_client.execute(query2)
            if rows2:
                return float(rows2[0][0])
            return None
        except Exception as e:
            logger.error(f"[AutoLines] Ошибка получения цены для {dt_str}: {e}")
            return None

    def _get_direction_for_id(self, ch_client, id_val, timeframe):
        """
        Возвращает направление тренда (long/short) для ID и указанного таймфрейма из auto_ids.
        """
        try:
            query = f"SELECT direction FROM crypto_data.auto_ids WHERE id = {id_val} AND timeframe = '{timeframe}' LIMIT 1"
            rows = ch_client.execute(query)
            if rows:
                return rows[0][0]
            return None
        except Exception as e:
            logger.error(f"[AutoLines] Ошибка получения направления для ID {id_val}, ТФ {timeframe}: {e}")
            return None

    def draw_slope_lines_from_chain(self, position_id, animal, ch_client=None, timeframe='1m',
                                    start_dt=None, end_dt=None):
        """
        Рисует наклонные линии цепочек для указанного ID и животного.
        Направление определяется по переданным датам start_dt/end_dt (если заданы)
        или по position_id (старый способ).
        """
        # === НОВАЯ ПРОВЕРКА ===
        if hasattr(self, 'current_position_id') and position_id != self.current_position_id:
            logger.debug(f"[НАКЛОННЫЕ ЛИНИИ] Пропуск отрисовки для ID {position_id}, текущий ID {self.current_position_id}")
            return

        cache_key = f"{position_id}_{animal}_{timeframe}"
        if hasattr(self, '_last_slope_cache') and self._last_slope_cache == cache_key:
            logger.debug(f"[НАКЛОННЫЕ ЛИНИИ] Пропускаем повторную отрисовку для {cache_key}")
            return

        self.clear_slope_lines()

        if ch_client is None:
            logger.warning("[НАКЛОННЫЕ ЛИНИИ] Не передан клиент БД, отрисовка невозможна")
            return

        self._last_slope_cache = cache_key

        if position_id is None or not animal:
            return

        if not hasattr(self, 'chain_manager') or self.chain_manager is None:
            logger.warning("[НАКЛОННЫЕ ЛИНИИ] ChainManager не найден")
            return

        chain = self.chain_manager.get_chain_for_id_and_animal(position_id, animal)
        if not chain:
            logger.info(f"[НАКЛОННЫЕ ЛИНИИ] Цепочка для ID {position_id}, животное {animal} не найдена")
            return

        chain_pairs = chain.get("chain_pairs", [])
        if not chain_pairs:
            logger.info(f"[НАКЛОННЫЕ ЛИНИИ] В цепочке для ID {position_id}, животное {animal} нет пар")
            return

        # Определяем направление
        direction = None
        if start_dt is not None and end_dt is not None:
            direction = self._get_direction_by_dates(ch_client, timeframe, start_dt, end_dt)
            if direction:
                logger.info(f"[НАКЛОННЫЕ ЛИНИИ] Направление по датам для ID {position_id}: {direction}")
        if direction is None:
            direction = self._get_direction_for_id(ch_client, position_id, timeframe)
            if direction:
                logger.info(f"[НАКЛОННЫЕ ЛИНИИ] Направление по ID для {position_id}: {direction}")

        if direction is None:
            logger.warning(f"[НАКЛОННЫЕ ЛИНИИ] Не удалось определить направление для ID {position_id}, ТФ {timeframe}, линии не рисуются")
            return

        base_color = 'green' if direction == 'long' else 'red'
        logger.info(f"[НАКЛОННЫЕ ЛИНИИ] ID {position_id} направление: {direction}, базовый цвет: {base_color}")

        self._drawn_pairs = set()
        if not hasattr(self, '_slope_label_data'):
            self._slope_label_data = []

        for pair in chain_pairs:
            left_id = pair["from_id"]
            right_id = pair["to_id"]
            pair_key = f"{min(left_id, right_id)}_{max(left_id, right_id)}"
            if pair_key in self._drawn_pairs:
                continue

            chain_type = pair.get("chain_type", "серия")
            line_type = pair.get("line_type", "главный")
            left_time_str = pair.get("from_time", "")
            right_time_str = pair.get("to_time", "")

            if not left_time_str or not right_time_str:
                continue

            left_price = self._get_price_from_db(ch_client, left_time_str)
            right_price = self._get_price_from_db(ch_client, right_time_str)
            if left_price is None or right_price is None:
                logger.warning(f"[НАКЛОННЫЕ ЛИНИИ] Не удалось получить цены для пары {left_id}→{right_id}, пропускаем")
                continue

            try:
                left_dt = datetime.strptime(str(left_time_str), '%Y-%m-%d %H:%M:%S')
                right_dt = datetime.strptime(str(right_time_str), '%Y-%m-%d %H:%M:%S')
                left_timestamp = left_dt.timestamp() * 1000
                right_timestamp = right_dt.timestamp() * 1000
            except Exception as e:
                logger.warning(f"[НАКЛОННЫЕ ЛИНИИ] Ошибка парсинга времени: {e}")
                continue

            if chain_type == "параллель":
                style = QtCore.Qt.PenStyle.SolidLine
            else:
                style = QtCore.Qt.PenStyle.CustomDashLine

            if base_color == "red":
                if line_type == "импульс":
                    line_color = (255, 140, 0, 200)
                else:
                    line_color = (255, 0, 0, 200)
            else:
                if line_type == "импульс":
                    line_color = (160, 32, 240, 200)
                else:
                    line_color = (0, 255, 0, 200)

            if style == QtCore.Qt.PenStyle.CustomDashLine:
                pen = pg.mkPen(color=line_color, width=1.5, style=QtCore.Qt.PenStyle.CustomDashLine)
                pen.setDashPattern([20, 15])
            else:
                pen = pg.mkPen(color=line_color, width=1.5, style=style)

            line = pg.PlotCurveItem(
                x=[left_timestamp, right_timestamp],
                y=[left_price, right_price],
                pen=pen,
                antialias=True
            )
            self.plot_widget.addItem(line)
            self.slope_line_items.append(line)
            self._drawn_pairs.add(pair_key)

            try:
                mid_x = (left_timestamp + right_timestamp) / 2
                mid_y = (left_price + right_price) / 2
                label_text = f"{left_id}→{right_id}"
                if chain_type == "параллель":
                    label_text += " (пар)"
                elif chain_type == "микс":
                    label_text += " (микс)"

                label = pg.TextItem(
                    text=label_text,
                    anchor=(0.5, 0.5),
                    angle=0,
                    color='white',
                    fill=(0, 0, 0, 180),
                    border=pg.mkPen(line_color, width=0.5)
                )
                label.setPos(mid_x, mid_y)
                self.plot_widget.addItem(label)
                self.slope_line_items.append(label)
                self._slope_label_data.append({
                    'label': label,
                    'left_timestamp': left_timestamp,
                    'right_timestamp': right_timestamp,
                    'left_price': left_price,
                    'right_price': right_price,
                    'sensitivity': 1.0
                })
                logger.debug(f"[НАКЛОННЫЕ ЛИНИИ] Добавлена линия {left_id}→{right_id}")
            except Exception as e_label:
                logger.warning(f"[НАКЛОННЫЕ ЛИНИИ] Ошибка создания метки: {e_label}")

        self._connect_view_range_changed()
        self.update_slope_label_angles()
        self.plot_widget.getViewBox().update()
        QtWidgets.QApplication.processEvents()
        logger.info(f"[НАКЛОННЫЕ ЛИНИИ] Отрисовано {len(self._drawn_pairs)} линий для ID {position_id}, животное {animal}")

    def update_slope_label_angles(self):
        """Обновляет углы наклона меток в соответствии с текущим масштабом графика"""
        # Объединяем данные из всех источников
        all_label_data = []
        if hasattr(self, '_slope_label_data'):
            all_label_data.extend(self._slope_label_data)
        if hasattr(self, '_branch_label_data'):
            all_label_data.extend(self._branch_label_data)
        if hasattr(self, '_group_label_data'):
            all_label_data.extend(self._group_label_data)
        
        if not all_label_data:
            return
        
        try:
            # Получаем текущий view range
            view_range = self.plot_widget.getViewBox().viewRange()
            if not view_range or len(view_range) < 2:
                return
            
            x_min, x_max = view_range[0]
            y_min, y_max = view_range[1]
            
            # Вычисляем масштаб осей (сколько пикселей на единицу)
            view_width = x_max - x_min
            view_height = y_max - y_min
            
            if view_width <= 0 or view_height <= 0:
                return
            
            # ⭐ РЕГУЛИРУЕМЫЙ ПАРАМЕТР: чувствительность угла к масштабу ⭐
            angle_sensitivity = 0.5  # уменьшите для менее крутых углов, увеличьте для более крутых
            
            for data in all_label_data:
                label = data['label']
                
                # Проверяем, является ли это вертикальной линией
                is_vertical = data.get('is_vertical', False)
                
                if is_vertical:
                    # Для вертикальных линий угол всегда близок к 90 градусам
                    # Используем индивидуальную чувствительность
                    sensitivity = data.get('sensitivity', 1.5)
                    angle = 90 * sensitivity
                    # Ограничиваем угол, чтобы не выходил за разумные пределы
                    angle = max(75, min(105, angle))
                else:
                    # Для наклонных линий используем существующую логику
                    left_x = data.get('left_timestamp')
                    right_x = data.get('right_timestamp')
                    left_y = data.get('left_price')
                    right_y = data.get('right_price')
                    
                    if left_x is None or right_x is None:
                        continue
                    
                    # Нормализуем координаты к экранным пикселям
                    norm_left_x = (left_x - x_min) / view_width
                    norm_right_x = (right_x - x_min) / view_width
                    norm_left_y = (left_y - y_min) / view_height
                    norm_right_y = (right_y - y_min) / view_height
                    
                    # Вычисляем угол в экранных координатах
                    delta_x = norm_right_x - norm_left_x
                    delta_y = norm_right_y - norm_left_y
                    
                    if abs(delta_x) < 1e-10:
                        angle = 90 if delta_y > 0 else -90
                    else:
                        angle = np.degrees(np.arctan2(delta_y, delta_x))
                        # Применяем чувствительность
                        sensitivity = data.get('sensitivity', 1.0)
                        angle = angle * sensitivity
                
                # Обновляем угол метки
                label.setAngle(angle)
            
            # Принудительно обновляем вид
            self.plot_widget.getViewBox().update()
            
        except Exception as e:
            print(f"[НАКЛОННЫЕ ЛИНИИ] Ошибка обновления углов: {str(e)}")

    def _connect_view_range_changed(self):
        """Подключает обработчик изменения масштаба к view box."""
        if hasattr(self, '_range_connected') and self._range_connected:
            return
        view_box = self.plot_widget.getViewBox()
        if view_box:
            view_box.sigRangeChanged.connect(self._on_view_range_changed)
            self._range_connected = True

    def _on_view_range_changed(self, vb, ranges):
        """Вызывается при изменении масштаба графика."""
        self.update_vertical_labels_position()
        self.update_slope_label_angles()
    
    def clear_lines(self):
        """Удаляет все вертикальные линии и метки автогрупп, но не очищает список меток."""
        for line in self.line_items:
            try:
                self.plot_widget.removeItem(line)
            except:
                pass
        self.line_items.clear()
        self.current_position_id = None
        # self._group_label_data НЕ очищается, он будет пересоздан при следующей отрисовке
    
    def clear_slope_lines(self):
        """Удаляет все наклонные линии и метки, сбрасывает ID и животное."""
        for item in self.slope_line_items:
            try:
                self.plot_widget.removeItem(item)
            except:
                pass
        self.slope_line_items.clear()
        self._last_slope_cache = None
        if hasattr(self, '_slope_label_data'):
            self._slope_label_data.clear()
        if hasattr(self, '_branch_label_data'):
            self._branch_label_data.clear()
        if hasattr(self, '_range_connected'):
            self._range_connected = False
        # _group_label_data не трогаем
    
    def draw_lines_for_position(self, position_id, auto_group_times, timeframe, show_labels=True, time_pairs_start=None, time_pairs_end=None):
        """Отрисовывает вертикальные линии авто-групп с однострочными метками (ID + время) по центру графика, увеличенный шрифт"""
        if self.current_position_id == position_id and self.line_items:
            return

        self.clear_lines()
        self.current_position_id = position_id

        limb_emojis = {
            "ХВОСТ": "🐕",
            "УСЫ": "🐱",
            "ОРГАН": "🐾"
        }

        def get_limb_name(group_num):
            if group_num in (1, 2):
                return "ХВОСТ"
            elif group_num in (3, 4):
                return "УСЫ"
            elif group_num in (5, 6):
                return "ОРГАН"
            else:
                return f"ГР.{group_num}"

        id_str = str(position_id)
        lines_drawn = 0
        labels_drawn = 0
        self._group_label_data.clear()

        view_box = self.plot_widget.getViewBox()
        view_range = view_box.viewRange()
        if view_range and len(view_range) >= 2:
            y_min, y_max = view_range[1]
        else:
            y_min, y_max = 0, 100000

        def format_timestamp(ts_ms):
            dt = datetime.fromtimestamp(ts_ms / 1000.0)
            return dt.strftime('%d.%m.%y %H:%M:%S')

        def add_line_and_label(group_num, timestamp, color, style, label_text_override=None):
            nonlocal lines_drawn, labels_drawn
            if timestamp is None:
                return

            line = pg.InfiniteLine(
                pos=timestamp,
                angle=90,
                pen=pg.mkPen(color, width=1.5, style=style, dash=[4, 4])
            )
            self.plot_widget.addItem(line)
            self.line_items.append(line)
            lines_drawn += 1

            if show_labels:
                try:
                    current_range = view_box.viewRange()
                    if current_range and len(current_range) >= 2:
                        cur_y_min, cur_y_max = current_range[1]
                    else:
                        cur_y_min, cur_y_max = y_min, y_max
                    view_height = cur_y_max - cur_y_min
                    if view_height > 0:
                        text_y_position = cur_y_min + view_height * 0.5
                    else:
                        text_y_position = cur_y_min

                    limb_name = get_limb_name(group_num)
                    emoji = limb_emojis.get(limb_name, "❓")
                    time_str = format_timestamp(timestamp)

                    if label_text_override:
                        label_text = f"{label_text_override} ID:{position_id} {time_str}"
                    else:
                        label_text = f"{emoji} {limb_name} {group_num} ID:{position_id} {time_str}"

                    label = pg.TextItem(
                        text=label_text,
                        anchor=(0.5, 0.5),
                        angle=90,
                        color='white',
                        fill=(0, 0, 0, 200),
                        border=pg.mkPen(color, width=0.5)
                    )
                    label.setPos(timestamp, text_y_position)

                    font = QtGui.QFont()
                    font.setPointSize(18)
                    font.setBold(True)
                    label.setFont(font)

                    self.plot_widget.addItem(label)
                    self.line_items.append(label)
                    labels_drawn += 1

                    self._group_label_data.append({
                        'label': label,
                        'timestamp': timestamp,
                        'y_position': text_y_position,
                        'group_num': group_num,
                        'is_vertical': True
                    })
                except Exception as e:
                    print(f"[АВТО-ЛИНИИ] Ошибка метки для группы {group_num}: {e}")

        for group_num in range(1, 9):
            if group_num == 7:
                if time_pairs_start is not None:
                    timestamp = time_pairs_start.timestamp() * 1000
                    color = self.group_colors.get(7, (255, 255, 255, 200))
                    style = self.group_styles.get(7, QtCore.Qt.PenStyle.DashLine)
                    add_line_and_label(7, timestamp, color, style, label_text_override="1️⃣ Единица 7 НАЧАЛО")
                continue
            elif group_num == 8:
                if time_pairs_end is not None:
                    timestamp = time_pairs_end.timestamp() * 1000
                    color = self.group_colors.get(8, (255, 255, 255, 200))
                    style = self.group_styles.get(8, QtCore.Qt.PenStyle.DashLine)
                    add_line_and_label(8, timestamp, color, style, label_text_override="1️⃣ Единица 8 КОНЕЦ")
                continue

            group_key = f'auto_group{group_num}_times'
            if group_key not in auto_group_times:
                continue
            group_data = auto_group_times[group_key]
            if timeframe not in group_data:
                continue
            if id_str not in group_data[timeframe]:
                continue
            time_str = group_data[timeframe][id_str]
            if not time_str:
                continue
            try:
                dt = datetime.strptime(time_str, '%Y-%m-%d %H:%M:%S')
                timestamp = dt.timestamp() * 1000
                color = self.group_colors.get(group_num, (255, 255, 255, 200))
                style = self.group_styles.get(group_num, QtCore.Qt.PenStyle.DashLine)
                add_line_and_label(group_num, timestamp, color, style)
            except Exception as e:
                print(f"[АВТО-ЛИНИИ] Ошибка группы {group_num}: {e}")

        self._connect_view_range_changed()
        print(f"[АВТО-ЛИНИИ] Отрисовано {lines_drawn} линий, {labels_drawn} меток для ID {position_id}")

    def update_vertical_labels_position(self):
        """Обновляет Y-позицию вертикальных меток при изменении масштаба (центрирование)"""
        if not self._group_label_data:
            return
        try:
            view_range = self.plot_widget.getViewBox().viewRange()
            if not view_range or len(view_range) < 2:
                return
            y_min, y_max = view_range[1]
            view_height = y_max - y_min
            if view_height <= 0:
                return
            new_y = y_min + view_height * 0.5
            for data in self._group_label_data:
                label = data.get('label')
                if label:
                    label.setPos(label.pos().x(), new_y)
        except Exception as e:
            print(f"[АВТО-ЛИНИИ] Ошибка обновления позиции меток: {e}")
    
    def draw_slope_lines_from_pass(self, position_id, correction_data, ch_client=None, timeframe='1m'):
        """
        Рисует наклонные линии на основе готовой цепочки из ChainManager
        (Замененная версия, совместимая со старыми вызовами)
        """
        import traceback
        traceback.print_stack(limit=5)
        
        # Если это та же позиция, ничего не делаем
        if hasattr(self, '_last_slope_position_id') and self._last_slope_position_id == position_id:
            print(f"[НАКЛОННЫЕ ЛИНИИ] Пропускаем повторную отрисовку для ID {position_id}")
            return
        
        # Очищаем предыдущие наклонные линии
        self.clear_slope_lines()
        
        # Запоминаем текущую позицию
        self._last_slope_position_id = position_id
        
        if position_id is None:
            return
        
        # Получаем готовую цепочку из ChainManager
        if not hasattr(self, 'chain_manager'):
            print(f"[НАКЛОННЫЕ ЛИНИИ] ❌ ChainManager не найден")
            return
        
        chain = self.chain_manager.get_chain_for_id(position_id)
        if not chain:
            print(f"[НАКЛОННЫЕ ЛИНИИ] ❌ Цепочка для ID {position_id} не найдена в ChainManager")
            return
        
        chain_pairs = chain.get("chain_pairs", [])
        
        # Инициализируем множество для отслеживания нарисованных пар
        self._drawn_pairs = set()
        
        # Рисуем линии для каждой пары из готовой цепочки
        for pair in chain_pairs:
            left_id = pair["from_id"]
            right_id = pair["to_id"]
            
            # Проверяем, не была ли уже нарисована эта пара
            pair_key = f"{min(left_id, right_id)}_{max(left_id, right_id)}"
            if pair_key in self._drawn_pairs:
                print(f"[НАКЛОННЫЕ ЛИНИИ] ⚠️ Пара {left_id}↔{right_id} уже нарисована, пропускаем")
                continue
            
            # Получаем данные из готовой пары
            chain_type = pair["chain_type"]
            base_color = pair["color"]
            line_type = pair["line_type"]
            left_time_str = pair["from_time"]
            right_time_str = pair["to_time"]
            left_price = pair["from_price"]
            right_price = pair["to_price"]
            
            # Парсим времена
            try:
                left_dt = datetime.strptime(str(left_time_str), '%Y-%m-%d %H:%M:%S')
                right_dt = datetime.strptime(str(right_time_str), '%Y-%m-%d %H:%M:%S')
                
                left_timestamp = left_dt.timestamp() * 1000
                right_timestamp = right_dt.timestamp() * 1000
            except Exception as e:
                print(f"[НАКЛОННЫЕ ЛИНИИ] ❌ Ошибка парсинга времени: {str(e)}")
                continue
            
            # Определяем стиль линии
            expected_style = QtCore.Qt.PenStyle.DashLine if chain_type == "серия" else QtCore.Qt.PenStyle.SolidLine
            style_name = "пунктирная" if chain_type == "серия" else "сплошная"
            
            # Определяем цвет линии
            if base_color == "red":
                if line_type == "импульс":
                    line_color = (255, 140, 0, 200)  # Оранжевый
                    color_name = "оранжевый"
                else:
                    line_color = (255, 0, 0, 200)    # Красный
                    color_name = "красный"
            elif base_color == "green":
                if line_type == "импульс":
                    line_color = (160, 32, 240, 200) # Фиолетовый
                    color_name = "фиолетовый"
                else:
                    line_color = (0, 255, 0, 200)    # Зеленый
                    color_name = "зеленый"
            else:
                line_color = (255, 255, 0, 200)      # Желтый
                color_name = "желтый"
            
            # СОЗДАЕМ ЛИНИЮ
            line = pg.PlotCurveItem(
                x=[left_timestamp, right_timestamp],
                y=[left_price, right_price],
                pen=pg.mkPen(
                    color=line_color,
                    width=1.5,
                    style=expected_style
                ),
                antialias=True
            )
            
            self.plot_widget.addItem(line)
            self.slope_line_items.append(line)
            
            # Запоминаем пару
            self._drawn_pairs.add(pair_key)
            
            # СОЗДАЕМ МЕТКУ
            try:
                mid_x = (left_timestamp + right_timestamp) / 2
                mid_y = (left_price + right_price) / 2
                
                label = pg.TextItem(
                    text=f"{left_id}→{right_id}",
                    anchor=(0.5, 0.5),
                    color='white',
                    fill=(0, 0, 0, 150),
                    border=pg.mkPen(line_color, width=0.5)
                )
                label.setPos(mid_x, mid_y)
                
                self.plot_widget.addItem(label)
                self.slope_line_items.append(label)
            except Exception as e_label:
                print(f"[НАКЛОННЫЕ ЛИНИИ] ⚠️ Ошибка создания метки: {str(e_label)}")

        self.plot_widget.getViewBox().update()
        QtWidgets.QApplication.processEvents()
    def on_timeframe_changed(self):
        """Вызывается при смене таймфрейма - очищаем линии"""

        self.clear_lines()
        self.clear_slope_lines()
        self.current_position_id = None
        # Очищаем сохраненный ID для наклонных линий
        if hasattr(self, '_last_slope_position_id'):
            print(f"[АВТО-ЛИНИИ] Сбрасываем _last_slope_position_id с {self._last_slope_position_id} на None")
            self._last_slope_position_id = None

    def _get_nearest_price(self, ch_client, target_dt, id_val):
        """Находит ближайшую цену из БД (как в оригинальном коде)"""
        try:
            # Сначала пробуем точное совпадение
            query = f"""
                SELECT close 
                FROM crypto_data.btc_usdt_1m 
                WHERE timestamp = '{target_dt.strftime('%Y-%m-%d %H:%M:%S')}'
                LIMIT 1
            """
            result = ch_client.execute(query)
            if result and len(result) > 0:
                return float(result[0][0])
            
            # Ищем ближайшее
            query_before = f"""
                SELECT timestamp, close 
                FROM crypto_data.btc_usdt_1m 
                WHERE timestamp <= '{target_dt.strftime('%Y-%m-%d %H:%M:%S')}'
                ORDER BY timestamp DESC
                LIMIT 1
            """
            result_before = ch_client.execute(query_before)
            
            query_after = f"""
                SELECT timestamp, close 
                FROM crypto_data.btc_usdt_1m 
                WHERE timestamp >= '{target_dt.strftime('%Y-%m-%d %H:%M:%S')}'
                ORDER BY timestamp ASC
                LIMIT 1
            """
            result_after = ch_client.execute(query_after)
            
            best_price = None
            best_diff = float('inf')
            
            if result_before and len(result_before) > 0:
                ts_before = result_before[0][0]
                price_before = float(result_before[0][1])
                diff_before = abs((ts_before - target_dt).total_seconds() / 60)
                if diff_before < best_diff:
                    best_diff = diff_before
                    best_price = price_before
            
            if result_after and len(result_after) > 0:
                ts_after = result_after[0][0]
                price_after = float(result_after[0][1])
                diff_after = abs((ts_after - target_dt).total_seconds() / 60)
                if diff_after < best_diff:
                    best_diff = diff_after
                    best_price = price_after
            
            if best_price is not None and best_diff <= 1:  # Допустимая разница 1 минута
                return best_price
            
            # ⭐ ИСПРАВЛЕНИЕ: Если цена не найдена в интервале, возвращаем последнюю свечу из базы ⭐
            query_last = """
                SELECT close 
                FROM crypto_data.btc_usdt_1m 
                ORDER BY timestamp DESC 
                LIMIT 1
            """
            result_last = ch_client.execute(query_last)
            if result_last and len(result_last) > 0:
                last_price = float(result_last[0][0])
                print(f"    [БД] Цена для ID {id_val} не найдена, используем последнюю свечу: {last_price:.2f}")
                return last_price
            
        except Exception as e:
            print(f"    [БД] Ошибка поиска цены для ID {id_val}: {str(e)}")
        
        # Если даже последнюю свечу не удалось получить, возвращаем 50000 как запасной вариант
        print(f"    [БД] Критическая ошибка для ID {id_val}, возвращаем 50000")
        return 50000

class ForceManager(QtCore.QThread):
    """
    Вычисляет силу в отдельном потоке.
    Сила = разница между экстремумом (max для long, min для short) на интервале
    от конца тренда до сигнала и ценой в конце тренда.
    """
    finished_signal = QtCore.pyqtSignal(float, str)  # (сила, ошибка)
    progress_signal = QtCore.pyqtSignal(str)

    def __init__(self, ch_config, timeframe, end_time, signal_time, direction, real_id=None):
        """
        ch_config: dict с параметрами ClickHouse
        timeframe: str, таймфрейм для данных (рекомендуется '1m')
        end_time: datetime, время конца тренда
        signal_time: datetime, время сигнала
        direction: str, 'long' или 'short'
        real_id: int or None, реальный ID из БД (для логирования)
        """
        super().__init__()
        self.ch_config = ch_config
        self.timeframe = timeframe
        self.end_time = end_time
        self.signal_time = signal_time
        self.direction = direction
        self.real_id = real_id
        self._client = None
        self._is_running = True

    def run(self):
        try:
            self._client = ClickHouseClient(
                host=self.ch_config['host'],
                port=self.ch_config['port'],
                user=self.ch_config['user'],
                password=self.ch_config['password'],
                settings={'connect_timeout': 10}
            )
            id_info = f" (реальный ID {self.real_id})" if self.real_id else ""
            logger.info(f"[FORCE] Начало расчёта силы{id_info}, направление {self.direction}, сигнал {self.signal_time}, конец тренда {self.end_time}")

            tf_minutes = {'30m': 30, '1h': 60, '4h': 240}[self.timeframe]
            left_dt = self.end_time - timedelta(minutes=3 * tf_minutes)

            if self.direction == 'long':
                start_max = min(left_dt, self.signal_time)
                end_max = max(left_dt, self.signal_time)
                start_min = left_dt
                end_min = self.end_time
            else:  # 'short'
                start_max = left_dt
                end_max = self.end_time
                start_min = min(left_dt, self.signal_time)
                end_min = max(left_dt, self.signal_time)

            logger.info(f"[FORCE] Максимум ищем на [{start_max} – {end_max}]")
            logger.info(f"[FORCE] Минимум ищем на [{start_min} – {end_min}]")

            query_max = f"""
                SELECT max(high)
                FROM crypto_data.btc_usdt_1m
                WHERE timestamp >= '{start_max.strftime('%Y-%m-%d %H:%M:%S')}'
                  AND timestamp <= '{end_max.strftime('%Y-%m-%d %H:%M:%S')}'
            """
            query_min = f"""
                SELECT min(low)
                FROM crypto_data.btc_usdt_1m
                WHERE timestamp >= '{start_min.strftime('%Y-%m-%d %H:%M:%S')}'
                  AND timestamp <= '{end_min.strftime('%Y-%m-%d %H:%M:%S')}'
            """
            rows_max = self._client.execute(query_max)
            rows_min = self._client.execute(query_min)

            if not rows_max or rows_max[0][0] is None or not rows_min or rows_min[0][0] is None:
                logger.warning("[FORCE] Нет данных")
                self.finished_signal.emit(0.0, "Нет данных")
                return

            max_high = float(rows_max[0][0])
            min_low = float(rows_min[0][0])
            force = max_high - min_low
            force = round(force, 2)

            logger.info(f"[FORCE] max_high={max_high:.2f}, min_low={min_low:.2f}, сила={force:.2f}")
            self.finished_signal.emit(force, "")

        except Exception as e:
            logger.error(f"[FORCE] Ошибка: {str(e)}", exc_info=True)
            self.finished_signal.emit(0.0, str(e))
        finally:
            if self._client:
                try:
                    self._client.disconnect()
                except:
                    pass

    def stop(self):
        self._is_running = False

    def _get_price_at(self, dt):
        """Возвращает цену close ближайшей свечи к dt (в пределах 2 минут)."""
        try:
            query = f"""
                SELECT close
                FROM crypto_data.btc_usdt_1m
                WHERE timestamp >= '{dt.strftime('%Y-%m-%d %H:%M:%S')}'
                ORDER BY timestamp LIMIT 1
            """
            rows = self._client.execute(query)
            if rows:
                return float(rows[0][0])
            # Попробуем предыдущую
            query2 = f"""
                SELECT close
                FROM crypto_data.btc_usdt_1m
                WHERE timestamp <= '{dt.strftime('%Y-%m-%d %H:%M:%S')}'
                ORDER BY timestamp DESC LIMIT 1
            """
            rows2 = self._client.execute(query2)
            if rows2:
                return float(rows2[0][0])
            return None
        except Exception as e:
            logger.error(f"[FORCE] Ошибка получения цены для {dt}: {e}")
            return None

class ImpulseSqlWorker(QtCore.QThread):
    finished_signal = QtCore.pyqtSignal(str)

    def __init__(self, parent, timeframe):
        super().__init__(parent)
        self.timeframe = timeframe
        self.parent = parent

    def run(self):
        self.parent._do_impulse_sql_worker(self.timeframe, self.finished_signal)        

