            table.setItem(i, 8, QtWidgets.QTableWidgetItem(f"{res['total_cat']:.1f}"))
            table.setItem(i, 9, QtWidgets.QTableWidgetItem(f"{res['total_manul']:.1f}"))
            table.setItem(i, 10, QtWidgets.QTableWidgetItem(f"{res['diff_dog']:+.1f}"))
            table.setItem(i, 11, QtWidgets.QTableWidgetItem(f"{res['diff_cat']:+.1f}"))
            table.setItem(i, 12, QtWidgets.QTableWidgetItem(f"{res['diff_manul']:+.1f}"))
            table.setItem(i, 13, QtWidgets.QTableWidgetItem(str(res['pairs_used'])))
